(window.FREALLY_I18N = window.FREALLY_I18N || {})["hi"] = {"hero.headline":"<span class=\"hl-muted\">एक खोज।</span> <span class=\"hl-bright\">हर स्रोत। हर OS।</span>","hero.sub":"टाइप करते-करते कोई भी फ़ाइल ढूँढें: उसके नाम से, उसके भीतर के शब्दों से, वह कैसी सुनाई देती है उससे, उसका हेडर क्या कहता है उससे, या ऐसे नाम से जो आपको याद नाम से बस मिलता-जुलता हो।","hero.chipApp":"डेस्कटॉप ऐप","hero.chipCli":"कमांड लाइन","hero.chipLanguages":"18 भाषाएँ","what.title":"यह क्या है","what.p1":"हर ऑपरेटिंग सिस्टम में एक खोज बॉक्स होता है, और हर एक अपने ढंग से कम पड़ता है। voidtools के Everything ने बरसों पहले Windows पर फ़ाइल नाम खोज को तुरंत बना दिया, और वह Windows पर ही रहा।","what.p2":"Freally Sourcerer, Windows, macOS और Linux के लिए उसी तरह की खोज है। यह आपकी डिस्कों का एक ही इंडेक्स रखता है, जिसे हर सिस्टम का फ़ाइल परिवर्तनों का अपना रिकॉर्ड ताज़ा रखता है — Windows पर NTFS change journal, macOS पर FSEvents, Linux पर inotify और fanotify — इसलिए नई और नाम बदली गई फ़ाइलें बिना दोबारा स्कैन किए मिल जाती हैं।","what.p3":"फिर यह नाम से आगे भी पढ़ता है। एक ही क्वेरी नाम के बारे में, दस्तावेज़ के भीतर के टेक्स्ट के बारे में, ऑडियो फ़ाइल की मापी गई प्रबलता के बारे में, कोई छवि या प्रोग्राम अपने हेडर में अपने बारे में क्या कहता है उसके बारे में, और आपके टाइप किए से बस मिलते-जुलते नामों के बारे में पूछ सकती है।","features.title":"इसमें क्या है","features.filename.title":"फ़ाइल नाम, तुरंत","features.filename.body":"सबस्ट्रिंग, वाइल्डकार्ड, रेगुलर एक्सप्रेशन, AND, OR और NOT, और आकार, तिथि, एक्सटेंशन और पथ के लिए Everything के अपने मॉडिफ़ायर — टाइप करते ही इंडेक्स से उत्तर।","features.content.title":"फ़ाइलों के भीतर का टेक्स्ट","features.content.body":"PDF, Word, Excel और PowerPoint फ़ाइलों, Markdown, 32 भाषाओं के सोर्स कोड, JSON, CSV और YAML, और मेल में पूर्ण-टेक्स्ट खोज, और आर्काइव को खोले बिना उनके भीतर भी।","features.audio.title":"ऑडियो, उसकी आवाज़ के अनुसार","features.audio.body":"ऑडियो को LUFS में मापी गई प्रबलता, true peak, मौन, dynamic range, अवधि, codec और sample rate से ढूँढें — किसी के टाइप किए टैग से नहीं।","features.properties.title":"फ़ाइल अपने बारे में क्या कहती है","features.properties.body":"फ़ाइल हेडर से पढ़े गए बहत्तर गुण: छवि का आकार और कैमरा, वीडियो का codec और अवधि, दस्तावेज़ का लेखक और पेज, प्रोग्राम का आर्किटेक्चर और हस्ताक्षर, और भी बहुत कुछ।","features.similar.title":"बस मिलते-जुलते नाम","features.similar.body":"समानता लेंस आपके टाइप किए के क़रीब के नाम ढूँढता है — कोई टाइपो, कोई संस्करण संख्या, कोई अलग prefix — और जिस खोज में कुछ नहीं मिलता, वह सबसे निकट का असली नाम सुझाती है।","features.everything.title":"Everything से आए हैं तो घर जैसा लगेगा","features.everything.body":"Everything का खोज सिंटैक्स यहाँ भी काम करता है, और उसकी फ़ाइल सूचियाँ खुलती भी हैं और निर्यात भी होती हैं, इसलिए किसी ड्राइव का कैटलॉग दोनों के बीच आ-जा सकता है।","features.results.title":"जो मिले, उस पर काम करें","features.results.body":"खोलें, फ़ोल्डर में दिखाएँ, कॉपी करें, पूरे परिणाम सेट का नाम पूर्वावलोकन के साथ बदलें और उसे पूर्ववत करें, डुप्लिकेट और ख़ाली फ़ोल्डर ढूँढें, और अपने ख़ुद के कमांड चलाएँ।","features.platforms.title":"एक ऐप, तीन सिस्टम","features.platforms.body":"Windows, macOS और Linux पर वही ऐप, वही क्वेरी भाषा और वही इंडेक्स, scripts के लिए कमांड लाइन, और अठारह भाषाएँ।","ladder.title":"1.0 की ओर रास्ता","ladder.intro":"हर संस्करण के लिए एक पंक्ति। 0.23 के बाद के संस्करण योजना हैं, उसी क्रम में जिसमें वे बनाए जाएँगे।","ladder.rung.v0.19.84":"पहला सार्वजनिक बिल्ड: हर सिस्टम के अपने change journal से ताज़ा रहने वाली फ़ाइल नाम खोज, क्वेरी भाषा, ऐप और उसकी सेटिंग — Windows, macOS और Linux पर, अठारह भाषाओं में।","ladder.rung.v0.21.0":"अनिवार्य फ़ीचर्स, 3 में से भाग 1: डुप्लिकेट, ख़ाली फ़ोल्डर, Everything की फ़ाइल सूचियाँ, और right-click मेनू से किसी परिणाम पर हर क्रिया।","ladder.rung.v0.22.0":"अनिवार्य फ़ीचर्स, 3 में से भाग 2: इंडेक्स डिस्क के साथ लाइव चलता है, सूचकांक स्वास्थ्य, पूर्ववत करने की सुविधा के साथ थोक में नाम बदलना, अनप्लग की गई ड्राइवें जो खोजने योग्य बनी रहती हैं, और scripts के लिए कमांड लाइन।","ladder.rung.v0.23.0":"अनिवार्य फ़ीचर्स, 3 में से भाग 3, और स्थिर रिलीज़: पोर्टेबल मोड, पूर्वावलोकन में ऑडियो और वीडियो, त्वरित झलक, रेगुलर एक्सप्रेशन बिल्डर, और उन फ़ोल्डरों की रिपोर्ट जिन्हें खोज देख नहीं पाती। इसकी सुधार रिलीज़, 0.23.2, वर्तमान संस्करण है।","ladder.rung.v0.24.0":"छवियों और वीडियो के लिए गुण लेंस: आयाम, कैमरा डेटा, codecs और अवधि — खोजने योग्य, और कॉलम के रूप में दिखने वाले।","ladder.rung.v0.25.0":"दस्तावेज़ों, प्रोग्रामों और पैकेजों के लिए गुण लेंस: लेखक और पेज संख्या, आर्किटेक्चर और हस्ताक्षर, इंस्टॉलर, शॉर्टकट, आर्काइव, फ़ॉन्ट, मेल और डेटाबेस।","ladder.rung.v0.26.0":"संगीत टैग, और ऑडियो के साथ काम करने वालों के लिए और भी बहुत कुछ।","ladder.rung.v0.27.0":"डुप्लिकेट और डिस्क की सफ़ाई।","ladder.rung.v0.28.0":"आपकी फ़ाइलों के लिए टैग, नोट्स और कलेक्शन।","ladder.rung.v0.29.0":"पावर खोज: मैक्रो, स्नैपशॉट, मॉनिटर और फ़ाइल हैश।","ladder.rung.v0.30.0":"व्यू और विंडो।","ladder.rung.v0.31.0":"एक लॉन्चर, और आपके ऑपरेटिंग सिस्टम से गहरा जुड़ाव।","ladder.rung.v0.32.0":"कमांड लाइन, टर्मिनल इंटरफ़ेस और ऑटोमेशन।","ladder.rung.v0.33.0":"आपके लोकल नेटवर्क में खोज, कैटलॉग, और पावर उपयोगकर्ताओं के लिए इंडेक्स उपकरण।","ladder.rung.v1.0.0":"कोड और ज्ञान लेंस, और रिलीज़: संस्करण 1.0।","ladder.note":"जो संस्करण पूरा हो चुका है वह बना और टैग किया गया है। यह डाउनलोड नहीं है: अभी कोई नहीं है, और 1.0.0 तक कोई नहीं होगा।","honest.title":"वे बातें जिन्हें ज़्यादातर साइटें सबसे नीचे रखती हैं","honest.firstIndex.title":"macOS और Linux पर पहला इंडेक्स ज़्यादा समय लेता है","honest.firstIndex.body":"Windows पर NTFS change journal की वजह से पूरा वॉल्यूम जल्दी इंडेक्स हो जाता है। macOS और Linux में ऐसा कुछ नहीं है, इसलिए वहाँ पहला इंडेक्स हर फ़ोल्डर से होकर गुज़रता है: बड़ी डिस्क पर सेकंड नहीं, मिनट। उसके बाद सिस्टम के अपने परिवर्तन events उसे ताज़ा रखते हैं।","honest.network.title":"क्या ऑनलाइन जाता है, और क्या कभी नहीं","honest.network.body":"कोई टेलीमेट्री नहीं है, और आपकी फ़ाइलों या खोजों के बारे में कुछ भी कहीं नहीं भेजा जाता। ऐप अपने-आप केवल एक काम के लिए ऑनलाइन जाता है: यह पूछने के लिए कि क्या कोई नया संस्करण है — दिन में एक बार, जब तक आप इसे न बदलें — और आप इसे बंद कर सकते हैं। बग रिपोर्ट तभी भेजी जाती है जब आप उसे भेजना चुनें, और वह भी यह देख लेने के बाद कि उसमें क्या है।","honest.unreadable.title":"जो यह नहीं देख पाता, वह बताता है","honest.unreadable.body":"जो फ़ोल्डर पढ़ा नहीं जा सका, वह बिल्कुल ख़ाली फ़ोल्डर जैसा दिखता है। चुपचाप कम परिणाम लौटाने के बजाय, Sourcerer उन फ़ोल्डरों की सूची देता है जिन्हें उसे छोड़ना पड़ा, कारण और आपके सिस्टम के लिए सुधार के साथ।","honest.lenses.title":"पाँच में से दो लेंस अभी जुड़े नहीं हैं","honest.lenses.body":"सामग्री लेंस, जो फ़ाइलों के भीतर का टेक्स्ट पढ़ता है, और समानता लेंस, जो बस मिलते-जुलते नाम ढूँढता है, बन चुके हैं पर अभी खोजों का उत्तर नहीं देते। आज फ़ाइल नाम, ऑडियो और गुण लेंस उत्तर देते हैं। बाकी दो को जोड़ना 1.0 की ओर रास्ते का हिस्सा है।","honest.downloads.title":"1.0.0 से पहले कोई डाउनलोड नहीं है","honest.downloads.body":"इस पन्ने पर न कोई बीटा, न कोई प्रीव्यू बिल्ड, न अर्ली एक्सेस। संस्करण 1.0.0 पहला संस्करण होगा जिसे यह साइट देगी।","site.tagline":"एक खोज। हर स्रोत। हर OS।","footer.licence":"स्वामित्व वाला — सर्वाधिकार सुरक्षित। © Mike Weaver. आज उपयोग के लिए मुफ़्त; भविष्य के संस्करण बेचे जा सकते हैं। ओपन सोर्स नहीं।","footer.everything":"Everything, voidtools का ट्रेडमार्क है, जिसका नाम यहाँ केवल तुलना के लिए लिया गया है। Freally Sourcerer का voidtools से कोई संबंध नहीं है।","featuresPage.lead":"Windows, macOS और Linux पर हर फ़ाइल के लिए एक खोज पट्टी: नाम, दस्तावेज़ों के भीतर का टेक्स्ट, आवाज़ के अनुसार ऑडियो, फ़ाइल का अपना हेडर क्या कहता है, और बस मिलते-जुलते नाम — एक ही इंडेक्स से, जो ख़ुद को ताज़ा रखता है।","featuresPage.version":"यह पन्ना Freally Sourcerer संस्करण 1.0 के बारे में है: इस पर लिखा सब कुछ 1.0 में है, और 1.0 के बाद के लिए नियोजित कुछ भी इस पर नहीं है।","featuresPage.numbers.intro":"हर आँकड़ा ऐप के अपने कोड और उसके परिवर्तनों के रिकॉर्ड से गिना गया है। कुछ भी बढ़ाकर पूर्णांकित नहीं किया गया।","featuresPage.numbers.lenses":"एक ही इंडेक्स में खोजने के तरीके: फ़ाइल नाम, सामग्री, ऑडियो, गुण और मिलते-जुलते नाम","featuresPage.numbers.properties":"हेडर से पढ़े जाने वाले फ़ाइल गुण","featuresPage.numbers.code":"प्रोग्रामिंग भाषाएँ, जिन्हें इसकी सामग्री खोज पढ़ती है","featuresPage.numbers.audioTypes":"ऑडियो फ़िल्टर में ऑडियो फ़ाइल प्रकार","featuresPage.numbers.matchModes":"मिलान मोड, केस मिलाएँ से लेकर विराम-चिह्न अनदेखा करें तक","featuresPage.numbers.systems":"ऑपरेटिंग सिस्टम: Windows, macOS और Linux","featuresPage.numbers.languages":"भाषाएँ","featuresPage.numbers.price":"आज की क़ीमत","featuresPage.free.title":"आज मुफ़्त","featuresPage.free.body":"Sourcerer आज जो कुछ भी करता है, वह सबके लिए मुफ़्त है: न कोई पेड टियर, न सदस्यता, और न कोई ट्रायल जो ख़त्म हो जाए।","featuresPage.cards.title":"संस्करण 1.0 क्या करता है","featuresPage.cards.index.title":"हर डिस्क का लाइव इंडेक्स","featuresPage.cards.index.body":"आपकी सभी ड्राइवों पर एक इंडेक्स, जिसे हर सिस्टम की अपनी परिवर्तन-धारा ताज़ा रखती है — Windows पर NTFS change journal, macOS पर FSEvents, Linux पर inotify और fanotify — इसलिए नई, नाम बदली गई और हटाई गई फ़ाइलें बिना दोबारा स्कैन किए दिखती हैं। अनप्लग की गई ड्राइव खोजने योग्य बनी रहती है, और उसके परिणाम बताते हैं कि वे किस ड्राइव पर हैं।","featuresPage.cards.names.title":"फ़ाइल नाम, ठीक वैसे जैसे Everything ढूँढता है","featuresPage.cards.names.body":"सबस्ट्रिंग, वाइल्डकार्ड, रेगुलर एक्सप्रेशन, AND, OR, NOT और समूहीकरण, आकार, तिथि, एक्सटेंशन, विशेषताओं और पथ के लिए Everything के मॉडिफ़ायर और वर्तनी के साथ, और सात मिलान मोड — केस मिलाएँ से लेकर विराम-चिह्न अनदेखा करें तक, और चीनी, जापानी व कोरियाई नामों को उनके उच्चारण से मिलाना भी।","featuresPage.cards.content.title":"फ़ाइलों के भीतर का टेक्स्ट","featuresPage.cards.content.body":"PDF, Word, Excel और PowerPoint फ़ाइलों, सादे टेक्स्ट और Markdown, 32 भाषाओं के सोर्स कोड, JSON, CSV और YAML, और मेल में पूर्ण-टेक्स्ट खोज, और zip, 7z व tar आर्काइव को खोले बिना उनके भीतर भी। एक व्यूअर हर मिलान को संदर्भ सहित एक-एक करके दिखाता है।","featuresPage.cards.audio.title":"ऑडियो, उसकी आवाज़ के अनुसार","featuresPage.cards.audio.body":"टैग से नहीं, माप से: LUFS में प्रबलता, true peak, मौन, dynamic range, अवधि, codec, sample rate और channels। प्रबलता या अवधि के अनुसार क्रमबद्ध करें, और सूची छोड़े बिना पूर्वावलोकन में फ़ाइल चलाएँ।","featuresPage.cards.properties.title":"फ़ाइल अपने बारे में क्या कहती है","featuresPage.cards.properties.body":"फ़ाइल हेडर से पढ़े गए बहत्तर गुण, जिन्हें किसी भी दूसरे मॉडिफ़ायर की तरह खोजा जा सकता है: छवि का आकार और कैमरा डेटा, वीडियो का codec और अवधि, दस्तावेज़ का लेखक और पेज संख्या, प्रोग्राम का आर्किटेक्चर और हस्ताक्षर, इंस्टॉलर संस्करण, शॉर्टकट के लक्ष्य, आर्काइव की सामग्री, फ़ॉन्ट, मेल हेडर और डेटाबेस तालिकाएँ। इनमें से कोई भी कॉलम बन सकता है।","featuresPage.cards.similar.title":"बस मिलते-जुलते नाम","featuresPage.cards.similar.body":"समानता लेंस आपके टाइप किए के क़रीब के नाम ढूँढता है — कोई टाइपो, कोई संस्करण संख्या, कोई अलग prefix — और जिस खोज में कुछ नहीं मिलता, वह सबसे निकट का असली नाम एक-क्लिक सुधार के रूप में सुझाती है।","featuresPage.cards.results.title":"किसी परिणाम के साथ आप जो कुछ भी करते हैं","featuresPage.cards.results.body":"खोलें, फ़ोल्डर में दिखाएँ, इससे खोलें, पथ, नाम, सामग्री या फ़ाइल को ही कॉपी करें, वहाँ टर्मिनल खोलें, और अपने परिभाषित कमांड चलाएँ। Space त्वरित झलक खोलता है, ऑडियो और वीडियो पूर्वावलोकन में चलते हैं, और परिणाम-संख्या पूरे सेट के आँकड़े खोलती है।","featuresPage.cards.rename.title":"नाम बदलें, पूर्ववत करें, व्यवस्थित करें","featuresPage.cards.rename.body":"खोजें और बदलें, रेगुलर एक्सप्रेशन, गणक और केस बदलाव से पूरे परिणाम सेट का नाम बदलें — पहले पूर्वावलोकन, और अगर दो नाम टकराएँ तो इनकार। पूर्ववत करें नाम बदलने को उलट देता है, रीस्टार्ट के बाद भी। डुप्लिकेट और ख़ाली फ़ोल्डर सीधे इंडेक्स से ढूँढें।","featuresPage.cards.everything.title":"Everything से आए हैं तो घर जैसा लगेगा","featuresPage.cards.everything.body":"Everything का खोज सिंटैक्स, क्विक फ़िल्टर और फ़ाइल सूचियाँ — आयात और निर्यात दोनों — और साथ में CSV, सादा टेक्स्ट, प्लेलिस्ट और NDJSON। एक strict मोड जाँचता है कि क्वेरी केवल वही उपयोग करे जो Everything समझता है।","featuresPage.cards.cli.title":"scripts के लिए कमांड लाइन","featuresPage.cards.cli.body":"freally कमांड वही क्वेरी भाषा बोलता है, JSON, NDJSON, CSV या NUL से अलग किए पथ छापता है, सार्थक exit codes लौटाता है, और bash, zsh, fish और PowerShell में completion देता है।","featuresPage.cards.portable.title":"चाहें तो पोर्टेबल","featuresPage.cards.portable.body":"इसे USB स्टिक से चलाएँ: इंडेक्स, सेटिंग, बुकमार्क और लॉग ऐप के बगल में एक Data फ़ोल्डर में रहते हैं, और जिस कंप्यूटर में स्टिक लगाई गई है उसमें कुछ भी पंजीकृत नहीं होता।","featuresPage.cards.languages.title":"अठारह भाषाएँ, हल्की या गहरी थीम","featuresPage.cards.languages.body":"मेनू, सेटिंग और हर डायलॉग की भाषा तुरंत बदल जाती है, और अरबी दाएँ से बाएँ लेआउट होती है। ऐप आपके सिस्टम की हल्की या गहरी थीम का अनुसरण करता है, या आपकी चुनी हुई थीम बनाए रखता है।","featuresPage.compare.title":"व्यावसायिक औज़ारों के साथ आमने-सामने","featuresPage.compare.intro":"Freally Sourcerer 1.0, आज लोगों द्वारा उपयोग किए जाने वाले व्यावसायिक डेस्कटॉप खोज औज़ारों के साथ। किसी दूसरे उत्पाद का हर ख़ाना उसके निर्माता के अपने पन्नों से लिया गया है, जिन्हें 2 अक्टूबर 2026 को जाँचा गया, और क़ीमतें अक्टूबर 2026 की US सूची क़ीमतें हैं — सिवाय वहाँ के जहाँ निर्माता कोई US क़ीमत नहीं दिखाता, और वह ख़ाना यह बताता है।","featuresPage.compare.feature":"फ़ीचर","featuresPage.compare.note.beta":"बीटा में","featuresPage.compare.row.price":"क़ीमत (USD, अक्टूबर 2026)","featuresPage.compare.freeToday":"आज मुफ़्त","featuresPage.compare.note.freeware":"फ़्रीवेयर","featuresPage.compare.note.oneTime":"एक बार","featuresPage.compare.note.perYear":"प्रति वर्ष, Basic","featuresPage.compare.legend.unknown":"सत्यापित नहीं","featuresPage.compare.note.euros":"एक बार, केवल यूरो में","featuresPage.compare.row.systems":"Windows, macOS और Linux","featuresPage.compare.legend.yes":"उपलब्ध","featuresPage.compare.legend.partly":"आंशिक","featuresPage.compare.row.liveIndex":"फ़ाइलें बदलने के साथ ताज़ा रहने वाले इंडेक्स से नाम द्वारा फ़ाइलें ढूँढता है","featuresPage.compare.note.scheduled":"इंडेक्स तय समय पर अपडेट होता है","featuresPage.compare.note.spotlight":"Spotlight का इंडेक्स","featuresPage.compare.note.chosenFolders":"आपके चुने फ़ोल्डर","featuresPage.compare.row.content":"PDF और Office फ़ाइलों जैसे दस्तावेज़ों के भीतर का टेक्स्ट खोजता है","featuresPage.compare.note.notIndexed":"इंडेक्स नहीं, धीमा","featuresPage.compare.row.audio":"मापी गई प्रबलता, codec, sample rate या अवधि से ऑडियो ढूँढता है","featuresPage.compare.note.noLoudness":"प्रबलता नहीं","featuresPage.compare.note.tagsBitRate":"टैग और bit rate","featuresPage.compare.note.mp3Tags":"MP3 और FLAC टैग","featuresPage.compare.row.properties":"फ़ाइल का हेडर जो कहता है उसे खोजता है: छवि का आकार, कैमरा, लेखक, पेज संख्या","featuresPage.compare.note.exifIptc":"EXIF और IPTC","featuresPage.compare.row.similar":"बस मिलते-जुलते नाम से फ़ाइल ढूँढता है","featuresPage.compare.note.similarWords":"दस्तावेज़ों में मिलते-जुलते शब्द","featuresPage.compare.row.cli":"खोज के लिए कमांड लाइन","featuresPage.compare.row.portable":"इंस्टॉल किए बिना, USB स्टिक से चलता है","featuresPage.compare.row.duplicates":"डुप्लिकेट फ़ाइलें ढूँढता है","featuresPage.compare.legend.no":"उपलब्ध नहीं","featuresPage.compare.summaryTitle":"संक्षेप में","featuresPage.compare.summary":"संक्षेप में: यह सब केवल Sourcerer में है — तीनों सिस्टम, लाइव इंडेक्स, दस्तावेज़ों के भीतर का टेक्स्ट, प्रबलता के अनुसार ऑडियो, फ़ाइल का हेडर क्या कहता है, और बस मिलते-जुलते नाम।","featuresPage.compare.theyWinTitle":"वे कहाँ आगे हैं","featuresPage.compare.theyWin":"जहाँ वे आगे हैं: Everything की कोई क़ीमत नहीं है, और उसका 1.5 बीटा फ़ाइलों को उनके hash से भी ढूँढता है; FileLocator Pro, Outlook की मेल फ़ाइलें खोजता है; Copernic, Google Drive, Dropbox और OneDrive में भी खोजता है; और DocFetcher Pro दस्तावेज़ों के भीतर आपके टाइप किए शब्दों से मिलते-जुलते शब्द ढूँढता है।","featuresPage.compare.asOf":"Sourcerer का कॉलम संस्करण 1.0 का है, जो अभी जारी नहीं हुआ है, और उसकी क़ीमत आज की है: Sourcerer आज मुफ़्त है, और भविष्य के संस्करण बेचे जा सकते हैं। दूसरे उत्पाद भी बदलते हैं; यह तालिका 2 अक्टूबर 2026 की स्थिति दिखाती है।","featuresPage.why.title":"यह ऐसे क्यों बना है","featuresPage.why.journal.title":"यह दोबारा स्कैन करने के बजाय सुनता है","featuresPage.why.journal.body":"हर सिस्टम पहले से अपनी फ़ाइलों में हुए परिवर्तन दर्ज करता है। Sourcerer टाइमर पर आपके फ़ोल्डरों से गुज़रने के बजाय वही रिकॉर्ड पढ़ता है, इसलिए डिस्क को फिर से पढ़े बिना इंडेक्स ताज़ा रहता है।","featuresPage.why.lazy.title":"यह केवल उतना पढ़ता है जितना सवाल को चाहिए","featuresPage.why.lazy.body":"किसी फ़ाइल के गुण तब पढ़े जाते हैं जब पहली बार कोई खोज उसके बारे में पूछती है, केवल उसके हेडर से, और फ़ाइल बदलने तक रखे जाते हैं। छवि कितनी चौड़ी है, इसका उत्तर देने के लिए न कोई तस्वीर डिकोड होती है, न किसी डेटाबेस की पंक्तियाँ खुलती हैं।","featuresPage.why.honest.title":"जो यह नहीं देख पाता, वह कहता है","featuresPage.why.honest.body":"जो फ़ोल्डर पढ़ा नहीं जा सका, वह बिल्कुल ख़ाली फ़ोल्डर जैसा दिखता है, इसलिए Sourcerer छोड़े गए फ़ोल्डरों के नाम और कारण बताता है। जो गिनती अपनी सीमा तक पहुँच गई, वह न्यूनतम के रूप में दिखाई जाती है, कभी सटीक संख्या के रूप में नहीं।","featuresPage.why.careful.title":"यह आपकी फ़ाइलों के साथ सावधान रहता है","featuresPage.why.careful.body":"नाम बदलने का पहले पूर्वावलोकन होता है और वह या तो एक साथ पूरा होता है या बिल्कुल नहीं, हटाई गई फ़ाइल Trash या Recycle Bin में जाती है, और आपका अपना कमांड एक बार आपसे पूछने के बाद तर्कों वाले प्रोग्राम के रूप में चलता है, कभी shell पंक्ति के रूप में नहीं।","featuresPage.why.local.title":"यह आपकी मशीन पर ही रहता है","featuresPage.why.local.body":"कोई टेलीमेट्री नहीं। इंडेक्स आपकी अपनी डिस्क पर रहता है, और आपकी फ़ाइलों या खोजों के बारे में कुछ भी कहीं नहीं भेजा जाता। अपडेट जाँच केवल यह पूछती है कि क्या कोई नया संस्करण है, और आप इसे बंद कर सकते हैं।","featuresPage.why.everything.title":"आप जो पहले से जानते हैं, यह उसका सम्मान करता है","featuresPage.why.everything.body":"Everything का सिंटैक्स, फ़िल्टर और फ़ाइल सूचियाँ वैसे ही व्यवहार करते हैं जैसे वहाँ — टेस्ट से जाँचे हुए — इसलिए बरसों की आदतें साथ चलती हैं, और दो और ऑपरेटिंग सिस्टम तक।","featuresPage.coming.title":"अभी क्या आना बाक़ी है","featuresPage.coming.intro":"साफ़-साफ़ बताया गया है, क्योंकि जो फ़ीचर सूची अपनी कमियाँ छिपाए, वह पढ़ने लायक नहीं। यह पन्ना संस्करण 1.0 के बारे में है, और Sourcerer एक-एक संस्करण करके बनता है: 0.23 के बाद के संस्करण अभी आने बाक़ी हैं। 1.0 की ओर रास्ते का हर संस्करण अपनी स्थिति के साथ चिह्नित है। पाँच में से दो लेंस — फ़ाइलों के भीतर का टेक्स्ट और बस मिलते-जुलते नाम — बन चुके हैं पर अभी खोज से जुड़े नहीं हैं। वे इस पन्ने पर इसलिए हैं क्योंकि वे 1.0 में हैं।","featuresPage.limits.title":"1.0 क्या नहीं करता","featuresPage.limits.headers":"यह गुण केवल फ़ाइल हेडर से पढ़ता है: उन्हें पाने के लिए न तस्वीरें डिकोड करता है, न वीडियो चलाता है, न दस्तावेज़ रेंडर करता है, इसलिए जो गुण हेडर में नहीं है, उसे खोजा नहीं जा सकता।","featuresPage.limits.firstIndex":"macOS और Linux पर पहला इंडेक्स हर फ़ोल्डर से होकर गुज़रता है, इसलिए बड़ी डिस्क पर सेकंड के बजाय मिनट लगते हैं।","featuresPage.limits.portable":"पोर्टेबल प्रति ख़ुद अपडेट नहीं होती: उसके फ़ोल्डर को नए संस्करण से बदलें।","featuresPage.coming.downloads":"संस्करण 1.0 से पहले कोई डाउनलोड नहीं है, और इस पन्ने पर भी कोई नहीं।","docs.intro":"Freally Sourcerer को, जैसा वह आज 1.0 की ओर रास्ते पर बना है, कैसे उपयोग करें; यह गाइड हर संस्करण के साथ बढ़ती है। macOS पर Ctrl को Cmd पढ़ें: मेनू आपके सिस्टम की अपनी कुंजियाँ दिखाते हैं।","docs.start.title":"शुरुआत करना","docs.search.title":"खोजना","docs.lenses.title":"पाँच लेंस","docs.syntax.title":"क्वेरी सिंटैक्स","docs.filters.title":"क्विक फ़िल्टर","docs.bookmarks.title":"बुकमार्क और साइडबार","docs.results.title":"परिणामों के साथ काम करना","docs.rename.title":"थोक में नाम बदलना","docs.preview.title":"पूर्वावलोकन और त्वरित झलक","docs.drives.title":"अनप्लग की गई ड्राइवें और फ़ाइल सूचियाँ","docs.health.title":"सूचकांक स्वास्थ्य और छोड़े गए फ़ोल्डर","docs.portable.title":"पोर्टेबल मोड","docs.settings.title":"सेटिंग और हॉटकी","docs.language.title":"भाषाएँ","docs.cli.title":"कमांड लाइन","docs.privacy.title":"निजता और नेटवर्क","docs.faq.title":"प्रश्न","docs.start.p1":"Sourcerer दो हिस्सों में चलता है: एक पृष्ठभूमि इंडेक्सर, <code>freally-indexd</code>, जो इंडेक्स को ताज़ा रखता है, और वह ऐप जिससे आप खोजते हैं। इंस्टॉलर दोनों को सेट करता है, और आपके साइन इन करने पर इंडेक्सर शुरू हो जाता है।","docs.start.id":"ऐप की आईडी <code>com.freallyproducts.sourcerer</code> है, और आपकी सेटिंग, बुकमार्क और इंडेक्स आपके सिस्टम के ऐप-डेटा फ़ोल्डर में इसी नाम से रखे जाते हैं। 0.23.2 तक के संस्करण <code>io.mikeweaver.freally</code> का उपयोग करते थे; नया संस्करण पहली बार शुरू होने पर उस फ़ोल्डर को नए नाम पर ले जाता है, इसलिए कुछ भी दोबारा इंडेक्स नहीं होता।","docs.start.p2":"ऐप पहली बार खुलने पर एक छोटा सेटअप पूछता है कि किन फ़ोल्डरों को इंडेक्स करना है, ऐप को सामने लाने वाली हॉटकी कौन-सी हो, और आपकी भाषा और थीम। इन सबको आप बाद में सेटिंग में बदल सकते हैं।","docs.start.p3":"फिर यह इंडेक्स बनाता है। Windows पर यह NTFS change journal पढ़ता है, जो जल्दी होता है; macOS और Linux पर यह आपके फ़ोल्डरों से होकर गुज़रता है, जिसमें बड़ी डिस्क पर मिनट लगते हैं। इसके काम करते समय भी आप खोज सकते हैं: परिणाम साथ-साथ भरते जाते हैं।","docs.start.p4":"संस्करण 1.0.0 से पहले कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","docs.search.type":"खोज पट्टी में टाइप करें। परिणाम टाइप करते ही दिखते हैं, लेंस के अनुसार समूहित, और हर समूह के साथ यह कि उसमें कितना समय लगा। हर वर्ण उन्हें और सीमित करता है; सबमिट करने को कुछ नहीं है।","docs.search.move":"तीर कुंजियों से परिणामों में आगे-पीछे जाएँ, और फ़ाइल को उसके सामान्य ऐप से खोलने के लिए Enter दबाएँ या पंक्ति पर डबल-क्लिक करें।","docs.search.within":"<kbd>Ctrl+Shift+F</kbd> पहले से मौजूद परिणामों में खोजता है। हर शब्द एक चिप बन जाता है जिसे आप अलग से हटा सकते हैं, ताकि बिना दोबारा टाइप किए एक कदम पीछे जा सकें।","docs.search.bold":"आपने जो टाइप किया, वह नामों और पथों में <strong>बोल्ड</strong> में दिखता है। <code>ext:json</code> जैसा मॉडिफ़ायर कोई ऐसी चीज़ नहीं जिसे आप ढूँढ रहे हैं, बल्कि सूची को सीमित करता है, इसलिए उसे चिह्नित नहीं किया जाता।","docs.search.clear":"<kbd>Esc</kbd> खोज पट्टी साफ़ करता है।","docs.lenses.intro":"Sourcerer में पाँच लेंस हैं, जो सभी एक ही इंडेक्स पढ़ते हैं। आज फ़ाइल नाम, ऑडियो और गुण लेंस आपकी खोजों का उत्तर देते हैं; सामग्री और समानता लेंस बन चुके हैं पर अभी खोज पट्टी से जुड़े नहीं हैं — यह 1.0 की ओर रास्ते में आएगा।","docs.lenses.filename":"फ़ाइल नाम: नाम और पथ, वाइल्डकार्ड, रेगुलर एक्सप्रेशन और Everything के मॉडिफ़ायर के साथ। पाँचों में सबसे तेज़।","docs.lenses.content":"सामग्री: PDF, Word, Excel और PowerPoint फ़ाइलों, सादे टेक्स्ट और Markdown, 32 भाषाओं के सोर्स कोड, JSON, CSV और YAML, मेल, और zip, 7z व tar आर्काइव के भीतर का टेक्स्ट, उन्हें खोले बिना। अभी खोज पट्टी से जुड़ा नहीं है।","docs.lenses.audio":"ऑडियो: किसी ऑडियो फ़ाइल का माप — LUFS में प्रबलता, मौन, dynamic range, अवधि, codec और sample rate — जिसकी गणना पहली बार किसी खोज के पूछने पर होती है, और जो फ़ाइल बदलने तक रखा जाता है।","docs.lenses.properties":"गुण: फ़ाइल का अपना हेडर क्या कहता है — छवियों, कैमरा डेटा, वीडियो, दस्तावेज़ों, प्रोग्रामों, इंस्टॉलरों, शॉर्टकट, आर्काइव, फ़ॉन्ट, मेल और SQLite डेटाबेस में फैले बहत्तर गुण।","docs.lenses.similar":"समानता: आपके टाइप किए के क़रीब के नाम, उन मौक़ों के लिए जब आपको फ़ाइल बस मोटे तौर पर याद हो। अभी खोज पट्टी से जुड़ा नहीं है; जब तक नहीं जुड़ता, जिस खोज में कुछ नहीं मिलता वह इसके बजाय सबसे निकट का असली नाम सुझाती है।","docs.lenses.prefix":"लेंस <strong>दृश्य → लेंस</strong> में चालू और बंद किए जा सकते हैं।","docs.syntax.intro":"Sourcerer, voidtools के Everything का सिंटैक्स समझता है, और अपने दूसरे लेंसों के लिए मॉडिफ़ायर जोड़ता है।","docs.syntax.basics":"बुनियादी बातें","docs.syntax.terms":"सादे शब्द नाम में कहीं भी मेल खाते हैं, और हर शब्द का मेल खाना ज़रूरी है: <code>report 2024</code>।","docs.syntax.wildcards":"<code>*</code> वर्णों के किसी भी क्रम से और <code>?</code> एक वर्ण से मेल खाता है, पूरे नाम के विरुद्ध: <code>invoice_202?.pdf</code>।","docs.syntax.boolean":"स्पेस या <code>AND</code> का अर्थ है दोनों, <code>|</code> या <code>OR</code> का अर्थ है कोई एक, <code>!</code> या <code>NOT</code> का अर्थ है नहीं, और कोष्ठक समूह बनाते हैं: <code>(budget | forecast) !draft</code>।","docs.syntax.regex":"<code>regex:</code> एक रेगुलर एक्सप्रेशन शुरू करता है: <code>regex:^report-\\d+</code>। सिंटैक्स Rust का है, इसलिए न backreferences हैं, न lookaround।","docs.syntax.modifiers":"मॉडिफ़ायर","docs.syntax.modifiersIntro":"मॉडिफ़ायर किसी फ़ाइल के बारे में ज्ञात बातों के आधार पर परिणाम सीमित करते हैं। जितने चाहें उतने जोड़ें।","docs.syntax.col.modifier":"मॉडिफ़ायर","docs.syntax.col.matches":"किससे मेल खाता है","docs.syntax.col.example":"उदाहरण","docs.syntax.mod.size":"आकार, kb, mb और gb, तुलनाओं और सीमाओं के साथ","docs.syntax.mod.date":"संशोधन तिथि; <code>dc:</code> निर्माण तिथि, <code>da:</code> एक्सेस तिथि","docs.syntax.mod.ext":"एक्सटेंशन, एक या अर्धविराम से अलग किए कई","docs.syntax.mod.attrib":"फ़ाइल विशेषताएँ, जैसे छिपी हुई","docs.syntax.mod.path":"पूरे पथ में यह टेक्स्ट है","docs.syntax.mod.parent":"फ़ाइल सीधे उसी फ़ोल्डर के भीतर है","docs.syntax.mod.anchors":"नाम इस टेक्स्ट से शुरू होता है, या इस पर ख़त्म होता है","docs.syntax.mod.loudness":"LUFS में मापी गई प्रबलता, और dB में dynamic range","docs.syntax.mod.length":"ऑडियो फ़ाइल की अवधि","docs.syntax.mod.codec":"ऑडियो codec, और Hz में sample rate","docs.syntax.mod.silence":"ऑडियो फ़ाइल का कितना हिस्सा मौन है, 0 से 1 तक","docs.syntax.mod.property":"बहत्तर गुणों में से कोई भी; <code>property:</code> लंबा रूप है","docs.syntax.mod.dupe":"समान नाम और समान आकार वाली फ़ाइलें; <code>name-dupe:</code> और <code>size-dupe:</code> इन दोनों में से एक पर मेल खाते हैं","docs.syntax.mod.empty":"ख़ाली फ़ाइलें और फ़ोल्डर; <code>empty:roots</code> फ़ोल्डरों की हर उस श्रृंखला का शीर्ष ढूँढता है जिसमें कोई फ़ाइल नहीं है","docs.syntax.mod.children":"फ़ोल्डर, इस आधार पर कि उनमें सीधे कितने आइटम हैं; <code>descendant-count:</code> किसी भी गहराई पर","docs.syntax.mod.volume":"किसी एक ड्राइव पर मौजूद फ़ाइलें, उसके नाम से, तब भी जब वह अनप्लग हो","docs.syntax.modes":"मिलान मोड","docs.syntax.modesMenu":"<strong>खोज</strong> मेनू केस मिलाएँ (<kbd>Ctrl+I</kbd>), पूरा शब्द मिलाएँ (<kbd>Ctrl+B</kbd>), पथ मिलाएँ (<kbd>Ctrl+U</kbd>) और डायाक्रिटिक्स मिलाएँ (<kbd>Ctrl+M</kbd>) को टॉगल करता है।","docs.syntax.ignore":"<strong>विराम-चिह्न अनदेखा करें</strong> से <code>foobar</code>, <code>foo-bar</code> को ढूँढ लेता है, और <strong>रिक्त स्थान अनदेखा करें</strong> से <code>myreport</code>, <code>my report</code> को। दोनों डिफ़ॉल्ट रूप से बंद हैं।","docs.syntax.cjk":"<strong>CJK ध्वन्यात्मकता मिलाएँ</strong> चीनी, जापानी और कोरियाई नामों को उनके उच्चारण से ढूँढता है: <code>wenjian</code> से 文件 मिलता है।","docs.syntax.regexBuilder":"<strong>regex सक्षम करें</strong> (<kbd>Ctrl+R</kbd>) पूरी क्वेरी को रेगुलर एक्सप्रेशन मानता है। खोज पट्टी के बगल का रेगुलर एक्सप्रेशन बिल्डर, आपके टाइप करते-करते, पैटर्न को स्क्रीन पर दिख रहे नामों पर जाँचता है, और पैटर्न अमान्य हो तो इंजन की अपनी त्रुटि दिखाता है।","docs.filters.p1":"क्विक फ़िल्टर एक क्लिक में परिणामों को किसी एक प्रकार की फ़ाइल तक सीमित करते हैं: ऑडियो, संपीड़ित, दस्तावेज़, एक्ज़ीक्यूटेबल, फ़ोल्डर, छवि और वीडियो। हर एक में वह हर एक्सटेंशन है जो Everything के अपने फ़िल्टर में है, और उससे ज़्यादा भी — 65 ऑडियो प्रकार, 79 वीडियो, 77 छवि, 86 दस्तावेज़ और 70 आर्काइव।","docs.filters.p2":"आप इन्हें टाइप भी कर सकते हैं, उन्हीं उपनामों के साथ जिनका आप अनुमान लगाएँगे: <code>audio:</code>, <code>video:</code>, <code>image:</code>, <code>document:</code>, <code>executable:</code> और <code>archive:</code>, या <code>music:</code>, <code>photos:</code>, <code>docs:</code> और <code>zip:</code>।","docs.filters.p3":"Everything के विपरीत, सोर्स कोड दस्तावेज़ के अंतर्गत नहीं रखा जाता; <code>ext:c;cpp;h</code> वह सेट वापस लाता है। अपनी किसी खोज को फ़िल्टर के रूप में रखने के लिए <strong>खोज → फ़िल्टर में जोड़ें…</strong> चुनें, और उन्हें <strong>फ़िल्टर व्यवस्थित करें…</strong> (<kbd>Ctrl+Shift+O</kbd>) से संपादित करें।","docs.bookmarks.add":"<kbd>Ctrl+D</kbd> मौजूदा खोज को बुकमार्क के रूप में सहेजता है, और <kbd>Ctrl+Shift+B</kbd> उन्हें व्यवस्थित करता है।","docs.bookmarks.recall":"किसी बुकमार्क को चलाने के लिए <code>:</code> और उसके बाद बुकमार्क का नाम टाइप करें।","docs.bookmarks.sidebar":"<strong>दृश्य → साइडबार</strong> एक कॉलम दिखाता है जिसमें आपके बुकमार्क, क्विक फ़िल्टर, आपकी ड्राइवें और आपकी हाल की खोजें होती हैं। बुकमार्क का क्रम बदलने के लिए उन्हें drag करें; केवल उसी ड्राइव में खोजने के लिए किसी ड्राइव पर क्लिक करें।","docs.bookmarks.history":"गोपनीयता मोड चालू होने पर या खोज इतिहास बंद होने पर हाल की खोजें दर्ज नहीं होतीं।","docs.results.intro":"हर पंक्ति आपकी डिस्क पर एक असली फ़ाइल है। उसके साथ आप क्या कर सकते हैं, यह देखने के लिए पंक्ति पर right-click करें:","docs.results.open":"खोलें, फ़ाइल प्रबंधक में दिखाएँ, और इससे खोलें, जो उन ऐप्स की सूची देता है जिन्हें आपके सिस्टम ने उस प्रकार की फ़ाइल के लिए पंजीकृत किया है।","docs.results.copy":"टेक्स्ट फ़ाइल की सामग्री के लिए सामग्री कॉपी करें, फ़ाइल को ही किसी फ़ोल्डर में चिपकाने के लिए फ़ाइल के रूप में कॉपी करें, और पथ सूची कॉपी करें — प्रति पंक्ति एक, उद्धरण चिह्नों में, स्पेस से अलग या शेल के लिए एस्केप।","docs.results.hits":"मिलान संदर्भ सहित देखें किसी दस्तावेज़ का हर मिलान दिखाता है; <kbd>F3</kbd> और <kbd>Shift+F3</kbd> उनमें एक-एक करके आगे-पीछे जाते हैं।","docs.results.terminal":"यहाँ टर्मिनल खोलें फ़ाइल के फ़ोल्डर में एक टर्मिनल खोलता है।","docs.results.commands":"<strong>सेटिंग → सामान्य → कस्टम कमांड</strong> से आपके अपने कमांड, जिनके तर्कों में <code>{path}</code>, <code>{dir}</code>, <code>{name}</code>, <code>{stem}</code> और <code>{ext}</code> हो सकते हैं। हर एक तर्कों वाले प्रोग्राम के रूप में चलता है, कभी shell पंक्ति के रूप में नहीं, और किसी प्रोग्राम के पहली बार चलने से पहले ऐप एक बार पूछता है।","docs.results.delete":"हटाएँ फ़ाइल को Trash या Recycle Bin में भेजता है।","docs.results.view":"किसी पंक्ति को दूसरे ऐप में ऐसे drag करें जैसे अपने फ़ाइल प्रबंधक से करते हैं। सॉर्ट करने के लिए कॉलम हेडर पर क्लिक करें, या <kbd>Ctrl+1</kbd> से <kbd>Ctrl+9</kbd> उपयोग करें; हेडर पंक्ति के अंत का <strong>+</strong> किसी गुण को कॉलम के रूप में जोड़ता है। <strong>दृश्य</strong> मेनू विवरण और थंबनेल के बीच बदलता है। पूरे परिणाम सेट के आँकड़ों के लिए स्थिति बार में परिणाम-संख्या पर क्लिक करें: प्रकार के अनुसार आकार और गिनती, और सबसे बड़ी, सबसे पुरानी और सबसे नई फ़ाइलें।","docs.rename.intro":"जिन परिणामों का नाम बदलना है उन्हें चुनें और <kbd>F2</kbd> दबाएँ। आप बदलाव एक बार बताते हैं, और डिस्क पर कुछ भी होने से पहले हर पुराना और नया नाम दिखाया जाता है।","docs.rename.find":"खोजें और बदलें, सादे टेक्स्ट के रूप में या रेगुलर एक्सप्रेशन के रूप में, जो पकड़ा गया उसके लिए <code>$1</code>, <code>$2</code> के साथ।","docs.rename.number":"बदले जाने वाले टेक्स्ट में <code>{n}</code> फ़ाइलों को पूर्वावलोकन के क्रम में क्रमांकित करता है; <code>{n:03}</code> संख्या को तीन अंकों तक शून्य से भरता है।","docs.rename.case":"केस बदलें, और चुनें कि नियम केवल नाम पर लागू हो या एक्सटेंशन पर भी। डिफ़ॉल्ट रूप से एक्सटेंशन को नहीं छुआ जाता।","docs.rename.check":"जो पंक्तियाँ आपस में टकराएँगी, किसी फ़ाइल को अधिलेखित करेंगी या ऐसा नाम बनाएँगी जिसे सिस्टम अस्वीकार करता है, वे चिह्नित की जाती हैं, और जब तक कोई भी पंक्ति चिह्नित है, किसी का नाम नहीं बदलता: पूरा batch या तो पूरा होता है या बिल्कुल नहीं।","docs.rename.undo":"<kbd>Ctrl+Z</kbd> नाम बदलने को पूर्ववत करता है, ऐप रीस्टार्ट करने के बाद भी, और <kbd>Ctrl+Shift+Z</kbd> उसे फिर से करता है। Windows और Linux पर पूर्ववत करें हटाई गई फ़ाइल को Recycle Bin या Trash से वापस भी लाता है। macOS पर यह संभव नहीं: फ़ाइल को Trash से ख़ुद पुनर्स्थापित करें।","docs.preview.pane":"<strong>दृश्य → पूर्वावलोकन</strong> (<kbd>Alt+P</kbd>) चुनी गई फ़ाइल को परिणामों के बगल में दिखाता है: तस्वीरें, टेक्स्ट और कोड, और दस्तावेज़।","docs.preview.play":"ऑडियो और वीडियो फलक में चलते हैं — चलाएँ और रोकें, आगे-पीछे करें, दोहराएँ और आवाज़ के नियंत्रण के साथ। ऑडियो एक वेवफ़ॉर्म बनाता है जिस पर आप क्लिक कर सकते हैं, और उसके नीचे उसका codec, sample rate, channels और प्रबलता होती है।","docs.preview.quickLook":"<kbd>Space</kbd> त्वरित झलक खोलता है, जो विंडो के ऊपर एक बड़ा पूर्वावलोकन है। उसके खुले रहते तीर कुंजियाँ परिणामों में आगे-पीछे चलती रहती हैं, और <kbd>Space</kbd> या <kbd>Esc</kbd> उसे बंद करता है।","docs.preview.mac":"macOS पर त्वरित झलक उन प्रारूपों के लिए, जिन्हें सिस्टम दिखा सकता है पर Sourcerer नहीं, फ़ाइल को सिस्टम के अपने क्विक लुक में खोलने का विकल्प भी देती है।","docs.drives.unplugged":"जब आप कोई ड्राइव अनप्लग करते हैं, तो उस पर इंडेक्स की गई हर चीज़ खोजने योग्य बनी रहती है। उसके परिणामों पर ड्राइव के नाम का बैज होता है, इसलिए वे यह भी बताते हैं कि कोई फ़ाइल किस ड्राइव पर है, और <code>volume:</code> किसी एक ड्राइव में उसके नाम से खोजता है। किसी दूसरे अक्षर या mount point पर लौटने वाली ड्राइव भी पहचानी जाती है।","docs.drives.lists":"<strong>फ़ाइल → परिणाम निर्यात करें…</strong> (<kbd>Ctrl+S</kbd>) परिणामों को Everything की <code>.efu</code> फ़ाइल सूची, CSV, सादे टेक्स्ट, ऑडियो फ़ाइलों की M3U प्लेलिस्ट, या किसी script के लिए NDJSON के रूप में सहेजता है। <strong>फ़ाइल → फ़ाइल सूची खोलें…</strong> (<kbd>Ctrl+O</kbd>) इंडेक्स के बजाय किसी सूची में खोजता है — Everything की सूचियों में भी — जब तक आप <strong>फ़ाइल सूची बंद करें</strong> नहीं चुनते।","docs.health.index":"<strong>उपकरण → अनुक्रमणिका अनुरक्षण → सूचकांक स्वास्थ्य…</strong> निगरानी में रखी हर जगह के लिए दिखाता है कि परिवर्तन लाइव आते हैं या केवल दोबारा स्कैन होने पर, इंडेक्स कितना पीछे है, और कितने परिवर्तन छूट गए। कुछ गड़बड़ हो तो यह बताता है कि क्या, और जहाँ पुनर्निर्माण ही सुधार है वहाँ एक-क्लिक पुनर्निर्माण देता है।","docs.health.permissions":"जिस फ़ोल्डर को ऐप पढ़ नहीं सकता, वह बिल्कुल ख़ाली फ़ोल्डर जैसा दिखता है। <strong>अनुमति स्थिति…</strong>, उसी मेनू में या स्थिति बार के \"फ़ोल्डर छोड़े गए\" बैज से, छोड़े गए फ़ोल्डरों, सिस्टम के कारण और सुधार की सूची देता है। macOS पर यह जाँचता है कि पूर्ण डिस्क पहुँच दी गई है या नहीं, और नहीं दी गई हो तो सही सेटिंग पेज खोलता है।","docs.portable.p1":"Sourcerer को USB स्टिक से चलाने के लिए ऐप के बगल में <code>portable.flag</code> नाम की एक ख़ाली फ़ाइल रखें, या उसे <code>--portable</code> के साथ शुरू करें। तब इंडेक्स, सेटिंग, बुकमार्क और लॉग ऐप के बगल में एक <code>Data</code> फ़ोल्डर में रहते हैं, और कंप्यूटर में कुछ भी पंजीकृत नहीं होता: न कोई पृष्ठभूमि सेवा, न कोई लिंक हैंडलर, न कोई अपडेटर। पोर्टेबल प्रति को उसका फ़ोल्डर बदलकर अपडेट करें।","docs.portable.mac":"macOS पर <code>Data</code> फ़ोल्डर ऐप के बगल में बनता है, उसके अंदर नहीं, क्योंकि ऐप के अंदर लिखने से उसका हस्ताक्षर टूट जाता है।","docs.settings.open":"<strong>उपकरण → विकल्प…</strong> (<kbd>Ctrl+,</kbd>) सेटिंग खोलता है, जो Everything के Options की तरह व्यवस्थित है: बाईं ओर पैनलों का एक ट्री, उसके ऊपर एक बॉक्स जो टाइप करते ही पैनलों और विकल्पों को फ़िल्टर करता है, और <strong>ठीक है</strong>, <strong>रद्द करें</strong> और <strong>लागू करें</strong>।","docs.settings.panels":"पैनल इन सबको कवर करते हैं: ऐप का रूप, खोज का व्यवहार, परिणाम, कीबोर्ड शॉर्टकट, इंडेक्स बनाने वाले फ़ोल्डर, ड्राइवें और बहिष्करण, हर लेंस, गोपनीयता और अपडेट, लॉग, बैकअप और रीसेट, और भाषा।","docs.settings.hotkey":"एक ग्लोबल हॉटकी ऐप को कहीं से भी सामने ले आती है, और खोज पट्टी तैयार रहती है। इसे <strong>सेटिंग → सामान्य → कीबोर्ड</strong> में सेट करें। <code>freally://search?q=…</code> रूप का लिंक उसी खोज के साथ ऐप खोलता है।","docs.language.p1":"Sourcerer अठारह भाषाएँ बोलता है। <strong>सेटिंग → लोकेल</strong> में एक चुनें, और पूरा ऐप — मेनू, सेटिंग, डायलॉग और स्थिति बार — बिना रीस्टार्ट के तुरंत बदल जाता है। अरबी में विंडो का लेआउट दाएँ से बाएँ होता है।","docs.cli.intro":"<code>freally</code> कमांड ऐप वाले उसी इंडेक्स में, उसी इंडेक्सर के ज़रिए, उसी क्वेरी भाषा में खोजता है।","docs.cli.formats":"<code>--json</code>, <code>--ndjson</code> और <code>--csv</code> scripts के लिए परिणाम छापते हैं, <code>-0</code>, <code>xargs -0</code> के लिए NUL से अलग किए पथ छापता है, और <code>--fields</code> कॉलम चुनता है। exit code बताता है कि कुछ मेल खाया या नहीं।","docs.cli.strict":"<code>--strict-everything</code> ऐसी किसी भी क्वेरी को अस्वीकार करता है जो कोई ऐसी चीज़ उपयोग करे जो Everything में नहीं है, और उसका नाम बताता है — यह जाँचने का तरीका कि क्वेरी दोनों में काम करती है।","docs.cli.manage":"<code>freally index</code> इंडेक्सर की स्थिति दिखाता है और उसे रोक, फिर से शुरू, सत्यापित, संहत या पुनर्निर्मित कर सकता है; <code>freally bookmark</code> बुकमार्क सहेजता है, सूचीबद्ध करता है और हटाता है।","docs.cli.completions":"<code>freally completions</code> bash, zsh, fish और PowerShell के लिए completions छापता है, जिनमें मॉडिफ़ायर नाम और आपके बुकमार्क भी शामिल हैं।","docs.privacy.telemetry":"कोई टेलीमेट्री नहीं है। इंडेक्स आपके अपने कंप्यूटर पर बनता और रहता है, और आपकी फ़ाइलों या खोजों के बारे में कुछ भी कहीं नहीं भेजा जाता।","docs.privacy.updates":"ऐप दिन में एक बार पूछता है कि क्या कोई नया संस्करण है; <strong>सेटिंग → गोपनीयता और अपडेट</strong> में आप इसे साप्ताहिक, मासिक या कभी नहीं कर सकते हैं, या अभी जाँच सकते हैं। कुछ भी इंस्टॉल करने से पहले यह दोनों संस्करणों के नाम बताकर पूछता है, और पोर्टेबल प्रति कभी जाँच नहीं करती।","docs.privacy.mode":"गोपनीयता मोड हाल की खोजें दर्ज करना बंद कर देता है और गुण लेंस को बंद कर देता है, जो फ़ाइलों के भीतर पढ़ता है।","docs.privacy.reports.title":"समस्या की रिपोर्ट करना","docs.privacy.reports.where":"जब ऐप किसी त्रुटि से टकराता है, तो उसके संदेश के बगल में एक <strong>रिपोर्ट करें</strong> बटन होता है। क्रैश के बाद, अगली बार लॉन्च होने पर <strong>रिपोर्ट करें</strong> या <strong>हटाएँ</strong> का विकल्प मिलता है।","docs.privacy.reports.page":"<strong>रिपोर्ट करें</strong> आपके ब्राउज़र में रिपोर्ट पेज, <code>freallyproducts.com/freally-sourcerer/report/</code>, खोलता है, जिसमें तकनीकी तथ्य पहले से भरे होते हैं: आप उन्हें पढ़ सकते हैं, पर बदल नहीं सकते। आप जोड़ते हैं कि आप क्या कर रहे थे, और चाहें तो एक ईमेल पता।","docs.privacy.reports.send":"जब तक आप उस पेज पर <strong>भेजें</strong> नहीं दबाते, कुछ नहीं भेजा जाता, और पृष्ठभूमि में कभी कुछ नहीं भेजा जाता।","docs.faq.missing.title":"कोई फ़ाइल परिणामों में क्यों नहीं है?","docs.faq.missing.indexing":"हो सकता है पहला इंडेक्स अभी भी चल रहा हो: स्थिति बार यह बताता है।","docs.faq.missing.roots":"हो सकता है उसका फ़ोल्डर इंडेक्स न किया गया हो: <strong>सेटिंग → अनुक्रमणिकाएँ</strong> में फ़ोल्डर, ड्राइवें और बहिष्करण जाँचें।","docs.faq.missing.permissions":"हो सकता है उसका फ़ोल्डर पढ़ा न जा सके: <strong>अनुमति स्थिति…</strong> खोलें।","docs.faq.smaller.title":"मैं इंडेक्स को छोटा कैसे करूँ?","docs.faq.smaller.body":"ऐसी फ़ाइलों से भरे फ़ोल्डर, जिन्हें आप कभी नहीं ढूँढते — जैसे <code>node_modules</code> और <code>.git</code> — <strong>सेटिंग → अनुक्रमणिकाएँ → बहिष्कृत करें</strong> में बाहर रखें।","docs.faq.rebuild.title":"मैं इंडेक्स फिर से शुरू से कैसे बनाऊँ?","docs.faq.rebuild.body":"<strong>उपकरण → अनुक्रमणिका अनुरक्षण → अनुक्रमणिका पुनर्निर्माण के लिए बाध्य करें…</strong> इंडेक्स को साफ़ करके शुरू से फिर बनाता है। उसी मेनू में <strong>अनुक्रमणिका सत्यापित करें…</strong> और <strong>अनुक्रमणिका संहत करें…</strong> उसे जाँचते और छोटा करते हैं।","kit.skip":"सामग्री पर जाएँ","kit.nav.site":"साइट","kit.nav.home":"होम","kit.nav.features":"फ़ीचर्स","kit.nav.documentation":"दस्तावेज़ीकरण","kit.nav.changelog":"बदलाव लॉग","kit.nav.language":"भाषा","kit.nav.allApps":"सभी Freally ऐप्स","kit.badge.progress":"v0.23.0 पूरा · आगे v0.24.0","kit.cta.features":"सभी फ़ीचर्स देखें","kit.cta.docs":"दस्तावेज़ीकरण पढ़ें","kit.price":"Freally Sourcerer आज मुफ़्त है, लेकिन हो सकता है कि यह हमेशा मुफ़्त न रहे: भविष्य के संस्करण बेचे जा सकते हैं।","kit.noDownloads":"अभी कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","kit.label.overview":"अवलोकन","kit.label.inside":"अंदर","kit.label.roadmap":"रोडमैप","kit.ladder.done":"पूरा","kit.ladder.planned":"नियोजित","kit.ladder.goal":"लक्ष्य","kit.label.honesty":"ईमानदारी","kit.family.label":"Freally परिवार","kit.family.title":"<span class=\"hl-muted\">एक परिवार।</span> <span class=\"hl-bright\">आठ ऐप्स।</span>","kit.cta.label":"क्या बदला","kit.cta.title":"<span class=\"hl-muted\">हर संस्करण,</span> <span class=\"hl-bright\">लिखित में।</span>","kit.cta.lede":"बदलाव लॉग में Freally Sourcerer में हुआ हर बदलाव, संस्करण-दर-संस्करण, सभी अठारह भाषाओं में दर्ज है।","kit.cta.changelog":"बदलाव लॉग पढ़ें","kit.footer.thisApp":"यह ऐप","kit.footer.family":"Freally परिवार","kit.status.devVersion":"विकास में · v0.23.2","kit.head.features":"<span class=\"hl-muted\">यह जो कुछ करता है,</span> <span class=\"hl-bright\">आमने-सामने।</span>","kit.label.numbers":"आँकड़ों में","kit.label.free":"आज मुफ़्त","kit.label.compare":"तुलना","kit.label.principles":"सिद्धांत","kit.label.limits":"सीमाएँ","kit.states.title":"स्थितियों का अर्थ","kit.states.done":"बना और टैग किया गया, पर इस साइट पर डाउनलोड नहीं","kit.states.planned":"अभी बनना बाकी है","kit.states.goal":"वह संस्करण जिस तक यह रास्ता जाता है","kit.states.ladder":"रास्ते का हर पड़ाव देखें","kit.head.documentation":"<span class=\"hl-muted\">यह कैसे काम करता है,</span> <span class=\"hl-bright\">क़दम-दर-क़दम।</span>","kit.search.placeholder":"दस्तावेज़ीकरण में खोजें","kit.docs.contents":"विषय-सूची","kit.head.changelog":"<span class=\"hl-muted\">हर बदलाव,</span> <span class=\"hl-bright\">संस्करण-दर-संस्करण।</span>","kit.changelog.lede":"सबसे नया पहले: Freally Sourcerer में जो कुछ बदला, इस साइट की हर भाषा में।","kit.changelog.versions":"संस्करण","kit.changelog.unreleased":"अप्रकाशित","kit.search.none":"इस साइट पर इससे कुछ भी मेल नहीं खाता।","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">अप्रकाशित</span></span>","changelog.6b02e0d363a4":"जोड़ा गया","changelog.1e07f27ea3ab":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>गुण लेंस</strong> (SRC-N01 … SRC-N15) — एक पाँचवाँ लेंस, जो <em>कंटेनर हेडर</em> पढ़ता है। <code>width:&gt;1920</code>, <code>camera-model:R5</code>, <code>author:lovelace</code>, <code>binary-type:arm64</code>, <code>package-version:0.23</code>, <code>broken-link:</code>, <code>entry-count:&gt;1000</code>, <code>font-scripts:cyrillic</code>, <code>from:ada@example.com</code>, <code>table-names:notes</code> — ग्यारह समूहों में बहत्तर गुण, जिनमें से हर एक मॉडिफ़ायर के रूप में टाइप किया जा सकता है और हर एक परिणाम कॉलम के रूप में भी उपलब्ध है। नया crate <code>freally-properties</code>; सामान्य रूप के लिए नया <code>property:</code> DSL नेमस्पेस (<code>property:duration&gt;60</code> — जिस कुंजी का नाम कोई पुराना मॉडिफ़ायर पहले से इस्तेमाल करता है, उस तक इसी तरह पहुँचा जाता है)।","changelog.a87ab2c792bf":"<strong>लेज़ी, और जर्नल द्वारा अमान्य होने वाला।</strong> इंडेक्सिंग के समय कुछ नहीं चलता। कोई गुण पहली बार तब पढ़ा जाता है जब कोई क्वेरी उस फ़ाइल के बारे में पूछती है, और उसके बाद उसके <code>mtime_ns</code> के आधार पर कैश किया जाता है, इसलिए जर्नल इस लेंस को अमान्य कर देता है, बिना लेंस के कभी उसकी सदस्यता लिए — यही अनुबंध ऑडियो लेंस का चरण 9 से रहा है। मिस भी कैश होते हैं: <code>.txt</code> फ़ाइलों से भरे फ़ोल्डर में हर फ़ाइल पर प्रति इंडेक्स जनरेशन एक <code>open</code> लगता है, प्रति कीस्ट्रोक एक नहीं।","changelog.ca8eac0102ce":"<strong>केवल हेडर।</strong> कोई भी पार्सर न कोई छवि डिकोड करता है, न कोई स्ट्रीम डीमक्स करता है, न कोई पेज रेंडर करता है, और न किसी के डेटाबेस की कोई पंक्ति पढ़ता है। यही सीमा-रेखा RAW फ़ाइलों से भरे फ़ोल्डर पर भी <code>width:&gt;1920</code> का उत्तर टाइपिंग की गति से देना संभव बनाए रखती है।","changelog.982e60011610":"<strong>पूर्ण (total)।</strong> कोई भी फ़ाइल किसी गुण क्वेरी को विफल नहीं कर सकती। कटा हुआ हेडर, ऐसी <code>.png</code> जो असल में टेक्स्ट फ़ाइल है, अपठनीय पथ: इन सबका अर्थ है &quot;इस पंक्ति के कोई गुण नहीं हैं&quot;, जो मेल न खाने का पूरी तरह वाजिब कारण है।","changelog.020bc33d94a7":"<strong>प्रारूप।</strong> PNG / JPEG / GIF / WebP / BMP / TIFF / AVIF-HEIC के आयाम और आंतरिक विवरण (SRC-N02, N04); has-GPS फ़्लैग के साथ EXIF कैप्चर डेटा, और <strong>कोई निर्देशांक संग्रहीत नहीं</strong> (N03); MP4 / MOV / MKV / WebM / AVI के तकनीकी विवरण (N05); PDF info डिक्शनरी और OOXML <code>core.xml</code> / <code>app.xml</code> (N08); PE / ELF / Mach-O आर्किटेक्चर, Windows VERSIONINFO स्ट्रिंग और Authenticode स्थिति (N09); MSI / deb / rpm / pkg पैकेज मेटाडेटा (N10); <code>.lnk</code> / <code>.desktop</code> / symlink के लक्ष्य, <code>broken-link:</code> खोजक के साथ (N11); zip / 7z / tar की एंट्री संख्या, संपीड़न अनुपात, एन्क्रिप्शन और मल्टी-वॉल्यूम पहचान (N12); TTF / OTF / WOFF का फ़ैमिली, वेट, ग्लिफ़ संख्या और समर्थित लिपियाँ — किसी घोषित रेंज से नहीं, बल्कि <em>cmap</em> से पढ़ी गईं (N13); RFC-822 और mbox हेडर (N14); SQLite स्कीमा (N15)।","changelog.2f4f9e89e8ed":"<strong>दो नए सामग्री एक्सट्रैक्टर।</strong> <code>.eml</code> / <code>.mbox</code> के हेडर और बॉडी सामग्री लेंस को मिलते हैं, और अटैचमेंट archive-peek की <code>container!inner</code> वर्तनी में वर्चुअल एंट्री के रूप में सूचीबद्ध होते हैं — अटैचमेंट के <em>बाइट</em> कभी डिकोड नहीं किए जाते (N14)। <code>.db</code> / <code>.sqlite</code> अपनी तालिकाओं और कॉलमों के नाम हमेशा देते हैं, और टेक्स्ट कॉलमों की पहली पंक्तियाँ <strong>केवल</strong> एक ऐसी सेटिंग के पीछे, जो बंद अवस्था में शिप होती है (N15): डाउनलोड फ़ोल्डर का डेटाबेस किसी के ऐप का डेटा है।","changelog.58bf7de69c7c":"<strong>गुण कॉलम</strong> (SRC-N06) — हेडर पंक्ति के <code>+</code> मेनू से कोई भी गुण परिणाम कॉलम बन सकता है, क्रमबद्ध करने योग्य, और हर क्विक फ़िल्टर के लिए स्वचालित लेआउट के साथ (चित्र आयाम दिखाता है, वीडियो अवधि और रिज़ॉल्यूशन)। कॉलम id अब <code>name</code> … <code>ext</code> और साथ में <code>prop:&lt;key&gt;</code> हैं — किसी निश्चित union के बजाय रजिस्ट्री से डेटा-चालित।","changelog.aa4087512231":"<strong>परिणाम आँकड़े</strong> (SRC-N07) — स्थिति बार में परिणाम-संख्या पर क्लिक करने से खुलते हैं: कुल बाइट, एक्सटेंशन और प्रकार के अनुसार गिनती और आकार, सबसे बड़ी / सबसे पुरानी / सबसे नई पंक्ति, और हर उस गुण का हिस्टोग्राम जो इस सेट में वास्तव में मौजूद है। गणना डेमन की ओर पूरे परिणाम सेट पर होती है, स्क्रीन पर दिख रहे पेज पर नहीं, और 200 000 पंक्तियों पर सीमित है — सीमा लागू होने पर &quot;यह न्यूनतम संख्या है&quot; नोट के साथ।","changelog.47c227c9a823":"<strong>सेटिंग → लेंस → गुण</strong> — लेंस चालू या बंद, प्रति-समूह टॉगल, प्रति फ़ाइल निष्कर्षण समय-सीमा, SQLite पंक्तियों वाला स्विच, और स्वचालित-कॉलम टॉगल। गोपनीयता मोड पूरे लेंस को बंद कर देता है, क्योंकि यह फ़ाइलों के अंदर पढ़ता है, और गोपनीयता मोड इसी के बारे में है।","changelog.2662e0d9c21f":"<strong>विचलन — छिपाए नहीं, साफ़ बताए गए।</strong> macOS पर हस्ताक्षर सत्यापन किसी सत्यापित हस्ताक्षर के बजाय <em>एम्बेडेड</em> हस्ताक्षर की सूचना देता है: <code>Security.framework</code> से नोटराइज़ेशन जाँच एक ऐसे फ़्रेमवर्क के विरुद्ध unsafe FFI है जिसे इस प्रोजेक्ट की कोई भी मशीन चलाकर परख नहीं सकती, और एक असत्यापनीय <code>valid</code> एक ईमानदार <code>embedded</code> से बदतर है। WOFF2 फ़ॉन्ट से कुछ नहीं मिलता — brotli और साथ में glyf/loca ट्रांसफ़ॉर्म अपने-आप में एक दूसरी फ़ॉन्ट लाइब्रेरी है, हेडर पढ़ना नहीं। ELF बाइनरी को कोई <code>signature</code> गुण मिलता ही नहीं, क्योंकि Linux बाइनरी के बजाय पैकेज पर हस्ताक्षर करता है और इसका उत्तर SRC-N10 में है। गुणों के <em>नाम</em> हर लोकेल में अनुवाद के बजाय उनकी कुंजियों से बनाए जाते हैं (<code>aspect-ratio</code> → &quot;Aspect ratio&quot;); उनके आसपास का UI सामान्य रूप से स्थानीयकृत है।","changelog.bc802b748761":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>आपने जो टाइप किया, वह परिणामों में बोल्ड दिखता है</strong>, टाइप करते-करते ही, नाम और पथ दोनों कॉलम में। केवल आपके खोज शब्द चिह्नित होते हैं: <code>ext:json</code> जैसा मॉडिफ़ायर सूची को सीमित करता है, वह कोई ऐसी चीज़ नहीं जिसे आप ढूँढ रहे हैं, इसलिए हर फ़ाइल नाम के भीतर <code>json</code> बोल्ड नहीं होता। चिह्नांकन हाइलाइटर ब्लॉक के बजाय फ़ॉन्ट वेट से होता है, ताकि वह चयनित पंक्ति पर और दोनों थीम में पढ़ने योग्य रहे।","changelog.0a3eaf604faf":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>बग की रिपोर्ट करें</strong> — <code>Help → Report a Bug…</code>, और साथ में एक प्रॉम्प्ट जो क्रैश के बाद अगली बार लॉन्च करने पर दिखता है। एक panic hook स्थानीय रूप से एक <strong>साफ़ की गई</strong> क्रैश रिपोर्ट लिखता है (फ़ाइल के डिस्क तक पहुँचने से पहले होम पथ और उपयोगकर्ता नाम हटा दिए जाते हैं), और डायलॉग आपको वह <strong>सटीक</strong> टेक्स्ट दिखाता है जो भेजा जाएगा — केवल ऐप संस्करण और OS — और उसके बाद ही पहले से भरा GitHub issue या मेल ड्राफ़्ट खोलने का विकल्प देता है। <strong>कुछ भी स्वतः नहीं भेजा जाता</strong>; कोई टेलीमेट्री नहीं है और हमारा चलाया कोई सर्वर नहीं है। दो अभ्यास (drills) सेटिंग → लॉग और डिबग में हैं।","changelog.09c294b4b464":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>अपडेट जाँचें</strong> — सेटिंग → गोपनीयता और अपडेट अब कोई वेब पेज खोलने के बजाय अपडेटर से पूछता है। यह बताता है कि आप कौन-सा संस्करण चला रहे हैं, काम करने वाले लिंक के साथ रिलीज़ नोट्स दिखाता है, और अपडेट उपलब्ध होने पर कुछ भी इंस्टॉल करने से पहले <strong>दोनों संस्करणों के नाम वाला हाँ/नहीं बॉक्स</strong> दिखाता है। हाँ चुनने पर यह इंडेक्सर डेमन को रोकता है, इंस्टॉल करता है और बंद हो जाता है; Windows पर इंस्टॉलर का अंतिम पेज नया संस्करण लॉन्च करने का विकल्प देता है। लॉन्च पर होने वाली जाँच आवृत्ति (cadence) सेटिंग का पालन करती है, क्रैश रिपोर्ट प्रतीक्षा में होने पर पीछे हट जाती है, और मशीन ऑफ़लाइन होने पर <strong>चुप</strong> रहती है।","changelog.59f3ea0ca50a":"<strong>[Windows]</strong> <code>freally-indexd status</code> बताता है कि डेमन सेवा के रूप में पंजीकृत है या नहीं, और सेवा प्रबंधक उसे किस हाल में देखता है। install और uninstall पहले से मौजूद थे, पर यह पूछने का कोई तरीका नहीं था कि हुआ क्या।","changelog.5b14114e2f2b":"<strong>[दस्तावेज़]</strong> <code>docs/EVERYTHING_MIGRATION_GUIDE.md</code> — voidtools के Everything से क्या-क्या साथ आता है, क्या नया है, और वे तीन बातें जो आपको चौंकाएँगी। <code>docs/MENU_REFERENCE.md</code> — सभी 112 मेनू आइटम और उनके शॉर्टकट, मेनू spec से जनरेट किए गए ताकि यह कभी पुराना न पड़े।","changelog.2643567f0f72":"<strong>[पैकेजिंग]</strong> <code>packaging/</code> में winget, Chocolatey, Homebrew Cask, Flathub और Snap के मैनिफ़ेस्ट हैं, जिन्हें <code>scripts/gen-packaging.mjs</code> किसी प्रकाशित रिलीज़ से जनरेट करता है, ताकि चेकसम वही हों जो GitHub परोसता है।","changelog.013883122f3c":"<strong>[रिलीज़]</strong> <code>scripts/verify-updater-chain.mjs</code> साबित करता है कि कोई प्रकाशित रिलीज़ वास्तव में अपडेट की जा सकती है: यह हर प्लेटफ़ॉर्म हस्ताक्षर के भीतर की key id की तुलना बाइनरी में कंपाइल की गई सार्वजनिक कुंजी से करता है। अपडेटर विफल होने पर बंद (fail closed) <strong>और चुप</strong> रहता है, इसलिए गलत कुंजी से हस्ताक्षरित रिलीज़ को और कुछ नहीं पकड़ता।","changelog.0c8009384b06":"<strong>[सभी प्लेटफ़ॉर्म]</strong> फ़ाइल हटाना अब पूर्ववत किया जा सकता है। <code>files_delete</code> पंक्तियों को OS के ट्रैश में भेजता है, जहाँ से उन्हें वापस लाया जा सकता है, पर कुछ भी दर्ज नहीं करता था — इसलिए ऐप का अपना पूर्ववत करें किसी भी प्लेटफ़ॉर्म पर हटाई गई फ़ाइल वापस नहीं देता था। अब यह जर्नल में दर्ज होता है, और Ctrl+Z, Recycle Bin (Windows) या freedesktop ट्रैश (Linux) से पुनर्स्थापित करता है।","changelog.e370b0fcd2c3":"<strong>[केवल macOS]</strong> हटाना <strong>पूर्ववत न हो सकने वाले के रूप में, कारण सहित</strong> दर्ज होता है, क्योंकि Put Back पर Finder का नियंत्रण है और वह इसके लिए कोई API उपलब्ध नहीं कराता। पूर्ववत करें अब चुप रहने के बजाय यह बताता है: <code>next_undo</code> सही तरह से किसी पूर्ववत न हो सकने वाली प्रविष्टि को लाँघने से इनकार करता है, जिसका अर्थ था कि हटाने के बाद Ctrl+Z कुछ भी नहीं करता था और कभी नहीं बताता था कि क्यों।","changelog.63589b7d0b3f":"<strong>[सभी प्लेटफ़ॉर्म]</strong> कस्टम कमांड किसी प्रोग्राम को पहली बार चलाने से पहले एक बार, नेटिव OS डायलॉग में, पूछते हैं। स्वीकृति प्रोग्राम से बँधी होती है, इसलिए कमांड का नाम बदलने पर दोबारा नहीं पूछा जाता, और प्रॉम्प्ट प्रोग्राम के साथ-साथ तर्क (arguments) भी बताता है। स्वीकृतियाँ <code>settings.json</code> के बाहर रहती हैं — उन्हें उसमें रखने से अनुमति-सूची उसी webview-लेखन-योग्य पथ के पीछे आ जाती, जिससे बचाने के लिए ही प्रॉम्प्ट मौजूद है। देखें <code>docs/SECURITY.md</code>।","changelog.549a5f40d4d8":"<strong>[सभी प्लेटफ़ॉर्म]</strong> कॉलम का आकार बदलने वाले ग्रिप अब कीबोर्ड से चलाए जा सकते हैं: तीर कुंजियाँ थोड़ा खिसकाती हैं, Home/End सीमाओं पर ले जाती हैं। पहले उन पर फ़ोकस तो जाता था पर वे कुछ नहीं करते थे, जो फ़ोकस न हो पाने से भी बुरा है।","changelog.2a6141e43be0":"बदला गया","changelog.484caa95cf9c":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>फ़िल्टर वाली क्वेरी के लिए फ़ाइल नाम खोज नाटकीय रूप से तेज़ हुई है।</strong> दस लाख फ़ाइलों पर मापने पर <code>ext:json</code> 229 ms → 11 ms (20.7×), <code>regex:^report-</code> 76 ms → 9.5 ms (7.9×), <code>*.rs</code> 60 ms → 19 ms (3.1×), और <code>report path:horizon</code> 31 ms → 12 ms (2.6×) हो गए। सादी एक-शब्द खोजें पहले से तेज़ थीं और अपरिवर्तित हैं। यह चार बदलावों से हुआ: ये क्वेरी-रूप अब हर इंडेक्स किए गए नाम पर चलने के बजाय एक ट्राइग्राम सीड बनाते हैं; नाम इंडेक्स हर पंक्ति का एक्सटेंशन, आकार, तिथि और विशेषता बिट साथ रखता है, ताकि इन फ़िल्टरों का उत्तर SQLite से हर मेल खाती पंक्ति लाने के बजाय मेमोरी से दिया जा सके; किसी डायरेक्टरी का पथ उसमें मौजूद हर फ़ाइल के लिए एक बार के बजाय केवल एक बार संग्रहीत होता है, जिससे <code>path:</code> पंक्तियों को लाए जाने से पहले ही खारिज कर सकता है; और लंबा शब्द टाइप करने पर अब नए सिरे से शुरू करने के बजाय पिछले कीस्ट्रोक के परिणामों को ही सीमित किया जाता है। Linux पर 200 000 फ़ाइलों के साथ हर बेंचमार्क परिदृश्य अब 8 ms से कम है। पूरी तालिकाओं, जिस मशीन पर उन्हें मापा गया, और आपकी मशीन पर परिणाम अलग क्यों होंगे — इन सबके लिए README का <strong>Search performance</strong> अनुभाग देखें।","changelog.89b30b76bb7e":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>क्विक फ़िल्टर अब आपकी डिस्क के कहीं बड़े हिस्से को कवर करते हैं।</strong> ऑडियो 22 एक्सटेंशन से 65 पर पहुँचा, वीडियो 23 → 79, छवि 24 → 77, दस्तावेज़ 25 → 86, संग्रह 23 → 70। Everything के अपने फ़िल्टरों में शामिल हर एक्सटेंशन अब यहाँ मौजूद है — एक टेस्ट द्वारा जाँचा गया जो उन्हें एक-एक करके नाम से गिनाता है — इसलिए जो कुछ आप Everything में किसी फ़िल्टर के तहत पा सकते थे, वह यहाँ गायब नहीं होता। जोड़े गए प्रारूप वे हैं जो Everything के डिफ़ॉल्ट बनने के बाद आए: Opus, AVIF, JXL, HEIC, हर बड़े निर्माता के camera RAW, zstd, OpenDocument, ई-बुक, और Apple iWork प्रारूप। आप इन्हें टाइप भी कर सकते हैं, उन्हीं उपनामों के साथ जिनका आप अनुमान लगाएँगे — <code>music:</code>, <code>movies:</code>, <code>photos:</code>, <code>docs:</code>, <code>compressed:</code>, <code>zip:</code>। सोर्स कोड <strong>दस्तावेज़</strong> से बाहर रहता है (Everything इसमें <code>c</code>/<code>cpp</code>/<code>h</code>/<code>java</code> भी शामिल कर लेता है); पुराना सेट <code>ext:c;cpp;h</code> से मिलता है।","changelog.170d6493da10":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>आपकी डिस्क के बड़े हिस्से पर लगने वाला फ़िल्टर अब धीमा नहीं है।</strong> ऑडियो या संपीड़ित चुनने पर पहले हर इंडेक्स की गई पंक्ति पर एक-एक करके जाया जाता था, क्योंकि साठ एक्सटेंशन का union ट्राइग्राम इंडेक्स का उपयोग नहीं कर सकता — उनमें से किसी एक पर सीमित करने से बाकी उनसठ के मिलान छूट जाते। Freally अब इसके बजाय अपने एक्सटेंशन कॉलम को सीधे मेमोरी में क्रम से पढ़ता है, प्रति पंक्ति चार बाइट। 2.7 मिलियन फ़ाइलों पर मापने पर, उनके पाँचवें हिस्से से मेल खाने वाला फ़िल्टर सबसे धीमे क्वेरी-रूप से सबसे तेज़ बन गया।","changelog.30a936879584":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>परिणाम-संख्या अब मिलानों की संख्या है, स्क्रीन पर दिख रही पंक्तियों की संख्या नहीं।</strong> पाँच लाख फ़ाइलों से मेल खाने वाला फ़िल्टर यही बताता है, जैसे Everything का &quot;531,129 objects&quot; बताता है, जबकि अब भी केवल वही पेज लाया जाता है जो आपको दिख रहा है। जब कोई क्वेरी इतनी व्यापक हो कि कैंडिडेट की ऊपरी सीमा तक पहुँच जाए, तो संख्या को न्यूनतम सीमा के रूप में बताया जाता है, न कि ऐसी संख्या के रूप में जो सटीक दिखे पर हो नहीं।","changelog.6af3be76b723":"<strong>[सभी प्लेटफ़ॉर्म]</strong> क्विक फ़िल्टर अब फ़ाइल के नाम में आख़िरी बिंदु के बाद जो भी हो, उस पर नहीं, बल्कि फ़ाइल के वास्तविक एक्सटेंशन पर मेल खाते हैं। <code>.jsonrc</code> जैसी dotfile का कोई एक्सटेंशन नहीं होता, इसलिए वह अब JSON क्विक फ़िल्टर में नहीं दिखती — <code>ext:json</code> हमेशा से यही करता था, और अब दोनों एकमत हैं।","changelog.d37659a5fceb":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>बड़ी डिस्क की इंडेक्सिंग लगभग 20× तेज़ है।</strong> स्कैन के दौरान हर कमिट अब तक देखे गए हर फ़ाइल नाम पर एक क्रमबद्ध इंडेक्स फिर से बनाता था — 200 000 फ़ाइलों पर 1.4 सेकंड के कमिट में से 1.34 सेकंड इसी में जाते थे, और स्कैन जितना आगे बढ़ता, यह उतना बिगड़ता जाता। जो यह बनाता था, उसे कुछ भी नहीं पढ़ता था। कई मिलियन फ़ाइलों वाली ड्राइव का पहला स्कैन घंटों से घटकर मिनटों का हो गया।","changelog.e2099089ef3b":"<strong>[सभी प्लेटफ़ॉर्म]</strong> मेनू के सबमेनू <strong>क्लिक-से-पिन</strong> होते हैं। एक क्लिक सबमेनू को खुला रखता है, पॉइंटर उसके बाद कहीं भी जाए — ट्रैकपैड को यही चाहिए और स्वचालित टेस्ट को भी; होवर करने पर वे अब भी खुलते हैं।","changelog.fb8d168729ab":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>freally index pause</code> और <code>resume</code> अब हर पता लगाए गए वॉल्यूम पर <code>monitor_changes</code> सेट करके वास्तव में रोकते और फिर से शुरू करते हैं। पहले इनमें से हर एक कोई असंबंधित सेटिंग कुंजी भेजता था और सफलता छाप देता था।","changelog.1246fc93bca0":"ठीक किया गया","changelog.40cc68328345":"<strong>[सभी प्लेटफ़ॉर्म]</strong> सूचकांक स्वास्थ्य पैनल हर 2 s पर पोल करने के बजाय मुख्य थ्रेड को पूरी तरह जकड़ लेता था और डेमन पर <code>index_health</code> कॉल की बौछार करता था, उतनी तेज़ी से जितनी तेज़ी से वह उत्तर दे सके। उसका <code>$effect</code> पोलर को इनलाइन शुरू करता था, और पोलर वही स्टेट पढ़ता-लिखता है जिसकी सदस्यता effect उसके बाद ले लेता था, इसलिए हर उत्तर उसे फिर से शुरू कर देता था। पैनल अनुपयोगी था और उसके खुले रहने तक ऐप प्रतिक्रिया देना बंद कर देता था। यह M13 से शिप हो रहा था; जो e2e spec इसे पकड़ लेता, वह एक असंबंधित कारण से <code>test.fixme</code> था।","changelog.3e288bea5aec":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>path:</code> और <code>parent:</code> हर हाइड्रेट की गई पंक्ति के लिए एक लोअरकेस स्ट्रिंग आवंटित करते थे, जबकि <code>path:</code> के पास पहले से एक कैश की गई प्रति थी।","changelog.760a29ec7c23":"<strong>[सभी प्लेटफ़ॉर्म]</strong> डायलॉग में दो तरह की कोने की त्रिज्या और तीन तरह की ड्रॉप शैडो थीं, क्योंकि <code>Modal</code> का इनलाइन <code>style</code> prop चुपचाप shell की अपनी class पर भारी पड़ता है। prop अब केवल माप (metrics) के लिए है, और इसे लाँघकर आगे जाने की कोशिश dev में रिपोर्ट होती है।","changelog.adfeb89fa1aa":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>दृश्य → प्रदर्शन प्रारूप → आकार प्रारूप</strong> के छह विकल्पों में से दो कुछ नहीं करते थे। सेटिंग स्कीमा <code>b | kb | mb | gb | auto_binary | auto_decimal</code> देता है; <code>formatBytes</code> पाँच मानों वाली एक अलग शब्दावली स्वीकार करता था, और हर call site ने cast करके इस असंगति को दरकिनार कर दिया था, इसलिए <code>b</code> और <code>auto_decimal</code> बाइनरी auto शाखा में जा गिरते थे। अब एक ही शब्दावली है, <code>auto_decimal</code> हज़ार की इकाइयों में गिनता है, और हर विकल्प एक टेस्ट से पक्का किया गया है।","changelog.8fe7422dc893":"<strong>[सभी प्लेटफ़ॉर्म]</strong> असली इंस्टॉल पर गुण कॉलम जोड़ना चुपचाप विफल हो जाता। TypeScript के <code>ColumnId</code> में <code>prop:&lt;key&gt;</code> रूप जुड़ गया; Rust वाला छह वेरिएंट का बंद enum ही रहा, इसलिए <code>settings_set</code> ने <code>unknown variant</code> के साथ पूरा पैच अस्वीकार कर दिया — केवल वह कॉलम नहीं — और UI ने इसे लॉग करके काम जारी रखा। Rust पक्ष अब <code>prop:&lt;key&gt;</code> को गुण रजिस्ट्री के विरुद्ध सत्यापित करता है, जिससे स्कीमा बंद बना रहता है। कॉलम जोड़ने वाला Playwright टेस्ट IPC mock पर चलता है और इसे पकड़ नहीं सकता था; अब <code>settings.rs</code> के तीन round-trip टेस्ट इसे पकड़ते हैं।","changelog.c4182c80506c":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>property:</code> नेमस्पेस से कोई भी टेक्स्ट या बूलियन गुण पहुँच में नहीं था। ग्रामर का <code>=</code> विभाजक मान तक पहुँच जाता था, इसलिए <code>property:camera-make=canon</code> शाब्दिक <code>=canon</code> खोजता था और कुछ नहीं लौटाता था, जबकि <code>property:has-alpha=yes</code> त्रुटि देता था। केवल संख्यात्मक और तिथि प्रकार ही इसे हटाते थे।","changelog.9d558fa75e7e":"<strong>[सभी प्लेटफ़ॉर्म]</strong> किसी भी non-ASCII मान के लिए टेक्स्ट गुण का मिलान एक दिशा में केस-संवेदी था: needle को पार्स के समय <code>to_ascii_lowercase</code> से फ़ोल्ड किया जाता था और पंक्ति के मान को मिलान के समय पूर्ण-Unicode <code>to_lowercase</code> से, इसलिए <code>camera-model:MÜLLER</code> कभी <code>Müller</code> नहीं ढूँढ पाता था।","changelog.a37ae4d3cefc":"<strong>[सभी प्लेटफ़ॉर्म]</strong> किसी गुण कॉलम से क्रमबद्ध करने पर अवरोही क्रम में वे पंक्तियाँ, जिनमें वह गुण <em>नहीं</em> था, दस्तावेज़ में बताए अनुसार आख़िर में आने के बजाय सबसे पहले आती थीं — comparator एक निश्चित <code>1</code> लौटाता था जिसे दिशा-गुणक फिर ऋणात्मक कर देता था। जहाँ सबसे बड़े मान होने चाहिए थे, वहाँ खाली पंक्तियों का एक पूरा पेज दिखता था।","changelog.1847045d095f":"<strong>[सभी प्लेटफ़ॉर्म]</strong> टाइप-फ़िल्टर चिप पर क्लिक करने से डेमन से पुराना कॉलम सेट माँगा जाता था: स्वचालित लेआउट तब लागू होता था जब चयन में बदलाव खोज को पहले ही ट्रिगर कर चुका होता, इसलिए नए गुण कॉलम तब तक खाली रेंडर होते थे जब तक कोई असंबंधित कीस्ट्रोक फिर से खोज न करे।","changelog.39af32b4d343":"<strong>[सभी प्लेटफ़ॉर्म]</strong> गुण-लेंस की सेटिंग डेमन रीस्टार्ट के बाद बनी नहीं रहती थीं। डेमन की ओर कुछ भी स्थायी रूप से सहेजा नहीं जाता, और उन्हें केवल सेटिंग <em>सहेजने</em> पर ही भेजा जाता था, इसलिए जिस लेंस को उपयोगकर्ता ने बंद किया था — या गोपनीयता मोड ने बंद किया था — वह अगली बार डेमन शुरू होने पर फिर चालू हो जाता था, जबकि UI उसे बंद ही दिखाता रहता। लोड की गई सेटिंग अब स्टार्टअप पर डेमन को फिर से भेजी जाती हैं।","changelog.426b2fbb21fa":"<strong>[सभी प्लेटफ़ॉर्म]</strong> कॉलम जोड़ने वाला मेनू स्क्रीन से बाहर खुलता था। उसे खोलने वाला <code>+</code> विंडो के दाएँ किनारे पर पिन है, इसलिए बिना clamp किए <code>left: clientX</code> ने एक पतली पट्टी छोड़कर पूरा मेनू किनारे के पार पहुँचा दिया, और स्क्रॉल करने को कुछ नहीं था।","changelog.1be320f46969":"<strong>[सभी प्लेटफ़ॉर्म]</strong> एक दूषित छवि हेडर मेगापिक्सेल की गणना करते समय <code>i64</code> को overflow कर सकता था — <code>0xFFFFFFFF</code> का वर्ग <code>i64::MAX</code> से आगे है — जिससे debug बिल्ड panic करता था और release बिल्ड को ऋणात्मक संख्या मिलती थी।","changelog.ffa5958e11a4":"<strong>[सभी प्लेटफ़ॉर्म]</strong> वायर पर आया <code>0</code> का <code>property_budget_ms</code> चुपचाप पूरे लेंस को no-op बना देता था: हर निष्कर्षण अपनी समय-सीमा पहले ही पार करके शुरू होता था और हर फ़ाइल बिना गुणों और बिना त्रुटि के लौटती थी। सेटिंग का स्पिनर एक न्यूनतम मान लागू करता था; वायर नहीं करता था। अब पहुँचते ही इसे न्यूनतम मान तक उठा दिया जाता है।","changelog.065a03b57ec4":"<strong>[सभी प्लेटफ़ॉर्म]</strong> कोई भी गुण समूह बंद होने पर हर कैश हिट पूरे गुण मैप की deep copy बनाता था — वही प्रति-पंक्ति आवंटन जिससे बचने के लिए साझा <code>Arc</code> मौजूद है, और जब तक वह सेटिंग लागू रहती, हर क्वेरी की हर पंक्ति पर इसकी क़ीमत चुकानी पड़ती थी। फ़िल्टर किया गया व्यू अब हर एंट्री के लिए memoize होता है और सेट बदलने पर हटा दिया जाता है।","changelog.1f99920ac00d":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>length:</code> की री-राइटिंग हर खोज के हर कीस्ट्रोक पर पूरे क्वेरी AST पर चलती थी और उसकी deep copy बनाती थी, उन खोजों में भी जिनमें <code>length:</code> था ही नहीं, क्योंकि डेमन हमेशा एक गुण प्रदाता (property provider) जोड़ता है।","changelog.8f6fb4eb7f42":"सुरक्षा","changelog.1a1f843d10c5":"<strong>[Windows]</strong> किसी शॉर्टकट का लक्ष्य एक अविश्वसनीय फ़ाइल से निकले बाइट होता है, और <code>broken-link:</code> का उत्तर देने के लिए उस पर <code>Path::exists</code> कॉल करना पड़ता था। Windows पर यह एक UNC पथ को SMB redirector को सौंप देता है, जो नामित होस्ट से कनेक्ट होकर लॉग-इन उपयोगकर्ता के NTLM क्रेडेंशियल पेश कर देता है — यह क्लासिक shell-link forced-authentication primitive है, और केवल इंडेक्सिंग से ही यह ट्रिगर हो जाता, हर फ़ाइल पर एक handshake, बिना कुछ क्लिक किए। <code>\\attacker\\share\\x</code> की ओर इशारा करने वाली <code>.lnk</code> फ़ाइलों का एक फ़ोल्डर किसी भी निगरानी वाली डायरेक्टरी में डाल देना ही काफ़ी था। लक्ष्यों को अब resolve करने से पहले UNC और URL रूपों के लिए जाँचा जाता है, और दूरस्थ लक्ष्य होने पर <code>broken-link</code> को जाँचने के बजाय अनसेट छोड़ दिया जाता है। यही सुरक्षा symlink लक्ष्यों पर भी लागू है, जो किसी भी आर्काइव के भीतर इसी तरह आते हैं।","changelog.c599b83df9e1":"<strong>[Windows]</strong> Authenticode सत्यापन <code>dwProvFlags: 0</code> के साथ चलता था। <code>WTD_REVOKE_NONE</code> CRL और OCSP को रोकता है, पर chain engine के AIA fetch को नहीं, इसलिए कोई self-signed बाइनरी, जिसके प्रमाणपत्र में <code>http://attacker/&lt;unique&gt;.cer</code> लिखा हो, इंडेक्सिंग को एक read receipt में बदल देती — पहुँच गया, यह IP, यह समय — और वह भी उस डेमन से जिसका गोपनीयता पैनल कोई बाहरी अनुरोध न करने का वादा करता है। अब इसे <code>WTD_CACHE_ONLY_URL_RETRIEVAL | WTD_REVOCATION_CHECK_NONE</code> पर पक्का कर दिया गया है।","changelog.4118fb4fed0e":"हटाया गया","changelog.7e47a128e1ba":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <strong>ऑफ़लाइन वॉल्यूम स्वतः हटाएँ</strong> सेटिंग। यह कुछ भी नियंत्रित नहीं करती थी — किसी कोड ने इसे कभी पढ़ा ही नहीं — और यह जिस व्यवहार का वर्णन करती थी, वह शिप हुए व्यवहार का ठीक उल्टा है: अनप्लग किया गया वॉल्यूम जानबूझकर एक ऑफ़लाइन कैटलॉग के रूप में <em>रखा</em> जाता है, ताकि उसकी पंक्तियाँ खोजने योग्य और बैज के साथ बनी रहें। इसे लिखे अनुसार लागू करने पर, डिफ़ॉल्ट रूप से चालू होने के कारण, हर अनप्लग की गई ड्राइव का इंडेक्स मिट जाता।","changelog.706f136720e0":"<span class=\"release__meta\"><span class=\"release__ver\">v0.23.2</span><time class=\"release__date\" datetime=\"2026-08-19\">2026-08-19</time></span><span class=\"release__title\">अपडेटर कुंजी रोटेशन और CI मरम्मत</span>","changelog.31b4f34d5ada":"<code>0.23.1</code> जैसा ही ऐप्लिकेशन, जिसे टैग किया गया था पर जिसकी रिलीज़ प्रकाशित होने के बजाय बदल दी गई। नीचे <code>0.23.1</code> अनुभाग की हर चीज़ यहाँ शिप होती है; आगे वही है जो उसके ऊपर बदला।","changelog.965ce76814aa":"<strong>नई अपडेटर साइनिंग कुंजी।</strong> <code>0.23.1</code> तक की रिलीज़ <code>9F291C936CFA28B7</code> से हस्ताक्षरित थीं, जिसका निजी हिस्सा केवल एक GitHub repository secret के रूप में मौजूद था। Repository secrets को वापस पढ़ा नहीं जा सकता, इसलिए उस कुंजी को न कॉपी किया जा सकता था, न स्थानांतरित, न पुनः प्राप्त — और अब वह जा चुकी है। <code>0.23.2</code> से आगे की रिलीज़ <code>E5035E2194EB7E04</code> से हस्ताक्षरित हैं, जिसका निजी हिस्सा, पासवर्ड और सार्वजनिक हिस्सा एक साथ GitHub के बाहर संग्रहीत हैं।","changelog.926a99810869":"<strong>इससे <code>0.23.1</code> या उससे पुराने किसी भी इंस्टॉल का अपडेटर टूट जाता है</strong>: पुरानी बाइनरी एक ऐसी सार्वजनिक कुंजी के विरुद्ध सत्यापन करती हैं जो अब किसी चीज़ पर हस्ताक्षर नहीं करती, इसलिए अपडेट इंस्टॉल होने के बजाय हस्ताक्षर सत्यापन में विफल होगा। नीचे दिए डाउनलोड से दोबारा इंस्टॉल करें। किसी इंस्टॉल के प्रभावित होने की जानकारी नहीं है — हर पिछली रिलीज़ की डाउनलोड संख्या नियमित link-checking से मेल खाती थी।","changelog.95ee6438be83":"<strong><code>apt-get update</code> किसी Linux बिल्ड को अनिश्चित काल तक अटका सकता था।</strong> runner images जिस Ubuntu मिरर को प्राथमिकता देती हैं, <code>azure.archive.ubuntu.com</code>, उसने कई घंटों तक पूरे jammy index सेट के लिए कुछ नहीं लौटाया, और कोई timeout कॉन्फ़िगर न होने से step विफल होने के बजाय प्रतीक्षा करता रहा — 72 सेकंड की baseline के मुक़ाबले एक घंटे तक, चार बार, और हर बार हाथ से रद्द करना पड़ा। बिल्ड अब <code>archive.ubuntu.com</code> का उपयोग करते हैं, step को दस मिनट पर सीमित करते हैं, और फिर से प्रयास करते हैं। बाद में यही step 41 सेकंड में चला।","changelog.7f5127beca31":"<strong>release workflow पर <code>workflow_dispatch</code> गलत ट्री बिल्ड करता था।</strong> यह इनपुट के रूप में एक टैग लेता है और किसी रिलीज़ को फिर से बिल्ड करने का प्रलेखित तरीका है, पर इसके checkout step में कोई <code>ref</code> नहीं था, इसलिए यह उसी ब्रांच को checkout करता था जिससे इसे dispatch किया गया था, जबकि artifacts का नाम इनपुट टैग के अनुसार रखता था।","changelog.e492554f1e26":"<strong>wall-clock बजट वाले टेस्ट CI में पूरे समानांतर लोड के तहत चलते थे।</strong> <code>scripts/ci-local.mjs</code> को बदलकर उन्हें अकेले चलाया जाने लगा था — क्योंकि nextest का प्रति-टेस्ट-एक-प्रोसेस मॉडल मशीन पर लगातार लोड डालता है और तब assertion लोड को ही मापने लगता है — पर CI उन्हें बाकी सब के साथ ही चलाता रहा, इसलिए ठीक उन्हीं टेस्ट के लिए, जिन्हें दोहराना सबसे कठिन है, स्थानीय गेट CI का पूर्वानुमान देना बंद कर चुका था। CI अब अपने nextest step को उसी तरह बाँटता है, और साझा runners पर, जहाँ माप का अर्थ कम है, ऊपरी सीमा बढ़ा दी गई है।","changelog.17a56bd3bbd4":"<strong>दो प्रति-OS clippy त्रुटियाँ</strong> <code>shell_actions/macos.rs</code> और <code>shell_actions/linux.rs</code> में, जिन्हें कोई Windows बिल्ड कंपाइल नहीं करता और जिन तक <code>src-tauri</code> लिंट गेट इस बार पहली बार पहुँचा।","changelog.c205924de0fe":"दस्तावेज़ीकरण","changelog.9c50b38011d4":"<code>README.md</code> चार रिलीज़ बीत जाने के बाद भी <code>v0.19.84</code> को आने वाली पहली रिलीज़ बता रहा था, और ऐसे पाँच दस्तावेज़ों से लिंक करता था जो इस रिपॉज़िटरी का हिस्सा नहीं हैं।","changelog.4395f6d7c73f":"साइट पर डाउनलोड आकार <code>0.23.0</code> के थे, जो लिंक के साथ ही आगे चले आए थे।","changelog.b2bfece1a5c5":"<span class=\"release__meta\"><span class=\"release__ver\">v0.23.1</span><time class=\"release__date\" datetime=\"2026-08-19\">2026-08-19</time></span><span class=\"release__title\">बिल्ड 4 की नींव · बिल्ड 3 का हैंडऑफ़, पूरा किया गया</span>","changelog.957188896a81":"बिल्ड 4 की नींव — बिल्ड 3 के हैंडऑफ़ को पूरा करना","changelog.4dce861a35f4":"v0.23.0 के बाद पिछले हैंडऑफ़ ने जो कुछ खुला छोड़ा था, वह सब, और साथ में इसे करते हुए मिले तीन बग। कोई नई सुविधा नहीं; यह सफ़ाई का वह दौर है जिसके ऊपर बिल्ड 4 का गुण-लेंस वाला काम टिका है।","changelog.116b07733767":"<strong><code>Search →</code> मेनू कुछ नहीं करता था।</strong> SRC-M23 ने <code>query.ts</code> से सभी सात match-mode फ़्लैग भेजे और डेमन के <code>QueryRunParams</code> को सातों पढ़ना सिखाया — पर बीच वाले Tauri कमांड ने उनमें से एक भी घोषित नहीं किया, और Tauri उन invoke तर्कों को चुपचाप गिरा देता है जिनका नाम कमांड में न हो। हर फ़्लैग executor तक अपने <code>serde</code> डिफ़ॉल्ट के रूप में पहुँचता था, इसलिए केस मिलाएँ, पूरा शब्द मिलाएँ, पथ मिलाएँ, डायाक्रिटिक्स मिलाएँ, ध्वन्यात्मक मिलान, विराम-चिह्न अनदेखा करें और रिक्त स्थान अनदेखा करें — हर एक बस एक चेकमार्क खिसकाता था और कुछ नहीं बदलता था। <code>commands/query.rs</code> में अब इनके उतरने की जगह <code>QuerySearchOpts</code> है, और <code>tests/unit/query_wire.test.ts</code> दोनों ओर तर्कों के नाम पक्के करता है।","changelog.3258356b0cdb":"<strong>केस मिलाएँ दोनों दिशाओं में गलत था।</strong> इसे चालू करने पर अपरकेस क्वेरी <em>कुछ नहीं</em> लौटाती थी और लोअरकेस क्वेरी तब भी केस-असंवेदी ढंग से मेल खाती थी। नाम इंडेक्स लोअरकेस कुंजियाँ संग्रहीत करता है, इसलिए कैंडिडेट पूर्व-फ़िल्टर के पास जाँचने के लिए केस वाला टेक्स्ट नहीं था और वह हाइड्रेशन के असली नाम देख पाने से पहले ही हर पंक्ति को खारिज कर देता था। यह ज्ञात था और टाल दिया गया था — एक टेस्ट टूटे हुए व्यवहार को सही ठहराता था और चरण-13 के एक इंडेक्स बदलाव की ओर इशारा करता था। उसकी ज़रूरत नहीं थी: केस मिलाएँ अब पूर्व-फ़िल्टर को छोड़ देता है, ठीक वैसे ही जैसे पथ मिलाएँ पहले से करता था, और predicate पंक्ति के असली नाम पर चलता है। ट्राइग्राम सीड फिर भी लागू होता है, क्योंकि वह लोअरकेस needle से बनता है और इसलिए केस वाले उत्तर का एक superset चुनता है, जिसका अर्थ है कि इसकी क़ीमत पूरे स्कैन के बजाय एक हाइड्रेशन है। <code>child:</code>, <code>name^:</code> और <code>name$:</code> को भी इसी रास्ते भेजा गया।","changelog.3fdb374f585c":"<strong>कोई भी सेटिंग सहेजी नहीं जा रही थी।</strong> <code>custom_commands</code> का एक डिफ़ॉल्ट था और पूरा सेटिंग → कस्टम कमांड पैनल था, पर वह <code>ALLOWED_PATCH_KEYS</code> से गायब था। <code>settings_set</code> पहली अज्ञात शीर्ष-स्तरीय कुंजी मिलते ही पैच अस्वीकार कर देता है, और UI का <code>flush()</code> पूरा स्टेट भेजता है — जिसमें <code>custom_commands</code> हमेशा होता है — इसलिए हर सेव एक console चेतावनी में विफल हो जाता था। अनुमति-सूची अब स्कीमा से निकाली जाती है (<code>allowed_patch_keys()</code>), और इसी से यह कमी सामने आई।","changelog.be64658b8045":"<strong><code>child:</code> / <code>name^:</code> / <code>name$:</code> क्वेरी के बाकी हिस्से के अनुसार अलग-अलग उत्तर देते थे।</strong> नाम-इंडेक्स पास इन्हें पूरी नॉर्मलाइज़ेशन सीढ़ी से गुज़ारता था जबकि हाइड्रेटेड पास कच्ची स्ट्रिंग की तुलना करता था, और दोनों पास हर क्वेरी पर चलते हैं — इसलिए हाइड्रेशन को बाध्य करने वाला कोई भी मॉडिफ़ायर जोड़ने पर फ़ैसला सख़्त वाले के हाथ चला जाता था। <code>name^:cafe</code> अकेले <code>café-notes.txt</code> ढूँढ लेता था और <code>size:</code> जोड़ते ही उसे ढूँढना बंद कर देता था।","changelog.35d326e420f1":"<strong>Escape कभी कोई डायलॉग बंद नहीं करता था।</strong> हैंडलर backdrop पर था, जो बिना tabindex का एक <code>role=&quot;presentation&quot;</code> div है, इसलिए उसे keydown मिल ही नहीं सकता था — और पैनल वैसे भी propagation रोक देता था। अब यह साझा <code>&lt;Modal&gt;</code> में, <code>window</code> पर रहता है।","changelog.4f4a3883a9bb":"<strong>प्राकृतिक क्रम केवल क्लाइंट-साइड था।</strong> <code>SortSpec.natural</code> डिफ़ॉल्ट रूप से <code>true</code> था और उसे कभी कुछ सेट नहीं करता था, इसलिए सेटिंग → परिणाम → <em>प्राकृतिक क्रम</em> UI का comparator बंद कर देता था और <code>freally search --json</code> फिर भी प्राकृतिक क्रम में ही रहता था। यह सेटिंग अब वायर के पार जाती है।","changelog.1eb006c07967":"<strong><code>src-tauri</code> लिंट नहीं होता था।</strong> यह वर्कस्पेस से बाहर रखा गया है, इसलिए <code>cargo clippy --workspace</code> ने इसे कभी देखा ही नहीं और तीन त्रुटियाँ चुपचाप विफल हो रही थीं। CI में अब उस मैनिफ़ेस्ट के लिए अपना step है। निष्क्रिय <code>log_event</code> कमांड — जो TS→Rust debug bridge के रूप में प्रलेखित था पर कभी पंजीकृत नहीं हुआ, इसलिए उसे की गई हर कॉल विफल होती थी — हटा दिया गया है।","changelog.17d4993eb122":"<strong>कस्टम कमांड अब सीमित हैं और उनके आकार की जाँच होती है।</strong> <code>custom_commands</code> एकमात्र सेटिंग है जिसका मान <em>चलाए जाने वाले प्रोग्राम</em> का नाम बताता है, और यह बिना किसी सत्यापन के <code>settings_set</code> तक पहुँचती थी — क्योंकि इस बिल्ड से पहले यह <code>settings_set</code> तक कभी पहुँचती ही नहीं थी (ऊपर देखें)। अब इस पर उसी तरह की सीमाएँ हैं जैसी हर दूसरे असीमित फ़ील्ड पर हैं — कमांड की संख्या पर, <code>id</code>/<code>name</code>/<code>program</code> की लंबाई पर, और इसकी दोनों स्ट्रिंग सूचियों, <code>args</code> और <code>extensions</code>, पर।","changelog.efc94af8b3c4":"<strong>सेटिंग फ़ाइल आयात करने से अब चुपचाप लॉन्चर इंस्टॉल नहीं होते।</strong> सेटिंग → बैकअप → <em>सेटिंग आयात करें</em> उपयोगकर्ता द्वारा दी गई JSON को सीधे सेटिंग स्टोर में पढ़ लेता है। इसलिए एक साझा &quot;Freally preset&quot; हर परिणाम के संदर्भ मेनू में एक कस्टम कमांड — चलाने के लिए एक प्रोग्राम — जोड़ सकता था, उसके लेखक द्वारा चुने गए लेबल के तहत, बिना कुछ बताए। आयात अब प्रोग्रामों के नाम बताकर पूछता है; मना करने पर बाकी सब आयात हो जाता है। <code>docs/SECURITY.md</code> शेष सीमा को साफ़ शब्दों में बताता है: जो कुछ भी सेटिंग लिख सकता है, वह कोई प्रोग्राम नामित कर सकता है।","changelog.442aded87a55":"प्रदर्शन","changelog.ee0c64c3999a":"<strong>विराम-चिह्न अनदेखा करें / रिक्त स्थान अनदेखा करें अब पूरे इंडेक्स को स्कैन नहीं करते।</strong> ये मोड तुलना से पहले टेक्स्ट को बदल देते हैं, इसलिए कच्चे नाम के ट्राइग्राम needle का वर्णन नहीं करते थे और executor हर नाम पर चलने लगता था। अब यह विराम-चिह्न और रिक्त स्थान हटाए गए नामों पर बने पोस्टिंग्स के एक समानांतर सेट से सीड लेता है। यह पहली बार उपयोग पर लेज़ी ढंग से बनता है और उसके बाद क्रमिक रूप से अपडेट होता है, इसलिए जो उपयोगकर्ता इनमें से कोई मोड कभी चालू नहीं करता, उसे इसकी क़ीमत कभी नहीं चुकानी पड़ती।","changelog.2bfd60f4ad05":"<strong>तीन के बजाय एक नॉर्मलाइज़ेशन सीढ़ी।</strong> <code>substring_match</code>, <code>anchored_match</code> और <code>literal_match</code> तीनों अलग-अलग case-fold → strip-diacritics → strip-ignored से गुज़रते थे और पहले ही एक-दूसरे से भटक चुके थे। अब वे <code>normalized</code> साझा करते हैं, जो किसी पायदान के पास करने को कुछ न होने पर आवंटन के बजाय borrow करता है — डिफ़ॉल्ट मोड में ASCII लोअरकेस नाम का आम मामला अब प्रति पंक्ति कुछ भी आवंटित नहीं करता।","changelog.40253ba25a46":"<strong>needle अब हर कैंडिडेट पंक्ति के लिए एक बार नहीं, बल्कि हर क्वेरी में एक बार नॉर्मलाइज़ होते हैं।</strong>","changelog.23f1c76bd888":"वेवफ़ॉर्म bucketing अब हर डिकोड किए गए फ़्रेम पर भाग देने के बजाय अपनी bucket सीमा साथ रखती है (तीन मिनट के स्टीरियो ट्रैक पर ~8 M भाग); permission ledger रैखिक स्कैन के बजाय <code>HashSet</code> से डुप्लिकेट हटाता है; और हाल की खोज दर्ज करते समय अब हर कीस्ट्रोक पर ~180-कुंजी वाले सेटिंग रूट को spread करके फिर से असाइन नहीं किया जाता।","changelog.64ff3a4bbdfd":"<strong>Freally Central हटा दिया गया है</strong> — vendored ट्री, वह <code>.gitmodules</code> stanza जो एक ऐसे सबमॉड्यूल का नाम लेता था जिसे git में कभी पंजीकृत ही नहीं किया गया था, React island और उसकी पाँच डिपेंडेंसी, <em>और Freally ऐप्स</em> डायलॉग और मेनू आइटम, उसकी लोकेल स्ट्रिंग, और दस्तावेज़ीकरण साइट पर उसकी प्रविष्टियाँ।","changelog.36e12a600874":"<strong>एक साझा <code>&lt;Modal&gt;</code></strong> उस backdrop / panel / Escape / <code>tabindex</code> वाली कवायद की जगह लेता है जिसे सात डायलॉग अलग-अलग ख़ुद लिखते थे, और सभी छह लंबित <code>a11y_interactive_supports_focus</code> चेतावनियाँ दूर करता है। <code>HitViewer</code>, <code>QuickLook</code>, <code>RegexBuilder</code> और प्रथम-रन विज़ार्ड जानबूझकर अपने-अपने shell रखते हैं — एक sibling backdrop, तीर-कुंजी नेविगेशन, एक popover, और न हटाया जा सकने वाला gate एक ही कंपोनेंट नहीं हैं।","changelog.05849c3f2c94":"<code>portable::open_log</code>, <code>service::scan</code>, <code>app_data_root</code> और <code>resultsStore.hitById</code> अपनी डुप्लिकेट प्रतियों की जगह लेते हैं।","changelog.fe8ee15bb86d":"CI","changelog.44ad89dc0cf1":"<code>cargo nextest</code> ने <code>cargo test</code> की जगह ली: 760 टेस्ट में से अधिकांश अपना Tantivy इंडेक्स बनाते हैं, और प्रति टेस्ट एक प्रोसेस उन्हें एक-दूसरे के locks से दूर रखता है। डेवलपमेंट मशीन पर warm स्थिति में मापा गया: 100s → 37s।","changelog.2892b412468b":"एक nextest test group इंडेक्स बनाने वाले पैकेजों को चार समवर्ती प्रोसेस तक सीमित करता है। इसके बिना, अतिरिक्त concurrency ने ज्ञात Windows Defender / Tantivy <code>Access is denied (os error 5)</code> race को कभी-कभार होने वाली से हर बार दोहराई जा सकने वाली बना दिया — लगातार दो रन तीन अलग-अलग टेस्ट पर विफल हुए। इस सीमा की क़ीमत ~2s है और suite अब भी <code>cargo test</code> के समय के पाँचवें हिस्से में चलता है।","changelog.f600da3213ca":"किसी ब्रांच पर पुराने पड़ चुके रन रद्द कर दिए जाते हैं; <code>main</code> को छूट है, ताकि वह उस कैश को भरता रहे जिससे हर ब्रांच restore करती है।","changelog.6811b6eaa5cb":"<code>CARGO_INCREMENTAL=0</code>, कैश केवल <code>main</code> से लिखा जाता है, हर जगह <code>--locked</code>, frozen pnpm install, और OS-निरपेक्ष गेट (<code>i18n-lint</code>, doctests) तीन के बजाय एक runner पर।","changelog.8266aee5f502":"<code>scripts/ci-local.mjs</code> में वह <code>src-tauri</code> गेट जुड़ गया जो उसमें नहीं था, और यह अपनी Rust और UI लेन समवर्ती रूप से चलाता है: 133s का काम 89s में।","changelog.b9b12625c2fd":"<span class=\"release__meta\"><span class=\"release__ver\">v0.23.0</span><time class=\"release__date\" datetime=\"2026-08-03\">2026-08-03</time></span><span class=\"release__title\">बिल्ड 3 · अनिवार्य (Must-Have) स्थिर गेट, 3 में से भाग 3</span>","changelog.c5819508ac2c":"तीन अनिवार्य (Must-Have) बिल्ड में से आख़िरी: SRC-M17 … SRC-M24। v0.23.0 के रूप में शिप होता है, <strong>स्थिर</strong> टैग।","changelog.7c2c8aacfd91":"<strong>SRC-M17 — पोर्टेबल मोड।</strong> <code>freally --portable</code>, या बाइनरी के बगल में एक ख़ाली <code>portable.flag</code> फ़ाइल, इंडेक्स, सेटिंग, बुकमार्क, जर्नल कर्सर और लॉग को executable के बगल में एक <code>Data/</code> फ़ोल्डर में रखती है, और ऐप को OS के साथ कुछ भी पंजीकृत करने से रोकती है। तीनों बाइनरी यह स्विच स्वीकार करती हैं; flag फ़ाइल ही वह चीज़ है जो डबल-क्लिक किए गए zip या AppImage को बिना किसी कमांड लाइन के पोर्टेबल बनाती है।","changelog.c081711c3fde":"यह लेआउट <code>freally_rpc::portable</code> में है — वह एकमात्र crate जिस पर Tauri shell, डेमन और CLI तीनों पहले से निर्भर हैं।","changelog.260a841f6090":"पोर्टेबल मोड जानबूझकर क्या <em>नहीं</em> करता — हर बात किसी ठोस कारण से, सिर्फ़ साफ़-सफ़ाई के लिए नहीं:","changelog.e53f7037be43":"<strong>कोई सेवा, launchd plist या systemd unit नहीं।</strong> पोर्टेबल मोड में <code>freally-indexd install</code> / <code>uninstall</code> / <code>service</code> तीनों इनकार कर देते हैं। इनमें से हर एक ऐसा पंजीकरण लिखता है जो USB स्टिक के बाद भी बना रहता है और ऐसे पथ की ओर इशारा करता है जो अगले बूट पर मौजूद नहीं होगा। <code>uninstall</code> को उल्टे कारण से मना किया जाता है: पोर्टेबल प्रति ने कभी कुछ पंजीकृत ही नहीं किया, इसलिए उसे चलने देने से होस्ट पर <em>इंस्टॉल की गई</em> प्रति का पंजीकरण हट जाता।","changelog.d1f534b3e627":"<strong><code>freally://</code> स्कीम का कोई पंजीकरण नहीं।</strong> यह मशीन-स्तर का एक हैंडलर लिखता है जो executable के मौजूदा पथ की ओर इशारा करता है; स्टिक निकालते ही उस मशीन का हर <code>freally://</code> लिंक बेसहारा लटक जाता है। इन-प्रोसेस listener फिर भी चलता है, इसलिए पोर्टेबल इंस्टेंस उसे सौंपे गए URL संभालता है — बस वह स्कीम पर दावा नहीं करता।","changelog.6320d3fbbef5":"<strong>कोई स्वतः-अपडेटर नहीं।</strong> अपडेटर एक <em>इंस्टॉलर</em> चलाता है। उसे स्टिक पर लगाने से ऐप होस्ट मशीन पर इंस्टॉल हो जाता, और पोर्टेबल उपयोगकर्ता ठीक इसी से बचना चाहता है। पोर्टेबल इंस्टॉल फ़ोल्डर बदलकर अपडेट होते हैं।","changelog.01ed92501ea3":"<strong>Windows सेवा को अपनाना नहीं।</strong> सेवा <code>%PROGRAMDATA%</code> के अंतर्गत इंस्टॉल किए गए इंडेक्स की मालिक है; उससे कनेक्ट होने वाला पोर्टेबल लॉन्च चुपचाप होस्ट के इंडेक्स में खोजता और स्टिक की गतिविधि उसमें लिख देता।","changelog.9f519044c9bf":"<strong>इंस्टेंस के पार कोई <code>taskkill</code> नहीं।</strong> single-instance प्रवर्तन image name के आधार पर प्रोसेस बंद करता है। पहले से Freally चला रही मशीन में लगाई गई स्टिक उस ऐप को बंद कर देती जिसे उपयोगकर्ता उस समय इस्तेमाल कर रहा था।","changelog.f0f408322071":"स्टेट के दो हिस्सों को स्पष्ट रूप से दूसरी जगह भेजना पड़ा, क्योंकि वे इंडेक्स रूट के नीचे नहीं आते:","changelog.ada349238a7a":"<strong>जर्नल कर्सर।</strong> हर OS subscriber डिफ़ॉल्ट रूप से अपनी प्रति-उपयोगकर्ता डायरेक्टरी इस्तेमाल करता है, इसलिए पोर्टेबल इंस्टॉल हर उस मशीन पर कर्सर छोड़ जाता जिसमें उसे लगाया गया। अब वे <code>Data/cursors</code> में जाते हैं।","changelog.8ea42f81060c":"<strong>RPC socket, जो जानबूझकर स्टिक से बाहर रहता है।</strong> स्टिक आमतौर पर FAT32 या exFAT होती है — ऐसे फ़ाइल सिस्टम जो Unix domain socket रख ही नहीं सकते, और जिनमें उस 0600 + peer-uid जाँच के लिए अनुमति बिट ही नहीं होते जिस पर transport निर्भर है। यह होस्ट की temp डायरेक्टरी में पोर्टेबल रूट से बने नाम के तहत रहता है, ताकि कोई पोर्टेबल इंस्टेंस कभी किसी इंस्टॉल किए गए इंस्टेंस या दूसरी स्टिक से न टकराए, और प्रमाणीकरण की व्यवस्था अपरिवर्तित रहे।","changelog.f576d6d3c2e0":"लॉग इसलिए स्थानांतरित होते हैं क्योंकि डबल-क्लिक की गई बाइनरी के पास विरासत में लेने को कोई console नहीं होता: दोनों प्रोसेस <code>Data/logs/</code> में लिखते हैं, और वह फ़ाइल न खुल पाने पर console पर लौट आते हैं, बजाय उन डायग्नोस्टिक्स को खोने के जो इसका कारण समझाते।","changelog.2af97df221d3":"macOS पर <code>Data/</code> <code>Freally.app</code> के बगल में बनता है, उसके अंदर नहीं — bundle के भीतर उपयोगकर्ता डेटा लिखने से code signing टूट जाती है और read-only mount पर यह सीधे विफल हो जाता है।","changelog.8b231cae5059":"<strong>इसी बदलाव में: परिचय पैनल गलत संस्करण बताता था।</strong> उसमें hardcoded <code>0.19.84</code> था और वह शिप हुए संस्करण से तीन रिलीज़ पीछे छूट चुका था। अब वह एक नए <code>app_environment</code> कमांड के ज़रिए चल रहे प्रोसेस से संस्करण पढ़ता है, जो यह भी बताता है कि क्या यह पोर्टेबल इंस्टॉल है और यह किस फ़ोल्डर में लिखता है — ताकि किसी और की मशीन में स्टिक लगाने वाला उपयोगकर्ता ऐप में ही पुष्टि कर सके कि होस्ट पर कुछ नहीं उतर रहा।","changelog.9ee660246eb6":"Smoke टेस्ट: <code>tests/smoke/build_03_portable.rs</code> असली डेमन बाइनरी की एक प्रति एक scratch डायरेक्टरी में रखता है (पोर्टेबल मोड executable के सापेक्ष परिभाषित है, इसलिए उसे अपनी जगह पर टेस्ट करने से वर्कस्पेस की हर दूसरी बाइनरी बाकी रन के लिए पोर्टेबल हो जाती) और flag फ़ाइल, स्विच, पंजीकरण के तीनों इनकार, और यह साबित करता है कि पोर्टेबल डेमन अपना इंडेक्स और अपना लॉग <code>Data/</code> में ही लिखता है, कहीं और नहीं।","changelog.b20d6ec3f044":"<strong>SRC-M24 — प्राकृतिक क्रम।</strong> नाम के भीतर अंकों के क्रम संख्याओं की तरह पढ़े जाते हैं, इसलिए <code>file2</code>, <code>file10</code> से पहले आता है और <code>v1.9</code>, <code>v1.10</code> से पहले। डिफ़ॉल्ट रूप से चालू, और सेटिंग → परिणाम → <em>प्राकृतिक क्रम</em> से बंद किया जा सकता है।","changelog.88d62d00604a":"यह केवल नाम पर नहीं, हर स्ट्रिंग कॉलम पर लागू होता है — नाम, पथ, प्रकार और एक्सटेंशन — ताकि &quot;प्राकृतिक क्रम में लगाएँ&quot; का चुपचाप अर्थ &quot;केवल नाम कॉलम को प्राकृतिक क्रम में लगाएँ&quot; न हो।","changelog.52f34cd037df":"दो comparator हैं क्योंकि दो सॉर्ट हैं: डेमन जो लौटाता है उसे क्रम में लगाता है (<code>crates/freally-query/src/natural.rs</code>) और परिणाम सूची क्लाइंट-साइड फिर से सॉर्ट करती है (<code>apps/freally-ui/src/lib/util/natural.ts</code>)। ये जानबूझकर एक जैसे नहीं हैं — UI गैर-अंक हिस्सों को <code>localeCompare</code> से गुज़ारता है ताकि accent और केस पहले जैसा ही व्यवहार करें, जबकि डेमन हमेशा लोअरकेस नाम ही देखता है — इसलिए मामलों का एक साझा vector उस संख्यात्मक व्यवहार को पक्का करता है जिस पर दोनों का सहमत होना ज़रूरी है, और इसे दोनों ओर से assert किया जाता है।","changelog.4ac049addd1f":"कुछ बातें जो बताने लायक हैं, क्योंकि हर एक इसे गलत करने का एक रास्ता है:","changelog.7548bb140901":"<strong>अंकों के क्रमों की तुलना उन्हें पार्स किए बिना होती है।</strong> पार्सिंग <code>u64</code> (या JS में 2^53) पर रुक जाती है; फ़ाइल नाम में 30 अंकों का क्रम असामान्य है पर अमान्य नहीं, और तब दो अलग-अलग बहुत लंबे क्रम बराबर माने जाते। पहले सार्थक अंकों की संख्या और फिर अंकों की तुलना किसी भी लंबाई पर सटीक है।","changelog.b4e5975dde5b":"<strong>शून्य padding बराबरी तोड़ने का अंतिम उपाय है।</strong> <code>file07</code> और <code>file7</code> एक ही संख्या हैं, इसलिए padding तभी निर्णय करती है जब और कुछ न करे — उसके दिखते ही उस पर निर्णय करने से <code>file07b</code>, <code>file7a</code> से आगे निकल जाता।","changelog.b682aa249886":"<strong>UI किसी गैर-अंक हिस्से की तुलना केवल वहाँ तक करता है जहाँ तक वह दोनों ओर मौजूद हो।</strong> कोई क्रम एक ओर किसी अंक से बीच में कट सकता है और दूसरी ओर नहीं — <code>img.png</code> बनाम <code>img1.png</code> से 7 और 3 लंबाई के क्रम मिलते हैं — और उन्हें पूरा-पूरा तुलना करने पर निर्णय <code>.</code> बनाम <code>1</code> के बजाय लंबाई पर होता है, जिससे <code>img.png</code> आख़िर में चला जाता था। साझा vector ने इसे पकड़ा।","changelog.efabda690420":"<strong>बिना अंकों वाली स्ट्रिंग अब भी पूरी की पूरी <code>localeCompare</code> से गुज़रती हैं</strong>, इसलिए आम मामले में collation ठीक पहले जैसा रहता है।","changelog.e3d8b9588796":"<strong>पथ कॉलम ही वह एक जगह है जहाँ यह टॉगल अंकों से अधिक कुछ बदलता है।</strong> प्राकृतिक क्रम बंद होने पर यह <code>PathBuf::cmp</code> ही रहता है, जो बाइट के बजाय component के अनुसार क्रम लगाता है; अंकों के क्रम देख पाने के लिए प्राकृतिक क्रम को पथ को टेक्स्ट के रूप में पढ़ना ही पड़ता है।","changelog.52750ba0909a":"<strong>बिना एक्सटेंशन वाली फ़ाइलें अब भी सबसे पहले आती हैं</strong>, जैसा <code>Option::cmp</code> करता था।","changelog.67df3bc8e4ae":"फ़ीचर विवरण कहता है कि इस क्रम का &quot;fast-sort इंडेक्स द्वारा पालन&quot; हो। पालन करने को ऐसा कोई इंडेक्स है ही नहीं: सॉर्टिंग <code>sort_rows</code> में उन कैंडिडेट पंक्तियों पर होती है जिन्हें executor पहले ही materialize कर चुका है, और आज स्टोर में सॉर्ट तेज़ करने वाला कोई इंडेक्स मौजूद नहीं है। उसे बनाना SRC-N स्तर का काम है, इसलिए इसे चुपचाप छोड़ने के बजाय स्पष्ट बताया गया है।","changelog.bd0993897678":"Smoke टेस्ट: <code>tests/smoke/build_03_natural_sort.rs</code> ऐसे नाम इंडेक्स करता है जिनकी हर प्रविष्टि पर बाइट क्रम और प्राकृतिक क्रम असहमत हैं, और डिफ़ॉल्ट, opt-out, अवरोही क्रम, पथ कॉलम, और यह पक्का करता है कि संख्यात्मक कॉलम को छुआ नहीं जाता।","changelog.b190e0af1450":"<strong>SRC-M23 — विराम-चिह्न अनदेखा करना, रिक्त स्थान अनदेखा करना, और anchored मिलान।</strong> <code>Search →</code> के अंतर्गत दो नए टॉगल (<code>Ignore Punctuation</code>, <code>Ignore Whitespace</code>) और दो नए DSL मॉडिफ़ायर, <code>name^:report</code> (इससे शुरू होता है) और <code>name$:final</code> (इस पर ख़त्म होता है)।","changelog.e35e30b09372":"<strong>चारों मौजूदा मिलान टॉगल अब वास्तव में कुछ करते हैं।</strong> बिल्ड 2 तक केवल <code>match_phonetic</code> वायर के पार जाता था: <code>Match Case</code>, <code>Match Whole Word</code>, <code>Match Path</code> और <code>Match Diacritics</code> बस एक चेकमार्क खिसकाते थे और कुछ नहीं बदलते थे, क्योंकि <code>query.run</code> केवल वही एक फ़्लैग भेजता था और डेमन <code>MatchMode</code> को <code>Default</code> से बनाता था। executor पूरे समय पाँचों का पालन करता रहा था। अब पूरा सेट भेजा और पढ़ा जाता है।","changelog.827fa9647b52":"<strong>इसे जोड़ते समय मिला एक संबंधित बग: <code>Match CJK Phonetics</code> कभी सहेजा नहीं जाता था।</strong> <code>settings_set</code> सेटिंग struct को फिर से serialize करके परिणाम को वापस पार्स करता है, और Rust के <code>SearchOpts</code> में कोई <code>match_phonetic</code> फ़ील्ड नहीं था — इसलिए <em>हर सेटिंग लेखन</em> पर यह फ़्लैग गिर जाता था। बिल्ड 2 ने इसे केवल TypeScript की ओर जोड़ा था। तीनों नए फ़्लैग Rust struct पर भी हैं।","changelog.32c9128fe95e":"कार्यान्वयन संबंधी टिप्पणियाँ:","changelog.c4202016a76a":"<strong>केवल लक्ष्य से नहीं, दोनों ओर से हटाया जाता है।</strong> केवल नाम से हटाने पर <code>foobar</code>, <code>foo-bar</code> को ढूँढ लेता जबकि <code>foo-bar</code>, <code>foobar</code> को नहीं ढूँढ पाता — यह मिलान मोड नहीं, बग जैसा लगता है।","changelog.09e51f90e5b3":"<strong>जब कोई मोड टेक्स्ट बदलता है तो ट्राइग्राम सीड छोड़ दिया जाता है।</strong> <code>foo-bar</code> ट्राइग्राम <code>foo</code>, <code>oo-</code>, <code>o-b</code>, <code>-ba</code>, <code>bar</code> इंडेक्स करता है; needle <code>foobar</code>, <code>oob</code> और <code>oba</code> माँगता है, जो उस पंक्ति में नहीं हैं, इसलिए सीडिंग चुपचाप <em>कुछ भी नहीं</em> लौटाती। executor पूरे स्कैन पर लौट आता है — वही समझौता जो <code>match_path</code> पहले से करता है। फ़्लैग डिफ़ॉल्ट रूप से बंद हैं, इसलिए बिना माँगे किसी को इसकी क़ीमत नहीं चुकानी पड़ती।","changelog.24e406c88eff":"<strong>कोई strip मोड चालू होने पर पूरा-शब्द अनदेखा किया जाता है</strong>, क्योंकि विभाजक हटाने से वे शब्द-सीमाएँ भी हट जाती हैं जिनसे यह परिभाषित होता है।","changelog.c0189eb66ffc":"<strong><code>name:foo-bar</code> सादे शब्द <code>foo-bar</code> जैसा व्यवहार करता है।</strong> ये एक ही क्वेरी के दो लिखित रूप हैं, इसलिए केवल literal-term पथ ही नहीं, <code>name:</code>/<code>child:</code> पथ भी strip मोड का पालन करता है।","changelog.5d357f0cb708":"<strong>विराम-चिह्न की परिभाषा Unicode वाली है, कोई ASCII सूची नहीं</strong>, इसलिए <code>'</code> और <code>-</code> के साथ <code>’</code> और <code>–</code> भी हटाए जाते हैं।","changelog.8b12742c48b5":"anchored मॉडिफ़ायर के लिए <code>^</code> और <code>$</code> को सामान्य key charset में जोड़ने के बजाय ठीक दो कुंजियों के लिए ही अनुमति दी गई है — वही तंत्र जो hyphen वाली कुंजियाँ इस्तेमाल करती हैं, और उसी स्थायी नियम (Standing Rule) #8 के कारण: charset को चौड़ा करने से <code>x^2:3</code> और <code>total$:5</code> literal शब्दों से बदलकर कठोर पार्स त्रुटियाँ बन जाते। <code>--strict-everything</code> के तहत दोनों अस्वीकार किए जाते हैं, क्योंकि voidtools के Everything में कोई anchored सिंटैक्स नहीं है। <code>name$:</code> एक्सटेंशन सहित पूरे नाम पर anchor करता है, इसलिए <code>name$:report</code>, <code>report.txt</code> से मेल नहीं खाता।","changelog.573c5bc71314":"नया मॉडिफ़ायर पंजीकृत करना पार्सर से कहीं आगे तक जाता है, और इनमें से कोई एक भी छूटने पर वह आधा-अधूरा काम करता है: AST variant, <code>exec.rs</code> में चार planner/evaluator जगहें, <code>optimizer::selectivity_rank</code> (anchored मिलान उस substring से संकरा होता है जिसे वह दर्शाता है, इसलिए वह <code>child:</code> से आगे रैंक होता है), <em>दो</em> जगहों पर strict-mode सूची, <code>report.rs</code> का डुप्लिकेट key charset — वह छूटा तो क्वेरी सही चलती है जबकि search bar उसे literal के रूप में रंगता है — और साथ में <code>modifier_name</code>, <code>ModifierDetail</code>, और घोषित <code>MODIFIER_KEYS</code> तालिका, जिसे CLI completions पढ़ते हैं।","changelog.5b298995d56c":"उस आख़िरी वाले में एक उल्लेखनीय कमी थी: <code>every_advertised_modifier_is_known_to_the_parser</code> किसी गायब sigil कुंजी को पकड़ नहीं सकता था, क्योंकि charset से बाहर की कुंजी <code>UnknownModifier</code> के बजाय <em>literal</em> में बदल जाती है, इसलिए टेस्ट दोनों हालात में पास हो जाता है। एक सकारात्मक assertion जोड़ा गया।","changelog.7cd3e842fd15":"<strong>SRC-M20 — regex बिल्डर और लाइव टेस्टर।</strong> search bar में एक नए regex टॉगल के बगल में एक popover: पैटर्न फ़ील्ड, इंजन की अपनी compile त्रुटि, Rust-शैली का त्वरित संदर्भ, और मौजूदा शीर्ष-50 परिणाम नामों में पैटर्न किससे मेल खाता है उसकी लाइव हाइलाइटिंग, &quot;50 में से 3 मेल&quot; गिनती के साथ। पैटर्न commit करने पर क्वेरी <code>regex:&lt;pattern&gt;</code> के रूप में फिर से लिखी जाती है और regex सक्षम करें चालू हो जाता है, ताकि मेनू क्वेरी के व्यवहार से कभी असहमत न हो।","changelog.fc32c438e9b3":"parse-error pill और AST hover पहले से उस क्वेरी को सत्यापित करते हैं जो आप <em>लिख चुके</em> हैं; पैटर्न लिखने में किसी चीज़ से मदद नहीं मिलती थी। समय वहीं जाता है — आप कुछ टाइप करते हैं, चलाते हैं, कुछ नहीं मिलता, और बता नहीं पाते कि पैटर्न गलत है या फ़ाइलें वहाँ हैं ही नहीं। popover दोनों उत्तर एक साथ दिखाता है।","changelog.8f5e99706420":"<strong>टेस्टिंग जानबूझकर Rust में होती है।</strong> स्पष्ट कार्यान्वयन webview के <code>RegExp</code> के विरुद्ध सत्यापन करता, और वह ठीक उन्हीं मामलों में गलत होता जिनसे पैटर्न लिखने वाला व्यक्ति टकराता है: क्वेरी executor <code>regex</code> crate चलाता है, जिसमें न backreferences हैं न lookaround, जो <code>\\d</code> को Unicode-aware मानता है, और <code>(?i)</code> को पीछे लगे फ़्लैग के बजाय इनलाइन लेता है। <code>RegExp</code> पर आधारित बिल्डर <code>(?&lt;=foo)bar</code> को ख़ुशी से स्वीकार कर लेता है और फिर क्वेरी चलने पर विफल होता है। <code>regex_test</code> उसी इंजन से compile करता है, इसलिए &quot;यह यहाँ मेल खाता है&quot; का अर्थ है &quot;यह वहाँ भी मेल खाएगा&quot; — ठीक इसी कारण एक unit टेस्ट है जो assert करता है कि lookaround अस्वीकार किया जाता है।","changelog.6e60e7b42f67":"छोटे निर्णय, जिनमें से हर एक किसी वास्तविक चीज़ की रक्षा करता है: spans <strong>वर्ण</strong> ऑफ़सेट के रूप में लौटाए जाते हैं, क्योंकि UI उन्हें JavaScript string indices से काटता है और बाइट ऑफ़सेट किसी multi-byte नाम को बीच से काट देता; शून्य-चौड़ाई वाले मिलान हटा दिए जाते हैं, क्योंकि <code>a*</code> हर स्थिति पर मेल खाता है और हर स्थिति पर कुछ नहीं हाइलाइट करना सिर्फ़ शोर है; ख़ाली पैटर्न कोई त्रुटि नहीं बताता, बजाय पहले ही कीस्ट्रोक पर एक त्रुटि चमकाने के; और compiled-automaton की आकार सीमा crate के 10 MB डिफ़ॉल्ट के बजाय 256 KB पर तय की गई है। इंजन finite-automaton पर आधारित है, इसलिए कोई शत्रुतापूर्ण पैटर्न exponential backtracking नहीं कर सकता — आकार सीमा ही एकमात्र मायने रखने वाला लीवर है, और वह तय है।","changelog.11270a28687b":"<strong>SRC-M19 — स्पेसबार से त्वरित झलक।</strong> किसी परिणाम पर Space दबाने से एक बड़ा modal पूर्वावलोकन खुलता है; उसके खुले रहते तीर कुंजियाँ परिणाम सेट में आगे-पीछे चलती हैं, और Space या Escape उसे बंद करता है। हेडर &quot;50 में से 7&quot; दिखाता है ताकि आपको पता रहे कि आप सेट में कहाँ हैं।","changelog.d3e1342a48af":"यह पूर्वावलोकन का दूसरा कार्यान्वयन नहीं है — यह वही <code>files_preview</code> कॉल करता है जो docked फलक करता है, इसलिए जो भी प्रारूप एक में रेंडर होता है, वह दूसरे में भी होता है। यह जो जोड़ता है वह है आकार और कीबोर्ड प्रवाह: docked फलक एक पैनल है जिस पर आप नज़र डालते हैं, यह &quot;यह फ़ाइल <em>है</em> क्या?&quot; वाला इशारा है, और मुद्दा यह है कि आपके हाथ कभी कीबोर्ड से न हटें।","changelog.273a049cb91a":"<strong>Space को कंपोनेंट में नहीं, global key binder में संभाला जाता है</strong>, और यही नाज़ुक हिस्सा है: Space एक वर्ण भी है, इसलिए जब भी caret किसी input, textarea, select या contenteditable में हो, उसे अनदेखा किया जाता है। इसे गलत करने का अर्थ है कि खोज बॉक्स स्पेस स्वीकार करना बंद कर दे — जो किसी गायब शॉर्टकट से कहीं बदतर बग है।","changelog.ca26390b3e56":"नेविगेशन उसी क्रम में चलता है जिसमें सूची वास्तव में <em>रेंडर</em> होती है (लेंस क्रम में batches, हर एक के भीतर sort store लागू, सिवाय duplicate-cluster batches के, जहाँ डेमन पहले ही पंक्तियों को क्रम में लगा चुका है और फिर से सॉर्ट करने से clusters बिखर जाते)। किसी और क्रम में चलने से तीर कुंजियाँ इधर-उधर कूदती लगती हैं। कदम दोनों सिरों पर रुक जाते हैं, घूमकर वापस नहीं आते, क्योंकि कुंजी दबाए रखने पर आख़िरी पंक्ति से पहली पर लौट आना गड़बड़ी जैसा लगता है, और यह चयन को बढ़ाने के बजाय बदल देता है।","changelog.f6f10923fe43":"<strong>फ़ीचर विवरण से विचलन, जिसे ढका नहीं बल्कि बताया गया है।</strong> विवरण macOS पर नेटिव QuickLook और बाकी जगह Freally का अपना होस्ट माँगता है। <code>qlmanage -p</code> एक <em>अलग OS विंडो</em> खोलता है जिसे Freally की कीबोर्ड हैंडलिंग नियंत्रित नहीं कर सकती, इसलिए उसे macOS का डिफ़ॉल्ट बनाने से तीर-कुंजी वाला प्रवाह टूट जाता, जो पूरी सुविधा का सार है। इसलिए तीनों प्लेटफ़ॉर्म पर ऐप के भीतर का modal ही सतह है — और इसी से व्यवहार टेस्ट करने योग्य और हर जगह एक जैसा बनता है — और macOS को अतिरिक्त रूप से उन प्रारूपों के लिए एक स्पष्ट &quot;macOS क्विक लुक में खोलें&quot; बटन मिलता है जिन्हें सिस्टम रेंडर कर सकता है पर Freally का पूर्वावलोकन होस्ट नहीं। पथ हर दूसरे फ़ाइल कमांड की तरह उसी <code>KnownPaths</code> गेट से गुज़रता है और <code>Command</code> तर्क के रूप में दिया जाता है, कभी shell के ज़रिए नहीं।","changelog.6fba87d13646":"<strong>SRC-M22 — बुकमार्क और फ़िल्टर साइडबार।</strong> एक वैकल्पिक बायाँ कॉलम (दृश्य → साइडबार, डिफ़ॉल्ट रूप से बंद) जिसमें चार अनुभाग हैं: drag से क्रम बदलने वाले बुकमार्क, सात प्रकार फ़िल्टर, इंडेक्स किए गए वॉल्यूम, और हाल की खोजें। चारों पहले से तीन अलग-अलग ड्रॉपडाउन और एक मेनू के पीछे मौजूद थे, इसलिए किसी खोज का दायरा तय करने के लिए यह जानना पड़ता था कि चार में से किस जगह देखना है; यह उन्हें क्लिक करने योग्य नोड्स के एक कॉलम में रख देता है।","changelog.2af93b3b0eaf":"<strong>&quot;हाल की खोजें&quot; को गढ़ना पड़ा, क्योंकि यहाँ खोज लाइव है।</strong> <code>run()</code> हर कीस्ट्रोक पर चलता है, इसलिए हर रन को ज्यों का त्यों दर्ज करने से <code>r</code>, <code>re</code>, <code>rep</code>, <code>repo</code>, <code>repor</code>, <code>report</code> बनते और वह एक प्रविष्टि दब जाती जो किसी को चाहिए। दो नियम इसे ठीक करते हैं, बिना किसी स्पष्ट commit इशारे के जो UI में है ही नहीं: नई क्वेरी उस हर मौजूदा प्रविष्टि को हटा देती है जो उसका prefix है (वहाँ तक पहुँचने के रास्ते के कीस्ट्रोक), और जो क्वेरी स्वयं सबसे नई प्रविष्टि का prefix है उसे दर्ज नहीं किया जाता (वह backspace है)। &quot;report&quot; और फिर &quot;invoice&quot; टाइप करने पर ठीक <code>[&quot;invoice&quot;, &quot;report&quot;]</code> बचता है।","changelog.97fe3ffe9b63":"यह सूची <strong>गोपनीयता मोड और खोज इतिहास टॉगल</strong> का पालन करती है — दोनों का अर्थ पहले से ही है &quot;मैंने जो खोजा उसका रिकॉर्ड न रखें&quot;, और साइडबार का अनुभाग ठीक ऐसा ही एक रिकॉर्ड है, इसलिए वह चुपचाप अपनी अलग प्रति नहीं रखता।","changelog.736397e92eea":"drag क्रम बुकमार्क रिकॉर्ड पर नहीं, बल्कि सेटिंग में बुकमार्क id की एक सूची के रूप में संग्रहीत होता है, इसलिए क्रम बदलने के लिए बुकमार्क IPC से होकर किसी नए लेखन पथ की ज़रूरत नहीं पड़ती। हटाए गए बुकमार्क की id खाली जगह छोड़ने के बजाय अनदेखी की जाती हैं, और पिछली drag के बाद जोड़ा गया बुकमार्क गिराया नहीं जाता बल्कि अंत में जोड़ दिया जाता है।","changelog.bb58e9012e27":"वॉल्यूम नोड <code>volume:&quot;&lt;label&gt;&quot;</code> <strong>उद्धरण चिह्नों के साथ</strong> देते हैं, क्योंकि लेबल में अक्सर स्पेस होते हैं (<code>Orange WD 4TB</code>) और बिना उद्धरण चिह्नों के वह दो शब्दों के रूप में पार्स होता।","changelog.3ce317440cef":"साइडबार <code>.result-area</code> के भीतर रेंडर होता है, परिणाम सूची और पूर्वावलोकन फलक के साथ एक ही flex पंक्ति साझा करते हुए, इसलिए इसे टॉगल करने से ऊपर और नीचे का मेनू / खोज / स्थिति वाला ढाँचा प्रभावित नहीं होता।","changelog.d5f690fcafa4":"<strong>इसे जोड़ते समय पकड़ी गई एक डुप्लिकेट चीज़</strong>, दर्ज करने लायक क्योंकि वह पहले से गलत थी: SRC-M19 में जोड़ा गया त्वरित झलक नेविगेशन सीधे <code>resultsStore.batches</code> पर चलता था। batches <em>आगमन</em> क्रम में संग्रहीत होते हैं और उनमें उन लेंसों के hits होते हैं जिन्हें उपयोगकर्ता ने बंद कर रखा है, और वे पंक्तियाँ भी जिन्हें किसी परिष्करण ने फ़िल्टर कर दिया है — जबकि सूची एक निश्चित लेंस क्रम में <code>viewForLens</code> से रेंडर होती है। <code>resultsStore.visibleHits</code> पहले से मौजूद था और यह सही करता था। नेविगेशन helper अब उसी <code>viewForLens</code> पर बना है, इसलिए तीर कुंजियाँ उस पर चलती हैं जो स्क्रीन पर है, न कि उस पर जो डेमन ने संयोग से पहले भेजा।","changelog.357a743ccb54":"<strong>SRC-M21 — अनुमति स्थिति रिपोर्ट + macOS पूर्ण डिस्क पहुँच विज़ार्ड।</strong> उपकरण → अनुमति स्थिति, और साथ में एक स्थिति-बार बैज जो केवल तब दिखता है जब कुछ कहने को हो, और एक विस्तृत दृश्य खोलता है कि स्कैनर कौन-से फ़ोल्डर नहीं पढ़ सका, किस वॉल्यूम पर, किस कारण से — उस प्लेटफ़ॉर्म के लिए निर्देशित सुधार के साथ जिस पर <em>इंडेक्स</em> चलता है।","changelog.b5aa6e1796c3":"<strong>जिस बैज को बढ़ाने की बात फ़ीचर विवरण करता है, वह मौजूद ही नहीं था।</strong> कहीं भी &quot;n पथ छोड़े गए (अनुमति)&quot; जैसा कुछ नहीं था: जिस डायरेक्टरी को स्कैनर नहीं खोल पाता, उससे बस एक <code>warn!</code> पंक्ति बनती थी और कुछ नहीं, इसलिए अपठनीय subtree बिल्कुल ख़ाली subtree जैसा दिखता था। पहले ledger (<code>crates/freally-indexd/src/permissions.rs</code>) बनाना पड़ा। इस stable-gate दौर में यह चौथी बार है कि किसी अनिवार्य (Must-Have) सुविधा का बताया गया शुरुआती बिंदु मौजूद ही नहीं निकला।","changelog.62ca3f92cd3e":"ledger क्या दर्ज करता है और क्यों:","changelog.d8706bc2b337":"<strong>रूट, फ़ाइलें नहीं।</strong> <code>walkdir</code> जिस डायरेक्टरी को नहीं खोल पाता उसके लिए एक त्रुटि बताता है और उसके भीतर नहीं उतरता, इसलिए ledger में स्वाभाविक रूप से हर अपठनीय subtree का रूट पहुँचता है। उपयोगी उत्तर भी यही है: &quot;इस फ़ोल्डर को पहुँच दें&quot;, न कि दस हज़ार फ़ाइल नाम।","changelog.0917b96f248e":"<strong>गायब हो चुका पथ कोई दोष नहीं है।</strong> <code>NotFound</code> पूरी तरह छोड़ दिया जाता है — लाइव फ़ाइल सिस्टम पर स्कैन के बीच हटाई गई फ़ाइल सामान्य बात है, और उसे गिनने से व्यस्त मशीन की हर रिपोर्ट चिंताजनक दिखती।","changelog.4df4fedc30d4":"<strong>2,000 प्रविष्टियों पर सीमित, और अतिरिक्त की गिनती के साथ।</strong> यह सूची मेमोरी में रखी जाती है, serialize होती है और IPC पर भेजी जाती है; कुछ हज़ार के बाद यह ऐसी रिपोर्ट नहीं रह जाती जिसे कोई व्यक्ति पढ़े। UI सूची के पूरी होने का आभास देने के बजाय &quot;और 12,043 अन्य&quot; कहता है।","changelog.45a8fa9b22b3":"<strong>पुनः स्कैन पहले उस रूट की प्रविष्टियाँ साफ़ करता है</strong>, ताकि जिस अनुमति को उपयोगकर्ता ने वास्तव में ठीक कर दिया है उसकी रिपोर्ट होना बंद हो जाए। इसके बिना रिपोर्ट केवल बढ़ती ही जाती।","changelog.8c83c3941420":"<code>config/permissions.json</code> में <strong>स्थायी रूप से सहेजा जाता है</strong>, क्योंकि &quot;जिन फ़ाइलों को मैं इंडेक्स नहीं कर सका&quot; का कोई मूल्य तभी है जब वह रीस्टार्ट के बाद भी बना रहे।","changelog.2272ff2f607f":"मार्गदर्शन ब्राउज़र के user-agent से नहीं, <strong>डेमन की ओर</strong> तय होता है: जब भी कोई क्लाइंट किसी दूरस्थ endpoint की ओर इंगित हो, इंडेक्स रिपोर्ट रेंडर करने वाली विंडो से अलग मशीन पर हो सकता है, और सुधार उसी मशीन का है जो फ़ोल्डर नहीं पढ़ सकी।","changelog.7bd109d95768":"macOS पर रिपोर्ट एक TCC-संरक्षित डायरेक्टरी पढ़कर <strong>पूर्ण डिस्क पहुँच का पता लगाती है</strong>: सफलता का अर्थ है अनुमति मिली हुई है, <code>PermissionDenied</code> का अर्थ है नहीं। कोई भी दूसरी त्रुटि &quot;अनुमति नहीं मिली&quot; के बजाय <em>अनिर्धारित</em> के रूप में बताई जाती है — किसी से ऐसी सेटिंग ठीक करने को कहना जो पहले से सही है, कुछ न कहने से बदतर है। अनुमति न मिली हो तो एक बटन सीधे पूर्ण डिस्क पहुँच फलक खोलता है।","changelog.bea94a4860c8":"Smoke टेस्ट: <code>tests/smoke/build_03_permissions.rs</code> साबित करता है कि स्कैनर वास्तव में ledger को संभाल रहा है — साफ़ ट्री उसे ख़ाली छोड़ता है, और एक असली स्कैन उस रूट के लिए पिछले दौर की प्रविष्टियाँ हटा देता है जबकि बाकी रूट को नहीं छूता। यह जानबूझकर कोई अस्वीकृत डायरेक्टरी बनाने की कोशिश नहीं करता: वह पोर्टेबल नहीं है (<code>chmod 000</code> root के लिए no-op है, और Windows को ACL की चीर-फाड़ चाहिए होती), इसलिए अस्वीकृति वाले पथों का unit-टेस्ट OS से <code>io::Error</code> माँगने के बजाय उसे सीधे बनाकर किया जाता है।","changelog.a0e48a175453":"<strong>SRC-M18 — पूर्वावलोकन फलक में इनलाइन ऑडियो/वीडियो प्लेबैक।</strong> ट्रांसपोर्ट (चलाएँ/रोकें, आगे-पीछे करें, दोहराएँ), एक वॉल्यूम स्लाइडर, एक रेंडर किया गया वेवफ़ॉर्म जिस पर क्लिक करके scrub किया जा सकता है, और ऊपर दिखाए गए codec / sample-rate / channel / LUFS बैज। <code>lufs:&lt;-14</code> वाले परिणाम को सुनने के लिए अब Freally छोड़ना नहीं पड़ता — ऑडियो लेंस इसी workflow में आपको बनाए रखने के लिए है।","changelog.5677c3279dd5":"<strong>वेवफ़ॉर्म के लिए कोई अतिरिक्त डिकोड नहीं लगता।</strong> एक <code>PeakCollector</code>, <code>freally-audio</code> के मौजूदा विश्लेषण पास के साथ ही चलता है: वही interleaved फ़्रेम जो loudness और silence accumulators को मिलते हैं, उसे भी मिलते हैं, इसलिए हर तीर कुंजी पर फिर से खुलने वाले फलक में ट्रैक खोलने पर, सिर्फ़ उसकी तस्वीर बनाने के लिए फ़ाइल दूसरी बार डिकोड नहीं होती। buckets प्रति-सेकंड के बजाय निश्चित संख्या में हैं क्योंकि canvas की चौड़ाई निश्चित है — प्रति-सेकंड envelope को फ़िट करने के लिए resample करने से ठीक वही peaks खो जाते हैं जो आकृति को पढ़ने योग्य बनाते हैं — और वे सभी channels के पार peak लेते हैं, क्योंकि वेवफ़ॉर्म उस क्षण की सबसे तेज़ आवाज़ दिखाता है, न कि उसके बारे में बाएँ channel की राय।","changelog.cdfeb4ff1549":"<strong>बाइट asset protocol से नहीं, IPC से जाते हैं — जानबूझकर।</strong> media element को डेटा देने का पारंपरिक तरीका Tauri का asset protocol है, और उसे अस्वीकार किया गया: उसे सक्षम करने का अर्थ है एक ऐसा फ़ाइल सिस्टम scope घोषित करना जिसे <em>webview</em> सीधे पढ़ सके, और &quot;उपयोगकर्ता का मीडिया जहाँ भी हो&quot; को कवर करने लायक चौड़ा कोई भी scope उस <code>KnownPaths</code> गेट को निष्प्रभावी करने लायक भी चौड़ा है जिसे बिल्ड 1 ने मज़बूत किया था — यह गुण कि कोई compromised frontend dependency ऐसी फ़ाइल तक नहीं पहुँच सकती जिसे डेमन ने कभी लौटाया ही नहीं। बाइट को एक कमांड से गुज़ारने पर हर read उसी जाँच के पीछे रहता है जिसके पीछे हर दूसरा फ़ाइल ऑपरेशन है।","changelog.92840d3c1b10":"इसकी क़ीमत यह है कि प्लेबैक stream नहीं, buffer होता है, इसलिए 192 MB की ऊपरी सीमा है — जो चुपचाप विफल होने के बजाय UI में बताई जाती है, और UI उससे बड़ी फ़ाइल को सिस्टम प्लेयर में खोलने का विकल्प देता है। बाइट base64 data URL के बजाय कच्चे <code>tauri::ipc::Response</code> के रूप में लौटाए जाते हैं; data URL payload को एक तिहाई बढ़ा देता और दोनों ओर पूरा re-encode करवाता।","changelog.712f85c29448":"दो छोटी बातें, जिनमें से हर एक असली बग होती: चयन बदलने पर object URL रद्द कर दिया जाता है (इसके बिना हर तीर कुंजी पूरी डिकोड की गई फ़ाइल leak करती), और non-finite integrated loudness <code>-inf LUFS</code> के बजाय <em>कोई बैज नहीं</em> के रूप में रेंडर होती है — एक gating block से छोटी क्लिप का कोई सार्थक integrated मान नहीं होता।","changelog.d91a498a29f7":"चलाया जा सकता है या नहीं, यह पूर्वावलोकन payload से नहीं, hit के एक्सटेंशन से तय होता है: मीडिया फ़ाइल का payload <code>unsupported</code> होता है, और ठीक यही वह मामला है जिसे चलाना उपयोगी है।","changelog.7c9e53ab0e65":"बिल्ड 3 समापन — समीक्षा दौरों ने क्या बदला","changelog.4519ec9bebde":"<code>/simplify</code> ने पूरे बिल्ड diff पर चार समीक्षक चलाए। उनमें से तीन ने स्वतंत्र रूप से एक ही बात पकड़ी, और दो निष्कर्ष शैली के नहीं, बल्कि असली दोष थे:","changelog.8ce21698a623":"<strong>साइडबार बुकमार्क के सहेजे गए फ़िल्टर गिरा देता था।</strong> <code>applyBookmark</code> ने ड्रॉपडाउन का load प्रवाह दोबारा लिखा था और <code>typeFilterStore.setFromIds(...)</code> छोड़ दिया था, इसलिए साइडबार से बुकमार्क खोलने पर, वही बुकमार्क ड्रॉपडाउन से खोलने की तुलना में अलग लेंस prefix बनता था। अब दोनों एक ही <code>bookmarksStore.apply</code> कॉल करते हैं।","changelog.eac5108065c7":"<strong><code>visibleHits</code> दो बार मौजूद था, अलग-अलग उत्तरों के साथ।</strong> त्वरित झलक वाली प्रति सॉर्ट करती थी; <code>resultsStore.visibleHits</code> — जिसे निर्यात, सभी चुनें और स्थिति-बार की गिनती पढ़ते हैं — नहीं करता था। कॉलम सॉर्ट सक्रिय होते ही दोनों असहमत हो जाते थे। सॉर्ट store के getter में चला गया और प्रति हटा दी गई, जिससे उस getter की &quot;उपयोगकर्ता जो देख रहा है उसका एकमात्र उत्तर&quot; वाली टिप्पणी भी आकांक्षा के बजाय सच हो जाती है।","changelog.c773525b8054":"<strong>हाथ से समन्वित दो strict-mode सूचियाँ पहले ही अलग हो चुकी थीं।</strong> पार्सर की केवल-Freally मॉडिफ़ायर सूची में <code>volume:</code> था और <code>report.rs</code> की प्रति में नहीं, इसलिए <code>volume:</code> वाली strict-everything क्वेरी को पार्सर अस्वीकार करता था जबकि search bar जिस रिपोर्ट से रेंडर होता है वह उसे ठीक बताती थी। अब एक ही <code>is_freally_only_modifier</code> है।","changelog.67e8b82d717f":"प्रदर्शन संबंधी उल्लेखनीय निष्कर्ष, सभी उन पथों पर जो इस बिल्ड ने जोड़े:","changelog.193b3787c53e":"अनुमति बैज का effect हर index-state poll पर फिर से चलता था — <code>indexStateStore</code> पूरा state object फिर से असाइन करता है, इसलिए &quot;<code>phase</code> पढ़ें&quot; अमान्य हो जाता है, चाहे <code>phase</code> बदला हो या नहीं। यह हमेशा के लिए हर पाँच सेकंड में एक IPC round-trip कर रहा था, और हर बार mutex के तहत पूरे ledger का clone बनाता था। अब पिछली poll की गई phase पर guard लगाया गया है।","changelog.25ff7799a027":"प्राकृतिक-क्रम comparator हर <em>वर्ण</em> पर एक regex चलाता था और हर chunk पर नया collator बनाता था। अब एक code-point जाँच और एक साझा <code>Intl.Collator</code>।","changelog.282cbf6f5b04":"पथ से सॉर्ट करने पर हर तुलना में दोनों <code>PathBuf</code> का रूपांतरण होता था — O(n log n) WTF-8 स्कैन। अब decorate-sort-undecorate, प्रति पंक्ति एक रूपांतरण।","changelog.fa6395a85e8e":"मीडिया प्लेयर बाइट और वेवफ़ॉर्म को एक के बाद एक लोड करता था, जबकि वे स्वतंत्र हैं; और सभी ~800 वेवफ़ॉर्म bars को प्लेबैक प्रगति पर निर्भर बना दिया था, इसलिए हर <code>timeupdate</code> 800 expressions का फिर से मूल्यांकन करता था। अब <code>Promise.all</code>-शैली का overlap और एक अकेला <code>--progress</code> overlay।","changelog.1a1162f4da54":"साथ ही: <code>AnalysisOpts::peak_buckets</code> private है, क्योंकि <code>pub</code> फ़ील्ड होने पर कोई caller इसे <code>analyze_with_opts</code> पर सेट कर सकता था, जिसके पास peaks लौटाने की कोई जगह नहीं है और जो उन्हें चुपचाप फेंक देता; और <code>media.rs</code> अपनी प्रति के बजाय साझा <code>files::verify_readable</code> कॉल करता है, इसलिए frontend-asserted reads का provenance स्तर ठीक एक ही जगह तय होता है।","changelog.c70a3b9f1590":"बिल्ड 3 समापन — <code>/security-review</code> ने क्या बदला","changelog.ccce544a9b0c":"दो HIGH (उच्च गंभीरता) निष्कर्ष, दोनों इसी बिल्ड से आए, दोनों ठीक किए गए।","changelog.de5618b9e06c":"<strong><code>media_bytes</code> उस स्तर पर gated था जिसे frontend ख़ुद के लिए बना सकता है।</strong> यह किसी नामित फ़ाइल की <em>पूरी</em> सामग्री webview को लौटाता है, और यह <code>Provenance::FrontendAsserted</code> इस्तेमाल कर रहा था — वह स्तर जो <code>files_whitelist_user_chosen</code> JS परत द्वारा माँगी गई किसी भी स्ट्रिंग को दे देता है। कोई compromised frontend dependency <code>~/.ssh/id_ed25519</code> को whitelist करके फिर उसे पढ़ सकती थी, बिना किसी डायलॉग और बिना डेमन के शामिल हुए। फ़ाइल सामग्री लौटाने वाले बाकी दो कमांड, <code>content_document</code> और <code>copy_file_contents</code>, पहले से <code>QueryHit</code> माँगते थे; अब ये दोनों भी माँगते हैं। वैध caller परिणाम पंक्तियों से चलता है, जिनके पास वह स्तर पहले से होता है, इसलिए उपयोगकर्ता के सामने कुछ नहीं बदलता।","changelog.ec04c33c4cd8":"<strong>पोर्टेबल-मोड socket सीधे साझा temp डायरेक्टरी में था।</strong> <code>/tmp</code> का mode 1777 है और नाम एक अनुमान लगाने योग्य पथ का FNV hash था, इसलिए कोई भी स्थानीय खाता उसे पहले bind कर सकता था। transport अपने स्वामित्व वाले listener के <em>peer</em> को प्रमाणित करता है; बाहर कनेक्ट होने वाला क्लाइंट कुछ भी जाँचता नहीं था, इसलिए उस पथ पर कब्ज़ा करना डेमन का पूरा प्रतिरूपण था — और <code>register_hit_paths</code>, <code>query:batch</code> में आने वाली किसी भी चीज़ को <code>Provenance::QueryHit</code> में बदल देता है, जो delete, rename और हर दूसरे विनाशकारी कमांड का गेट है। तीन बदलाव:","changelog.7cf7132d7226":"socket एक प्रति-उपयोगकर्ता डायरेक्टरी में चला गया — जहाँ मौजूद हो वहाँ <code>$XDG_RUNTIME_DIR</code>, नहीं तो uid-चिह्नित एक उप-डायरेक्टरी जिसे यह प्रोसेस बनाता है और chmod 0700 करता है, और अगर वह किसी और के स्वामित्व में निकले तो उसे सीधे अस्वीकार कर देता है।","changelog.aadc9d78386e":"<code>transport::unix::connect</code> अब ऐसा socket अस्वीकार करता है जिसका स्वामी यह उपयोगकर्ता न हो, या जिसका mode दूसरों के लिए सुलभ हो। यह <code>symlink_metadata</code> इस्तेमाल करता है, इसलिए हमारे स्वामित्व वाले socket की ओर इशारा करने वाला symlink इस जाँच को पूरा नहीं करता। यह listener की peer-uid जाँच का वह समकक्ष है जो अब तक गायब था।","changelog.0ed10670ac32":"socket की parent डायरेक्टरी को कस न पाने पर <code>listen</code> अब पूरी तरह विफल नहीं होता। <code>chmod 0700 /tmp</code> हर non-root उपयोगकर्ता के लिए <code>EPERM</code> लौटाता है, इसलिए <strong>पोर्टेबल मोड Linux पर अपना डेमन शुरू ही नहीं कर पाता था</strong> — सुरक्षा मज़बूत करने वाला कदम उसी चीज़ को गिरा रहा था जिसकी उसे रक्षा करनी थी। अब यह लॉग करता है और इसके बजाय socket के अपने 0600 पर भरोसा करता है।","changelog.d3ce18a2d574":"<span class=\"release__meta\"><span class=\"release__ver\">v0.22.0</span><time class=\"release__date\" datetime=\"2026-08-02\">2026-08-02</time></span><span class=\"release__title\">बिल्ड 2 · अनिवार्य (Must-Have) स्थिर गेट, 3 में से भाग 2</span>","changelog.9bd054757229":"तीन अनिवार्य (Must-Have) बिल्ड में से दूसरा: SRC-M09 … SRC-M16। cross-platform, जब तक कोई प्रति-OS टिप्पणी कुछ और न कहे। सुविधाओं का पूरा दस्तावेज़ीकरण <code>docs/documentation.html</code> में है।","changelog.d9bb66b60223":"<strong>SRC-M09 — मशीन-पठनीय CLI आउटपुट।</strong> <code>freally search</code> में <code>--json</code>, <code>--ndjson</code> (प्रति hit एक object, streaming), <code>--csv</code>, कॉलम चुनने के लिए <code>--fields</code>, <code>xargs -0</code> के लिए <code>-0</code>, <code>--limit</code> / <code>--offset</code>, और सार्थक exit codes (0 hits मिले, 1 कोई नहीं, 2 त्रुटि) जुड़े।","changelog.758c601a0121":"<strong>SRC-M10 — shell completions।</strong> <code>freally completions &lt;shell&gt;</code> bash, zsh, fish और PowerShell के लिए completions छापता है, जिनमें subcommands, flags, और — गतिशील रूप से — मॉडिफ़ायर कीवर्ड और सहेजी गई खोजों के नाम शामिल हैं।","changelog.88b57e0c662b":"<strong>SRC-M11 — टाइपो-सहिष्णु &quot;क्या आपका मतलब था&quot;।</strong> जब फ़ाइल नाम लेंस कुछ नहीं लौटाता, तो समानता कैंडिडेट को सीमित Damerau-Levenshtein दूरी से फिर से रैंक किया जाता है और सबसे निकट वाले को एक-क्लिक सुधार के रूप में पेश किया जाता है।","changelog.651b223b2f18":"<strong>SRC-M12 — CJK ध्वन्यात्मक मिलान।</strong> <code>wenjian</code> या <code>wj</code> टाइप करने पर <code>文件</code> मिलता है; romaji, kana से मेल खाता है; lead jamo, Hangul से। उच्चारण (readings) सहायक नाम कुंजियों के रूप में इंडेक्स होते हैं और <strong>खोज → CJK ध्वन्यात्मकता मिलाएँ</strong> से वैकल्पिक रूप से चालू किए जाते हैं। हर रूपांतरण एक table lookup या अंकगणित है — Hangul का विघटन Unicode syllable block पर शुद्ध अंकगणित है, kana एक in-tree तालिका है, और Han उच्चारण <code>pinyin</code> crate से आते हैं।","changelog.1bd2b09ee538":"<strong>लाइव परिवर्तन जर्नलिंग।</strong> इंडेक्स अब केवल स्कैन चलने पर नहीं, बल्कि फ़ाइलें बदलते ही अपडेट होता है। हर OS subscriber पहले से <code>subscribe()</code> लागू करता था और <code>freally-index</code> पहले से सीमित <code>EventQueue</code> शिप करता था, पर किसी ने उन्हें कभी जोड़ा नहीं था: <code>Index::apply</code> और <code>EventQueue</code> केवल benches और एक unit टेस्ट से पहुँच में थे। <code>freally-indexd::watcher</code> वही pipeline है — एक producer थ्रेड जो OS की परिवर्तन stream को queue में खाली करता है, और एक consumer जो batches लागू और commit करता है। Windows पर USN journal प्रति-वॉल्यूम है, इसलिए एक ड्राइव के फ़ोल्डर एक ही watcher में सिमट जाते हैं जो पथ prefix से फ़िल्टर करता है; FSEvents और inotify सीधे एक subtree पर नज़र रखते हैं।","changelog.eaa3eb8d8d9f":"<em>producer रुकने (block) के बजाय events क्यों गिराता है:</em> रुकने से events बचते नहीं — हमारे इंतज़ार करते समय OS की ओर का buffer भरता रहता है, और overflow होने पर वे बिना किसी रिकॉर्ड के चले जाते हैं। अपनी ही सीमा पर गिराने से वही events खोते हैं, पर एक गिना हुआ, timestamp वाला ledger बचता है, और नीचे वाला सलाहकार उसी पर रिपोर्ट करता है।","changelog.71e6a83277bd":"<strong>SRC-M13 — सूचकांक स्वास्थ्य पैनल + पुनर्निर्माण सलाहकार।</strong> <strong>उपकरण → अनुक्रमणिका अनुरक्षण → सूचकांक स्वास्थ्य</strong> हर निगरानी वाले स्थान के लिए बताता है: event से क्वेरी में दिखने तक का विलंब, छूटे events का ledger, आख़िरी देखा गया परिवर्तन, और queue की गहराई, और साथ में नियम-आधारित सलाह, जहाँ पुनर्निर्माण ही सुधार हो वहाँ एक-क्लिक पुनर्निर्माण के साथ। सामग्री-निष्कर्षण का backlog शून्य के बजाय <em>ट्रैक नहीं किया गया</em> के रूप में बताया जाता है — डेमन कोई eager-extraction worker नहीं चलाता, और &quot;0&quot; को &quot;निष्क्रिय&quot; समझा जाता।","changelog.946db255ad4d":"<strong>SRC-M14 — हटाने योग्य वॉल्यूम के ऑफ़लाइन कैटलॉग।</strong> ड्राइव अनप्लग करने पर भी उसकी फ़ाइलें खोजने योग्य रहती हैं, और अलग किए गए डिवाइस से आए परिणामों पर <em>ऑफ़लाइन — Orange WD 4TB</em> बैज लगा होता है। <code>volume:</code> उस नाम से फ़िल्टर करता है जिससे आप ड्राइव को जानते हैं, या उसकी volume id से। किसी दूसरे अक्षर या mount point पर लौटने वाली ड्राइव को उसी कैटलॉग के रूप में पहचाना जाता है।","changelog.f637da61fd70":"<em>अंदरूनी तौर पर:</em> <code>volume</code> कॉलम, उसका SQLite इंडेक्स और Tantivy फ़ील्ड, तीनों चरण 4 में शिप हो चुके थे, पर ingest पथ पर पंक्ति बनाने वाला एकमात्र constructor एक ख़ाली स्ट्रिंग hard-code करता था, इसलिए पूरा कॉलम निष्क्रिय था। पंक्तियों पर अब असली mount table पर longest-prefix मिलान से मुहर लगती है, और केवल यही mount point को किसी साधारण डायरेक्टरी से अलग पहचान सकता है।","changelog.4ec8be883d22":"<strong>SRC-M15 — थोक में नाम बदलना।</strong> कितने भी परिणाम चुनें, <code>F2</code> दबाएँ, और बदलाव एक बार बताएँ: capture groups के साथ literal या regex खोज/बदलें, <code>{n}</code> / <code>{n:03}</code> गणक, केस रूपांतरण, और stem या पूरा नाम बदलने का विकल्प। एक लाइव तालिका हर पहले/बाद की जोड़ी दिखाती है और उन पंक्तियों को चिह्नित करती है जो एक-दूसरे से टकराएँगी, किसी मौजूदा फ़ाइल को अधिलेखित करेंगी, या ऐसा नाम बनाएँगी जिसे सिस्टम स्वीकार नहीं करेगा। पूरा batch या तो पूरा होता है या बिल्कुल नहीं, और बीच में विफलता होने पर सब वापस (rollback) हो जाता है।","changelog.46851cce7744":"<em>टिप्पणी:</em> roadmap में एकल-फ़ाइल नाम बदलना पहले से शिप होता दर्ज था। ऐसा नहीं था — केवल <em>बुकमार्क</em> का नाम बदलना मौजूद था — इसलिए यह बिल्ड नाम बदलने का मूल primitive भी जोड़ता है और उसके ऊपर थोक वाली परत भी।","changelog.3fc85f03e023":"<strong>SRC-M16 — फ़ाइल ऑपरेशनों के लिए पूर्ववत/फिर से करें।</strong> <code>Ctrl+Z</code> किसी नाम बदलने या थोक नाम बदलने को उलट देता है, <code>Ctrl+Shift+Z</code> उसे फिर से चलाता है, और डेमन जर्नल को स्थायी रूप से सहेजता है ताकि आख़िरी 50 ऑपरेशन रीस्टार्ट के बाद भी बने रहें। batch उल्टे क्रम में खुलता है, इसलिए श्रृंखलाबद्ध नाम बदलना (<code>a→b</code>, <code>b→c</code>) ख़ुद से टकराए बिना पूर्ववत होता है।","changelog.51f9c128a973":"<em>प्रलेखित अपवाद:</em> हटाना इतिहास में दर्ज होता है पर उसका पूर्ववत नहीं है। Freally OS के ट्रैश में हटाता है, और एकमात्र cross-platform restore API (<code>trash::os_limited</code>) Windows और freedesktop Linux के लिए लागू है, पर <strong>macOS के लिए नहीं</strong>। दबाने के बाद विफल होने वाला बटन देने के बजाय, हटाने के साथ एक कारण जुड़ा होता है जो बताता है कि पुनर्स्थापित करना ऑपरेटिंग सिस्टम का काम है। फ़ोल्डर में कॉपी करें और फ़ोल्डर में ले जाएँ जर्नल में दर्ज नहीं होते, क्योंकि वे अभी वास्तव में कॉपी या स्थानांतरण नहीं करते।","changelog.c75a49fc28b8":"<strong>write-side कमांडों का सुरक्षा ढाँचा।</strong> नाम बदलने का एक गंतव्य होता है, और स्रोत के विपरीत वह कभी किसी परिणाम सेट में नहीं था — इसलिए बिल्ड 1 के इस नियम के तहत कि write-side IPC caller द्वारा चुने गए पथ स्वीकार नहीं करेगा, frontend कभी गंतव्य नहीं भेजता। वह चुने गए पथ और <em>नियम</em> भेजता है; backend हर नाम ख़ुद निकालता है और पूर्वावलोकन पर भरोसा करने के बजाय लागू करते समय उन्हें फिर से निकालता है, इसलिए छेड़छाड़ की गई पूर्वावलोकन तालिका कुछ नहीं बदलती। निकाले गए नाम अस्वीकार कर दिए जाते हैं यदि उनमें पथ विभाजक हो, वे <code>.</code> या <code>..</code> हों, उनमें कोई ऐसा वर्ण हो जिसे कोई प्लेटफ़ॉर्म स्वीकार नहीं करता, Windows उन्हें चुपचाप बदल दे (अंत में बिंदु या स्पेस, जिससे लागू हुआ नाम स्वीकृत नाम से अलग हो जाता), या वे किसी आरक्षित डिवाइस नाम से मेल खाएँ। इसके बाद गंतव्य स्रोत की अपनी parent डायरेक्टरी से फिर से बनाया जाता है।","changelog.b2289135440f":"<strong>टेस्ट।</strong> <code>tests/smoke/build_02_index_health.rs</code>, <code>build_02_volume_catalogs.rs</code> और <code>build_02_rename_undo.rs</code> नई सतहों को OS-निरपेक्ष ढंग से गेट करते हैं; unit टेस्ट नाम बदलने के इंजन, ऑपरेशन जर्नल, सलाहकार नियमों, event coalescing, विलंब के हिसाब, वॉल्यूम मैप और कैटलॉग रजिस्ट्री को कवर करते हैं। <code>apps/freally-ui/tests/unit/build_02.test.ts</code> frontend की wiring को कवर करता है।","changelog.b1d319c1818b":"<strong>i18n।</strong> सभी 18 लोकेल में 68 नई कुंजियाँ (कुल 782); <code>xtask i18n-lint</code> हरा।","changelog.7d87f19cc769":"<code>volume:</code> केवल-Freally मॉडिफ़ायर है, इसलिए strict-Everything मोड में इसे <code>similar:</code> और ऑडियो परिवार के साथ अस्वीकार किया जाता है।","changelog.7df7bfeaffe7":"<code>freally-journal</code> तीनों subscribers पर एक OS-निरपेक्ष <code>JournalPosition</code> (<code>generation</code> + <code>offset</code>) उपलब्ध कराता है, ताकि डेमन प्रति-OS cursor प्रकार जाने बिना wrap हुई या फिर से बनाई गई change stream का पता लगा सके।","changelog.f787e991d5ac":"ज्ञात कमियाँ","changelog.cea8b98efa00":"<code>auto_remove_offline</code> अब भी no-op है। इसे शब्दशः लागू करने का अर्थ है किसी ऑफ़लाइन डिवाइस की पंक्तियों को इंडेक्स से मिटा देना; यह विनाशकारी है, SRC-M14 के दायरे से बाहर है, और इसका <code>true</code> डिफ़ॉल्ट हर मौजूदा इंस्टॉल पर चुपचाप लागू हो जाता। यह सुविधा जो चाहती है वह है बनाए रखना, और डेमन पहले से यही करता था।","changelog.8d7633d7bfb2":"चारों मौजूदा match-mode टॉगल (केस, पूरा शब्द, पथ, डायाक्रिटिक्स) अब भी केवल UI तक सीमित हैं — डेमन <code>ExecOpts::default()</code> बनाता है और केवल SRC-M12 का ध्वन्यात्मक फ़्लैग वायर के पार जाता है। यह बिल्ड 2 से पहले का है; इन्हें जोड़ने से मौजूदा क्वेरी के परिणाम बदल जाते।","changelog.61109f3e67da":"<span class=\"release__meta\"><span class=\"release__ver\">v0.21.0</span><time class=\"release__date\" datetime=\"2026-07-31\">2026-07-31</time></span><span class=\"release__title\">बिल्ड 1 · अनिवार्य (Must-Have) स्थिर गेट, 3 में से भाग 1</span>","changelog.d178abfc569c":"तीन अनिवार्य (Must-Have) बिल्ड में से पहला: SRC-M01 … SRC-M08। cross-platform, जब तक कोई प्रति-OS टिप्पणी कुछ और न कहे। सुविधाओं का पूरा दस्तावेज़ीकरण <code>docs/documentation.html</code> में है।","changelog.8290eb7e3829":"<strong>SRC-M01 — संदर्भ सहित मिलान दिखाने वाला सामग्री व्यूअर।</strong> हर उस फ़ाइल के लिए पूरे दस्तावेज़ का दृश्य जिसे extractor pipeline पढ़ सकती है: हर मिलान हाइलाइट, क्रमांकित पंक्तियाँ, मिलान-संख्या बैज, मिलानों के बीच <code>F3</code> / <code>Shift+F3</code>, और खुलते ही पहले मिलान पर पहुँचना। नए परिणाम right-click मेनू से पहुँचा जाता है। हाइलाइट किए गए शब्द क्वेरी के literal और उद्धृत atoms हैं, और साथ में कोई भी सक्रिय परिष्करण चिप। 20,000 पंक्तियों पर सीमित, और यह बात बताई जाती है।","changelog.90356999c878":"<strong>SRC-M02 — परिणामों में खोजें।</strong> <code>Ctrl+Shift+F</code> एक दूसरे चरण का बॉक्स खोलता है जो क्वेरी फिर से चलाने के बजाय स्क्रीन पर पहले से मौजूद सेट को सीमित करता है। हर शब्द हटाई जा सकने वाली चिप बन जाता है, इसलिए ज़रूरत से ज़्यादा सीमित हो जाने पर फिर से टाइप करने के बजाय एक क्लिक लगता है। पथ विभाजक वाला शब्द पूरे पथ से मेल खाता है, नहीं तो फ़ाइल नाम से। निर्यात और सभी चुनें परिष्कृत सेट पढ़ते हैं, इसलिए वे कभी उन पंक्तियों पर काम नहीं करते जिन्हें किसी चिप ने नज़र से हटा दिया है। <em>(फ़िल्टर व्यवस्थित करें अब <code>Ctrl+Shift+O</code> पर है।)</em>","changelog.e01ea66e064f":"<strong>SRC-M03 — Everything के साथ अंतर-संचालन वाला आयात/निर्यात।</strong> <code>File → Export Results…</code> save डायलॉग में चुने गए एक्सटेंशन से अपना प्रारूप तय करता है: <code>.efu</code>, <code>.csv</code>, <code>.txt</code>, <code>.m3u</code> / <code>.m3u8</code>, <code>.ndjson</code>, <code>.json</code>। <code>.efu</code>, voidtools के Everything के साथ बाइट-स्तर पर संगत है — शाब्दिक <code>Filename,Size,Date Modified,Date Created,Attributes</code> हेडर, CRLF पंक्तियाँ, RFC-4180 quoting, और सीमा पर रूपांतरित Windows FILETIME ticks, ताकि Linux या macOS पर लिखी गई सूची Windows पर Everything में बिना बदलाव के लोड हो जाए। प्लेलिस्ट निर्यात में केवल ऑडियो होता है और यह बताया जाता है कि कितनी में से कितनी पंक्तियाँ लिखी गईं। <code>File → Open File List…</code> एक सूची लोड करता है और लाइव इंडेक्स <em>की जगह</em> उसमें खोजता है — अनप्लग किए गए वॉल्यूम के लिए &quot;वह फ़ाइल किस ड्राइव पर थी?&quot; का उत्तर। लोड की गई सूची पर मिलान नाम-या-पथ substring से होता है, DSL से नहीं।","changelog.d5c8d8b6e6ed":"<strong>SRC-M04 — इससे खोलें…</strong> किसी परिणाम के प्रकार के लिए पंजीकृत अनुप्रयोगों की प्रति-OS गणना: Windows पर <code>SHAssocEnumHandlers</code> (Explorer का अपना स्रोत), Linux पर साझा MIME डेटाबेस के विरुद्ध <code>.desktop</code> <code>MimeType=</code> मिलान, और macOS पर घोषित bundle document types के साथ <code>/usr/bin/open -a</code>।","changelog.00c9693a1527":"<strong>SRC-M05 — उन्नत कॉपी क्रियाएँ।</strong> किसी टेक्स्ट फ़ाइल की <em>सामग्री</em> कॉपी करें; फ़ाइलों को ही OS क्लिपबोर्ड फ़ाइल objects के रूप में कॉपी करें (<code>CF_HDROP</code>, <code>NSPasteboard</code> file URLs, <code>x-special/gnome-copied-files</code>); और बहु-चयन को चार quoting शैलियों में पथ सूची के रूप में कॉपी करें।","changelog.678cdb17b71c":"<em>प्रलेखित प्रति-OS अपवाद:</em> Linux पर कोई ऐसा in-process क्लिपबोर्ड नहीं है जो लिखने वाले प्रोसेस के बंद होने के बाद भी बना रहे, इसलिए file-object कॉपी के लिए <code>wl-clipboard</code> या <code>xclip</code> चाहिए, और दोनों में से कोई इंस्टॉल न होने पर यह बात बताई जाती है।","changelog.c00e9441825d":"<strong>SRC-M06 — यहाँ टर्मिनल और कस्टम कमांड।</strong> &quot;यहाँ टर्मिनल खोलें&quot; परिणाम के फ़ोल्डर में प्लेटफ़ॉर्म का टर्मिनल लॉन्च करता है। उपयोगकर्ता-परिभाषित कमांड <strong>सेटिंग → सामान्य → कस्टम कमांड</strong> में रहते हैं, <code>{path}</code> / <code>{dir}</code> / <code>{name}</code> / <code>{stem}</code> / <code>{ext}</code> placeholders और वैकल्पिक प्रति-एक्सटेंशन दायरे के साथ। हर विस्तार एक <code>argv</code> स्लॉट बनता है।","changelog.561fa38bf46d":"<strong>SRC-M07 — <code>dupe:</code> परिवार चालू हुआ।</strong> <code>dupe:</code> (समान नाम <em>और</em> आकार), <code>name-dupe:</code> / <code>dupe:name</code>, और <code>size-dupe:</code> / <code>dupe:size</code> अब <code>ModifierKind::Reserved</code> में पार्स होने के बजाय वास्तव में चलते हैं। पहचान सीधे इंडेक्स से होती है — कोई hashing नहीं, वह SRC-N22 का काम है। मेल खाने वाली पंक्तियाँ एक समूह हेडर के नीचे इकट्ठी होती हैं। डायरेक्टरी कभी किसी समूह में नहीं आतीं। <code>similar:</code> की तरह यह परिवार भी केवल root स्थिति में ही मान्य है।","changelog.0610973d550f":"<em>स्थायी नियम (Standing Rule) #8 टिप्पणी:</em> <code>dupe:foo</code> पहले पार्स होकर निष्पादन के समय विफल होता था। अब यह <em>पार्स</em> के समय ही <code>InvalidModifierValue</code> के साथ विफल होता है — वही उन्नयन जो ऑडियो मॉडिफ़ायर को चरण 9 में मिला था। जिस किसी क्वेरी ने कभी परिणाम लौटाए थे, उसका व्यवहार नहीं बदला।","changelog.761324a5cfcc":"<strong>SRC-M08 — ख़ालीपन वाले मॉडिफ़ायर।</strong> <code>empty:</code> (अकेला, या <code>empty:file</code> / <code>empty:folder</code> / <code>empty:roots</code> के साथ दायरा तय करके), <code>child-count:</code> और <code>descendant-count:</code>, जिनका उत्तर फ़ाइल सिस्टम पर चले बिना इंडेक्स डेटा से दिया जाता है। <code>empty:roots</code> हर उस फ़ोल्डर श्रृंखला का <em>शीर्ष</em> बताता है जिसमें किसी भी गहराई पर कोई फ़ाइल नहीं है; गिनती वाले मॉडिफ़ायर केवल डायरेक्टरी से मेल खाते हैं। नया <code>freally_index::DirStats</code>, <code>files.db</code> पर एक ही पास में इंडेक्स की डायरेक्टरी संरचना निकालता है, जो applied-event counter के आधार पर memoize होती है।","changelog.b3468cd50e03":"<strong>सहायक UI।</strong> परिणाम का right-click मेनू, मुख्य विंडो की toast सतह, और परिष्करण पट्टी — सभी कीबोर्ड से पहुँच योग्य।","changelog.53d34aa4b652":"<strong>टेस्ट।</strong> <code>tests/smoke/build_01_dsl.rs</code> और <code>build_01_interop.rs</code> दोनों मॉडिफ़ायर परिवारों और <code>.efu</code> wire प्रारूप को गेट करते हैं; unit टेस्ट <code>DirStats</code>, codecs, quoting, placeholder विस्तार, <code>.desktop</code> पार्सिंग, मिलान का स्थान, provenance गेट, और crates के बीच तालिकाओं के lockstep को कवर करते हैं; <code>tests/unit/build_01.test.ts</code> frontend stores को कवर करता है।","changelog.73bc8a5d676f":"<strong>i18n।</strong> सभी 18 लोकेल में 55 नई कुंजियाँ; <code>xtask i18n-lint</code> हरा।","changelog.f56c4fe5f08d":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>KnownPaths</code> में कोई लिखने वाला नहीं था। चरण 12 ने query hits को डेमन notifications में भेज दिया और उन्हें पंजीकृत करने का काम किसी ने नहीं सँभाला, इसलिए हर gated फ़ाइल-ऑपरेशन हर परिणाम पंक्ति को अस्वीकार करता था। <code>daemon.rs</code> अब <code>query:batch</code> के गुज़रते समय उन्हें पंजीकृत करता है।","changelog.fe76b18c0f5e":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>finalize_bootstrap</code>, <code>applied_events</code> को आगे नहीं बढ़ाता था, इसलिए स्कैन के बीच निकाला गया <code>DirStats</code> पूरे हो चुके इंडेक्स के लिए भी कैश बना रहता था — जिससे अगले जर्नल batch तक <code>empty:folder</code> हर डायरेक्टरी से मेल खाता था।","changelog.83072c3967c3":"<strong>[सभी प्लेटफ़ॉर्म]</strong> असमर्थित स्थिति वाला <code>dupe:</code> तब चुपचाप हटा दिया जाता था जब कोई दूसरा शीर्ष स्तर पर हो (<code>dupe:name !size-dupe:</code> बिना त्रुटि के शून्य hits लौटाता था)। स्थिति guard अब अनुपस्थिति जाँचने के बजाय नोड गिनता है।","changelog.abf1376b827c":"<strong>[सभी प्लेटफ़ॉर्म]</strong> जब पूरे स्कैन किए गए ट्री में कोई फ़ाइल न हो, तब <code>empty:roots</code> कुछ नहीं बताता था: हर पंक्ति अपने parent के लिए एक गिनती प्रविष्टि बनाती है, इसलिए स्कैन रूट का अपना parent इंडेक्स किया हुआ दिखता था।","changelog.24ee98d1fa85":"<strong>[सभी प्लेटफ़ॉर्म]</strong> ऐसे predicate का निषेध, जिसका निर्णय नाम इंडेक्स नहीं कर सकता (<code>!empty:file</code>, <code>!size:&gt;1mb</code>), शून्य पंक्तियाँ लौटाता था — नाम चरण की &quot;जाने दो&quot; परिपाटी <code>NOT</code> के तहत उलटकर अस्वीकृति बन जाती है। यह पहले से मौजूद था; बिल्ड 1 ने इसे उभार दिया।","changelog.8d60d2e391a7":"<strong>[सभी प्लेटफ़ॉर्म]</strong> hit viewer हर पंक्ति की लोअरकेस <em>प्रति</em> में मिलान ढूँढता था जबकि UI मूल पंक्ति को काटता था, जिससे <code>İ</code> वाली पंक्ति पर हर हाइलाइट खिसक जाता था। ऑफ़सेट अब मूल टेक्स्ट को इंडेक्स करते हैं, और needle व haystack एक जैसे फ़ोल्ड होते हैं।","changelog.83b5581b542c":"<strong>[Linux]</strong> विफल <code>wl-copy</code> (X11 के तहत चलते हुए) सफलता बताता था, इसलिए &quot;फ़ाइल के रूप में कॉपी करें&quot; काम करने का दावा करता था, क्लिपबोर्ड को अछूता छोड़ देता था, और कभी <code>xclip</code> पर नहीं जाता था।","changelog.4695c56f4771":"<strong>[Windows]</strong> COM guard तब भी <code>CoUninitialize</code> कॉल करता था जब <code>CoInitializeEx</code> ने <code>RPC_E_CHANGED_MODE</code> लौटाया हो — जिससे उस थ्रेड को वास्तव में initialize करने वाले के नीचे से COM उखड़ जाता था।","changelog.e39b26f32960":"<strong>[CI]</strong> <code>vendor/freally-central</code> (और Freally ऐप्स पैनल) एक ऐसा सबमॉड्यूल था जो अब मौजूद न रही एक रिपॉज़िटरी की ओर इशारा करता था, इसलिए हर OS पर हर रन <em>checkout</em> पर विफल होता था। पैनल को सादे सोर्स के रूप में vendored किया गया है और दोनों workflows <code>submodules: false</code> सेट करते हैं, इसलिए रिपॉज़िटरी एक clone से बिना किसी और चीज़ के बिल्ड होती है।","changelog.0cb6b784b78e":"<strong>[सभी प्लेटफ़ॉर्म]</strong> कस्टम-एक्सट्रैक्टर होस्ट में <code>wasmtime</code> 44.0.1 → 47.0.3, जिससे <strong>RUSTSEC-2026-0222</strong> बंद हुआ (engines के बीच type indices आपस में गड़बड़ा सकते हैं)। केवल उपयोगकर्ता द्वारा इंस्टॉल किए गए WASM एक्सट्रैक्टर से पहुँचा जा सकता है, पर <code>cargo-deny</code> हर हाल में बिल्ड को इस पर गेट करता है।","changelog.e131be0feec2":"<strong>[सभी प्लेटफ़ॉर्म]</strong> फ़ाइल-सूची का निर्यात और आयात अब अपने OS डायलॉग <strong>Rust में</strong> खोलते हैं और वापस पढ़े गए पथ पर काम करते हैं। गंतव्य को webview से होकर भेजने का अर्थ था कि <code>file_list_export</code> — बिल्ड 1 का पहला <em>write</em>-side कमांड — frontend द्वारा बताए गए किसी भी पथ को अधिलेखित कर देता, और जिस रजिस्ट्री प्रविष्टि के विरुद्ध वह जाँच करता था उसे frontend ख़ुद बना सकता था। <code>KnownPaths</code> में एक <code>Provenance</code> आयाम भी जुड़ा, ताकि frontend की पहुँच वाली कोई अनुमति कभी लिखने की अनुमति न दे सके।","changelog.d1a9848c839b":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>run_custom_command</code> एक कमांड <strong>id</strong> लेता है और उसे backend की सहेजी गई सेटिंग के विरुद्ध resolve करता है। IPC पर <code>program</code> फ़ील्ड स्वीकार करने से यह मनमाना प्रोसेस चलाने का primitive बन गया था: जब caller executable भी ख़ुद चुनता हो, तो <code>Command::arg</code> से तर्क भेजना कोई सुरक्षा नहीं है।","changelog.ed41b394f8fd":"पूरे threat-model बदलाव के लिए <code>docs/SECURITY.md</code> देखें।","changelog.c99d8fed1d7c":"<span class=\"release__meta\"><span class=\"release__ver\">v0.20.1</span><time class=\"release__date\" datetime=\"2026-07-10\">2026-07-10</time></span>","changelog.2cd4002ecd32":"बिना नई सुविधाओं वाली एक पैच रिलीज़। यह इसलिए है क्योंकि v0.20.0 ख़ुद को ठीक नहीं कर सकता: अपडेटर endpoint शिप हुई बाइनरी में कंपाइल है, इसलिए हर इंस्टॉल एक ऐसी रिपॉज़िटरी जाँच रहा है जो मौजूद नहीं है, और उसे कभी अपडेट नहीं मिलेगा। यही बिल्ड इसे ठीक करता है, और इसमें वे सुरक्षा उन्नयन भी हैं जो v0.20.0 के बाद आए।","changelog.4bffda6c3827":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>quick-xml</code> 0.39.4 → 0.41.0, जिससे <strong>RUSTSEC-2026-0194</strong> (start tag में डुप्लिकेट attribute नाम जाँचते समय quadratic रन टाइम) और <strong>RUSTSEC-2026-0195</strong> (<code>NsReader</code> में namespace-declaration का असीमित आवंटन, मेमोरी ख़त्म करने वाला denial of service) बंद हुए। दोनों तक पहुँचा जा सकता है: <code>freally-extractors</code> के docx और pptx एक्सट्रैक्टर अविश्वसनीय Office XML सीधे <code>quick_xml::Reader</code> में डालते हैं। कोई शत्रुतापूर्ण दस्तावेज़ एक्सट्रैक्टर होस्ट को अटका सकता था या उसके संसाधन ख़त्म कर सकता था। लाइसेंस अपरिवर्तित (MIT)।","changelog.68001f921152":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>calamine</code> 0.34.0 → 0.36.0 — पहली रिलीज़ जो <code>quick-xml ^0.41</code> स्वीकार करती है, इसलिए यह अपने आप में कोई बदलाव नहीं बल्कि ऊपर वाले की आवश्यकता है। लाइसेंस अपरिवर्तित (MIT)। इसकी transitive <code>zip</code> 7 → 8 पर जाती है; वर्कस्पेस की अपनी <code>zip</code> 5 पर ही pinned रहती है।","changelog.d7a4cb594270":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>crossbeam-epoch</code> 0.9.18 → 0.9.20, जिससे <strong>RUSTSEC-2026-0204</strong> बंद हुआ (<code>Atomic</code> और <code>Shared</code> के <code>fmt::Pointer</code> impl में, अंतर्निहित pointer अमान्य होने पर, अमान्य pointer dereference)। transitive और semver-संगत। लाइसेंस अपरिवर्तित (MIT OR Apache-2.0)।","changelog.4aabc8b9de68":"तीनों अपग्रेड करके ठीक किए गए। <code>deny.toml</code> की ignore सूची में कोई advisory नहीं जोड़ी गई।","changelog.6fd7a68afb1a":"<strong>[सभी प्लेटफ़ॉर्म]</strong> स्वतः-अपडेटर अब उस रिपॉज़िटरी की ओर इशारा करता है जिसमें यह प्रोजेक्ट वास्तव में है। <code>tauri.conf.json</code> में <code>MikesRuthless12/Freally</code> लिखा था, जो मौजूद नहीं है, इसलिए <code>latest.json</code> 404 पर पहुँचता था और <strong>किसी भी शिप हुए बिल्ड में स्वतः-अपडेट ने कभी काम नहीं किया</strong>। चूँकि endpoint बाइनरी में ही बसा है, v0.19.84 और v0.20.0 मृत URL को poll करते रहेंगे; केवल इस रिलीज़ या बाद के इंस्टॉल ही अपडेट ढूँढ सकते हैं।","changelog.4a77c5b010f4":"<span class=\"release__meta\"><span class=\"release__ver\">v0.20.0</span><time class=\"release__date\" datetime=\"2026-07-01\">2026-07-01</time></span>","changelog.ff6c265c78c6":"इस रिलीज़ के लिए कोई नोट्स नहीं लिखे गए। इसने क्या बदला, यह केवल <code>v0.19.84</code> और <code>v0.20.0</code> के बीच की commit range से ही निकाला जा सकता है; इसे यहाँ फिर से गढ़ने के बजाय अनुपस्थित के रूप में दर्ज किया गया है, क्योंकि पाँच महीने बाद लिखा गया विश्वसनीय-सा सारांश, तथ्य के ही प्रारूप में लिपटा एक अनुमान होता है। इसके बारे में निश्चित रूप से ज्ञात एकमात्र बात नीचे <code>[0.20.1]</code> में है: इसका अपडेटर endpoint एक ऐसी रिपॉज़िटरी का नाम लेता था जो मौजूद नहीं है, और यह ख़ुद को ठीक नहीं कर सकता था।","changelog.648e810f75b8":"<span class=\"release__meta\"><span class=\"release__ver\">v0.19.84</span><time class=\"release__date\" datetime=\"2026-06-21\">2026-06-21</time></span><span class=\"release__title\">चरण 0–12 · पहला सार्वजनिक बिल्ड</span>","changelog.abfb5e516e09":"ये नोट्स 2026-05-11 से 2026-08-21 तक, पाँच टैग की गई रिलीज़ के दौरान, <code>## [Unreleased]</code> के नीचे पड़े रहे। ये अप्रकाशित काम नहीं हैं और कभी थे भी नहीं — नीचे चरण 0 की प्रविष्टि &quot;पहला सार्वजनिक टैग <strong>v0.19.84</strong> होगा&quot; पर ख़त्म होती है, और यही यह अनुभाग दर्ज करता है। टैग 2026-06-21 को बना, पर किसी ने शीर्षक का नाम नहीं बदला, और उसके बाद की हर रिलीज़ को वही ब्लॉक विरासत में मिला।","changelog.c8dfea56f286":"यह एक वास्तविक ख़तरा था, सिर्फ़ अव्यवस्था नहीं। release workflow <code>## [Unreleased]</code> का नाम बनाए जा रहे संस्करण में बदलकर अपने प्रकाशित नोट्स बनाता है, इसलिए अगली रिलीज़ चरण 0–12 के काम की 533 पंक्तियाँ — पाँच महीने पुरानी, पहले से हर इंस्टॉल में — ऐसे शिप कर देती मानो वे नई हों। इसे <code>v0.19.84</code> और <code>v0.20.0</code> के बीच बाँटने के बजाय उस टैग की तिथि दी गई है जिसमें यह शिप हुआ, क्योंकि इसकी हर प्रविष्टि दोनों से पहले की है।","changelog.14161839f591":"नीचे का सब कुछ बिल्ड 1–3 रिलीज़ से पहले का है और कभी किसी संस्करण अनुभाग में नहीं ले जाया गया। इसे अनुमान के आधार पर <code>0.21.0</code>–<code>0.23.0</code> में पीछे से डालने के बजाय यहाँ जस का तस छोड़ा गया है; इसे छाँटना अपने आप में एक अलग काम है।","changelog.f1873f116239":"TASK-098 — सभी 18 लोकेल में शुरू से अंत तक पूर्ण Fluent i18n (2026-05-11)","changelog.495b18f2f513":"18 लोकेल वाला Fluent loader अब जुड़ गया है। सेटिंग → लोकेल (या प्रथम-रन विज़ार्ड) में भाषा बदलने पर UI की हर अनूदित स्ट्रिंग — मेनू, स्थिति बार, सेटिंग पैनल, डायलॉग और विज़ार्ड — बिना रीस्टार्ट के फिर से रेंडर होती है।","changelog.78760917c35b":"<strong>लोडर।</strong>","changelog.5f1a08de08be":"<code>apps/freally-ui/src/lib/i18n/bundle.ts</code> चरण-11 की <code>EN_FTL</code> इनलाइन स्ट्रिंग की जगह <code>import.meta.glob(&quot;../../../../../locales/*/freally.ftl&quot;, { query: &quot;?raw&quot;, eager: true })</code> का उपयोग करता है। सभी 18 <code>.ftl</code> फ़ाइलें बिल्ड के समय इनलाइन हो जाती हैं; हर <code>FluentBundle</code> के नीचे fallback संसाधन के रूप में <code>en</code> की परत होती है, ताकि कोई भूली-भटकी गायब कुंजी कच्ची key string के बजाय अंग्रेज़ी में दिखे।","changelog.a9d6f49ee814":"<code>vite.config.ts</code>, <code>server.fs.allow</code> को वर्कस्पेस रूट तक बढ़ाता है ताकि dev मोड package रूट के बाहर मौजूद लोकेल ट्री को पढ़ सके।","changelog.d354155cedc1":"<code>bundle.ts</code>, <code>loadedLocales()</code> export करता है ताकि test suite assert कर सके कि glob ने वास्तव में सभी 18 फ़ाइलें उठाईं।","changelog.50aa545a0dff":"<strong>अनुवाद डेटा — स्थायी नियम (Standing Rule) #4 lockstep।</strong>","changelog.c8b21089e4f2":"<code>en/freally.ftl</code> 314 से बढ़कर 557 कुंजियों का हो गया। 243 नई कुंजियाँ कवर करती हैं: विज़ार्ड का परिष्कार (संकेत, placeholders, &quot;चरण N / N&quot;), स्थिति बार के खंड, लेंस / पूर्वावलोकन / बुकमार्क स्ट्रिंग, परिचय / कनेक्ट डायलॉग, हर UI/होम/बैकअप/कीबोर्ड/इतिहास/लोकेल/फ़ोल्डर/वॉल्यूम पैनल का संकेत + अनुभाग शीर्षक + toast, और PRD §8.28 का पूरा मेनू बार (हर फ़ाइल/संपादन/दृश्य/खोज/बुकमार्क/उपकरण/सहायता लेबल + हर सबमेनू शीर्षक + हर hover-संकेत)।","changelog.8f7a7778b776":"यही 243 कुंजियाँ बाकी सभी 17 लोकेल में समानांतर रूप से दोहराई गईं (es, de, fr, it, nl, pl, pt-BR, tr, vi, id, ru, uk, ar, hi, ja, ko, zh-CN)। हर <code>.ftl</code> अब वही 557 कुंजियाँ resolve करता है; नया <code>tests/unit/i18n.test.ts</code> lockstep टेस्ट हर CI रन पर इसे assert करता है।","changelog.3b3366de3c39":"<strong>कंपोनेंट रूपांतरण।</strong>","changelog.c65098e5c147":"<code>menu_spec.ts</code> में हर <code>MenuItemSpec</code> और <code>MenuSubmenu</code> पर एक <code>l10n</code> कुंजी जुड़ी, और स्थिति-बार hover संकेतों के लिए एक <code>hintL10n</code>। <code>MenuBar.svelte</code> इन्हें <code>labelOf(spec)</code> / <code>hintOf(spec)</code> helpers से resolve करता है, जो अनुवाद कुंजी न होने पर शाब्दिक <code>label</code>/<code>hint</code> पर लौट आते हैं।","changelog.ef3a0f5b03d9":"FirstRunWizard अपना शीर्षक, चरण संख्या, हर चरण का शीर्षक + संकेत, थीम कार्ड, और पीछे/आगे/समाप्त करें बटन <code>t()</code> से रेंडर करता है। हॉटकी वाला चरण विज़ार्ड के पिछले दौर में पहले ही हटा दिया गया था; हॉटकी कॉन्फ़िगरेशन सेटिंग → कीबोर्ड में बना रहता है।","changelog.4124e2c07aee":"StatusBar इनके लिए <code>t()</code> उपयोग करता है: index-phase खंड (&quot;अनुक्रमित (N फ़ाइलें)&quot; / &quot;अनुक्रमण हो रहा है… N/M&quot; / &quot;रोका गया&quot; / &quot;त्रुटि&quot;), परिणाम-संख्या का बहुवचन (<code>status-result-count-one</code> बनाम <code>…-many</code>), चयन आकार बैज, क्वेरी समय, लेंस समय बैज, और local-DB / remote-endpoint खंड। थीम बदलने वाले बटन का <code>aria-label</code> और हॉटकी hover संकेत अब अनुवाद योग्य हैं।","changelog.a3b5fe09b103":"सेटिंग डायलॉग — <code>SettingsDialog.svelte</code>, <code>SettingsTreeNav.svelte</code>, <code>SettingsButtonBar.svelte</code>, <code>LocalePanel.svelte</code>, और साथ में अनुक्रमणिकाएँ, लेंस, नेटवर्क और विविध समूहों के पैनल (UI / होम / खोज / परिणाम / दृश्य / संदर्भ मेनू / फ़ॉन्ट और रंग / कीबोर्ड / अनुक्रमणिकाएँ-शीर्ष / वॉल्यूम / फ़ोल्डर / फ़ाइल सूचियाँ / बहिष्कृत करें / फ़ाइल नाम / सामग्री / ऑडियो / समानता / कस्टम / HTTPS / ETP / इतिहास / गोपनीयता / लॉग / बैकअप / परिचय)।","changelog.f3afe9f2e294":"बुकमार्क, पूर्वावलोकन फलक, और <code>LensSection</code> के empty-state / संक्षिप्त करने वाले नियंत्रण।","changelog.7ad5ec734228":"<strong>RTL अब चेकबॉक्स नहीं, स्वचालित है।</strong>","changelog.adaca56bf336":"सेटिंग → लोकेल में &quot;RTL पूर्वावलोकन&quot; चेकबॉक्स हटा दिया गया है। RTL उन लोकेल के लिए स्वतः लागू होता है जिनकी मूल लिपि RTL है — अभी शिप होने वाले लोकेल में इस श्रेणी में केवल <code>ar</code> है। <code>applyRtlForLocale</code> अपनी आंतरिक <code>RTL_LOCALES</code> अनुमति-सूची देखता है; <code>bootstrap.ts</code> का <code>locale_settings.rtl_preview</code> फ़ील्ड पिछली संगतता के लिए सहेजी गई स्टेट में बना रहता है, पर UI अब उसे नहीं दिखाता।","changelog.b2a93dfa6039":"<strong>टेस्ट।</strong>","changelog.cd3c3612b144":"नया <code>tests/unit/i18n.test.ts</code> कवर करता है: (a) glob ने वास्तव में सभी 18 लोकेल लोड किए, (b) <code>bundleFor(code)</code> ऐसा bundle लौटाता है जो हर लोकेल के लिए एक canary कुंजी resolve करता है, (c) 18 लोकेल कुंजी सेट पर पूरी तरह lockstep में हैं, (d) <code>settingsStore.state.locale</code> बदलने से <code>t()</code> का लौटाया मान बदलता है, (e) अज्ञात लोकेल कच्ची key string के बजाय <code>en</code> से होकर fallback करता है, (f) अज्ञात कुंजी वही कुंजी लौटाती है।","changelog.82baaedc9013":"चरण-12 परिष्कार दौर — UX, विश्वसनीयता और live-apply (2026-05-11)","changelog.2907b565b163":"एक लंबे डिबगिंग सत्र के दौरान व्यवहार से जुड़ा बड़ा दौर। अधिकांश सुधार सीधे voidtools-Everything की बराबरी वाले लाभ हैं, और साथ में वह बुनियादी विश्वसनीयता का काम जो डेवलपमेंट के दौरान डेस्कटॉप ऐप को बार-बार चलाना सुखद बनाता है।","changelog.f8b766536c97":"<strong>Single-instance + बिना रोके डेमन बूट।</strong>","changelog.e7d0360bc90d":"<code>kill_other_freally_instances()</code> Windows पर <code>run()</code> की शुरुआत में चलता है (<code>freally-ui.exe</code> + <code>freally-indexd.exe</code> के विरुद्ध taskkill <code>/F /T</code>, ख़ुद को छोड़कर बाकी PIDs तक सीमित), ताकि ऐप फिर से लॉन्च करने पर हाथ से प्रोसेस बंद किए बिना हमेशा साफ़ शुरुआत हो। macOS / Linux पर बराबरी के लिए stub।","changelog.a731267547b9":"<code>Daemon::boot</code> अब <code>tauri::Builder::setup</code> के भीतर एक समर्पित <code>freally-daemon-boot</code> थ्रेड बनाता है; setup hook तुरंत लौट आता है और विंडो फ़ौरन दिखती है। पहले canonical-store replay GUI थ्रेड को 10-15 s तक रोक सकता था, जिससे Windows का non-responsive-window watchdog सक्रिय होकर किसी HWND के बनने से पहले ही प्रोसेस गिरा देता था।","changelog.59d90e38c9ea":"consumer की ओर <code>Client::connect</code> को 500 × 40 ms के retry loop में लपेटा गया है, ताकि धीमा डेमन बूट एक अकेली connect race में हार न जाए।","changelog.2f85875a08d3":"<strong>फ़िल्टर चिप + खोज मेनू — OR संयोजन के साथ बहु-चयन।</strong>","changelog.9f34cca2f956":"नया <code>lib/stores/type_filter.svelte.ts</code> एक <code>Set&lt;TypeFilterId&gt;</code> रखता है; डिफ़ॉल्ट पूरा सेट है (Everything मोड)। <code>toQueryFragment()</code> आंशिक चयन के लिए पार्सर-स्तर का <code>(audio: OR video: OR …)</code> समूह देता है, और &quot;सब कुछ&quot; या &quot;कुछ नहीं&quot; के लिए ख़ाली स्ट्रिंग, जिससे डेमन की ओर का AND-of-prefixes वाला जाल ख़त्म हो जाता है।","changelog.8adb4f889882":"<code>QuickFiltersPalette.svelte</code> की चिप सीधे store को टॉगल करती हैं; <code>Search → …</code> के मेनू आइटम <code>radio</code> से <code>checkable</code> में बदल जाते हैं, और <code>MenuBar.isItemChecked</code> store पढ़ता है। &quot;Everything&quot; <code>selected.size === ALL.length</code> से निकलता है — किसी एक चिप पर क्लिक करने से वह चिप और Everything दोनों बंद हो जाते हैं, बाकी बनी रहती हैं।","changelog.5246ff18704a":"<code>bookmarks.add</code> खोज टेक्स्ट के साथ सक्रिय फ़िल्टर सेट भी सहेजता है; Rust <code>Bookmark</code> DTO में <code>#[serde(default)]</code> के साथ <code>filters: Vec&lt;String&gt;</code> जुड़ा, ताकि मौजूदा <code>bookmarks.json</code> फ़ाइलें deserialize होती रहें। किसी बुकमार्क पर क्लिक करने से textbox की सामग्री (<code>queryStore.setSource</code> से) और चिप चयन (<code>typeFilterStore.setFromIds</code> से) दोनों पुनर्स्थापित होते हैं।","changelog.942a0601c778":"संग्रह (Archive) का टोकन ठीक किया: <code>compressed: &quot;zip:&quot;</code> → <code>&quot;archive:&quot;</code> (<code>freally-query::quick_filters</code> से असली <code>QuickFilter::Archive</code> उपनाम)। पुराना <code>zip:</code> समूह के भीतर बस एक एक्सटेंशन था, इसलिए संग्रह कभी किसी चीज़ से मेल नहीं खाता था।","changelog.6de9bf011469":"<strong>आरंभिक Everything क्वेरी + everything-मोड बराबरी।</strong>","changelog.29e61abbcb91":"<code>bootstrap.ts</code> में <code>runInitialEverythingQuery()</code> hydrate के बाद एक बार चलता है और 60 × 800 ms तक <code>resultsStore.batches.length</code> को poll करता है, नए <code>run()</code> कॉल तभी शुरू करता है जब कुछ भी in-flight न हो, ताकि यह स्वचालित कॉल अपनी ही क्वेरी रद्द न करे। लॉन्च के बाद पहली रेंडरिंग &quot;आरंभ करने के लिए कोई क्वेरी लिखें।&quot; के बजाय तुरंत परिणाम दिखाती है।","changelog.c323e4a1d454":"जब पूरा type-filter सेट चुना हो और खोज बॉक्स ख़ाली हो, तो <code>resultsStore.run()</code> एक अकेला <code>*</code> वाइल्डकार्ड बनाता है ताकि फ़ाइल नाम लेंस हर इंडेक्स की गई प्रविष्टि सूचीबद्ध करे (voidtools-Everything की बराबरी)।","changelog.2c27ce8face6":"<code>ResultList.svelte</code> का placeholder गेट अपडेट हुआ: &quot;आरंभ करने के लिए कोई क्वेरी लिखें&quot; तभी दिखता है जब स्रोत ख़ाली हो और साथ ही कोई type filter चुना न हो (यानी उपयोगकर्ता ने स्पष्ट रूप से हर चिप का चयन हटा दिया हो)।","changelog.28ad0f2414d6":"<strong>फ़ोल्डर इंडेक्सिंग।</strong>","changelog.c21ab8d7106b":"<code>crates/freally-indexd/src/scanner.rs::scan_folder</code> अब फ़ाइलों के साथ डायरेक्टरी भी इंडेक्स करता है; walkdir पथ <code>is_file() || is_dir()</code> पर फ़िल्टर करता है और जर्नल event के <code>attrs</code> फ़ील्ड में <code>FILE_ATTRIBUTE_DIRECTORY (0x10)</code> लगाता है।","changelog.799bfffa54d6":"<code>crates/freally-journal-win/src/subscriber.rs</code> का MFT bootstrap पथ अब डायरेक्टरी रिकॉर्ड नहीं छोड़ता — वे अपने असली <code>file_attributes</code> bitmask के साथ ज्यों के त्यों आगे जाते हैं।","changelog.709c7429febd":"<code>QueryHit</code> (Rust DTO + मेल खाता TS interface) में एक <code>attrs: u32 #[serde(default)]</code> फ़ील्ड जुड़ा जिसे डेमन <code>FileRow.attrs</code> से भरता है। UI <code>0x10</code> बिट से फ़ाइल और फ़ोल्डर में अंतर करता है।","changelog.694ce7c4310f":"<strong>असली Windows shell आइकन + प्रति-पंक्ति रेंडरिंग।</strong>","changelog.4479cd257069":"नया <code>apps/freally-ui/src-tauri/src/commands/icons.rs</code> — <code>icon_for_ext(ext, is_dir) -&gt; Option&lt;String&gt;</code> async Tauri कमांड जो <code>SHGFI_USEFILEATTRIBUTES</code> के साथ Win32 <code>SHGetFileInfoW</code> चलाता है (ताकि <code>_.xml</code> जैसा नकली पथ, डिस्क पर फ़ाइल के वास्तव में मौजूद हुए बिना, पंजीकृत handler का आइकन resolve कर ले) → <code>GetIconInfo</code> → <code>GetDIBits</code> से 32-bit BGRA → BGRA→RGBA channel swap → <code>image</code> crate से PNG → base64 data URL। फ़िलहाल macOS / Linux पर <code>None</code> लौटाता है।","changelog.6794e87b4eb5":"<code>src-tauri/Cargo.toml</code>: <code>image = &quot;0.25&quot; --no-default-features --features png</code>, <code>base64 = &quot;0.22&quot;</code>, और <code>cfg(windows)</code> के तहत संबंधित <code>windows = &quot;0.59&quot;</code> feature सेट जोड़ता है।","changelog.9e73805e7e38":"नया <code>lib/stores/icon_store.svelte.ts</code> — <code>Map&lt;(ext, is_dir), Promise&lt;dataUrl | null&gt;&gt;</code> कैश, ताकि 200 परिणाम पंक्तियाँ प्रति पंक्ति नहीं, बल्कि हर अनोखे एक्सटेंशन पर एक IPC करें। एक reactive <code>tick</code> फ़ील्ड जो हर resolution पर बढ़ता है ताकि $derived consumers फिर से रेंडर हों।","changelog.872e5a605907":"<code>ResultRow.svelte</code> का नाम कॉलम <code>iconStore.get(hit.ext, isDir)</code> से लिया गया <code>&lt;img class=&quot;row-icon&quot; src=…&gt;</code> रेंडर करता है, और data URL लोड होने तक emoji fallback (<code>📁</code> / <code>📄</code>) दिखाता है।","changelog.eb2ed58a295d":"<strong>MFT bootstrap में असली मेटाडेटा।</strong>","changelog.392710a87044":"USN रिकॉर्ड में FRN + attrs + एक अकेला timestamp होता है पर फ़ाइल का आकार नहीं, इसलिए MFT-fast-path इंडेक्स में <code>size: 0</code> और केवल-USN timestamp लिखता था। <code>subscriber.rs</code> अब असली <code>len</code>, <code>modified</code>, <code>created</code> भरने के लिए हर भेजे गए event पर <code>std::fs::metadata(&amp;full)</code> करता है। शुद्ध USN walk से धीमा, पर सही — आकार और संशोधित कॉलम आख़िरकार walkdir fallback के लिए बाध्य किए बिना शून्य से भिन्न मान दिखाते हैं।","changelog.693e07211105":"<strong>खोज बॉक्स + परिणाम पंक्ति का रूप।</strong>","changelog.660ce86cdba0":"<code>SearchBar.svelte</code> अब <code>&lt;input value={queryStore.source}&gt;</code> को bind करता है, ताकि प्रोग्राम से होने वाले अपडेट (बुकमार्क क्लिक, Escape से साफ़ करना, भविष्य का deep-link) textbox में दिखें। <code>.raw</code> पर टूटा हुआ <code>color: transparent</code> भी हटा दिया (&quot;mirror&quot; syntax-highlight परत ठीक से संरेखित नहीं हो रही थी, इसलिए गहरे मोड में टाइप किया गया टेक्स्ट लगभग अदृश्य था) — input अब अपना टेक्स्ट ख़ुद रेंडर करता है और mirror छिपा हुआ है।","changelog.40ca8d425ec9":"<code>ResultRow.svelte</code> की पंक्ति CSS <code>--row-{state}-fg/bg/weight/style</code> पढ़ती है, ताकि फ़ॉन्ट और रंग पैनल के प्रति-स्थिति नियंत्रण लाइव रहें। जुड़ी हुई स्थितियाँ: normal, highlighted (hover), selected, selected_highlighted।","changelog.5442f7a05dd7":"वैकल्पिक-पंक्ति + hover specificity बग ठीक किया, जिसके कारण <code>:nth-child(even)</code> नियम के <code>.row.selected</code> पर भारी पड़ने पर चयनित पंक्ति अचयनित दिखती थी। दोनों selectors में अब <code>:not(.selected)</code> है, इसलिए चयनित पंक्ति index या hover चाहे जो हो, अपना cyan रंग बनाए रखती है।","changelog.1e3c5fb60489":"<strong>फ़ॉन्ट और रंग: live-apply + स्थायी सहेजना।</strong>","changelog.99c1c70df3e3":"नया <code>lib/stores/fonts_apply.svelte.ts::applyFontsAndColors()</code>, <code>settings.fonts_and_colors</code> से <code>&lt;html&gt;</code> पर CSS custom properties लिखता है: <code>--font-ui</code> (cross-OS fallback श्रृंखला के साथ), <code>--app-font-size</code>, प्रति-स्थिति <code>--row-…-fg/bg/weight/style</code>, प्रति-लेंस <code>--lens-…</code> overrides। bootstrap पर (hydrate के बाद) एक बार और फिर हर पैनल पैच पर कॉल होता है — लॉन्च के बीच पुनर्स्थापित होता है और बदलाव पर लाइव लागू होता है।","changelog.bd2af6cb049b":"<code>FontsAndColorsPanel.svelte</code> का फ़ॉन्ट इनपुट एक <code>&lt;select&gt;</code> ड्रॉपडाउन में बदल गया, जो <code>window.queryLocalFonts()</code> से भरा जाता है (Local Font Access API, जिसे Windows पर Tauri 2 WebView2 runtime समर्थन देता है), और non-Chromium webviews के लिए 25 फ़ैमिली की चुनी हुई fallback सूची है। हर विकल्प दृश्य पूर्वावलोकन के लिए अपने ही फ़ॉन्ट में रेंडर होता है।","changelog.0f1775f6dcaa":"UIPanel का थीम ड्रॉपडाउन सेटिंग पैच के साथ <code>themeStore.set(value)</code> भी कॉल करता है, ताकि हल्का/गहरा बदलाव चुनते ही लाइव लागू हो — लागू करें / रीस्टार्ट की ज़रूरत नहीं।","changelog.e689bf04af40":"<strong>दृश्य पैनल के टॉगल जोड़े गए।</strong>","changelog.af26fe7a3745":"App.svelte का $effect चुनी हुई सेटिंग को <code>&lt;body data-*&gt;</code> attributes पर प्रतिबिंबित करता है; <code>app.css</code> के नए CSS नियम उन पर प्रतिक्रिया देते हैं: <code>data-alternate-rows</code>, <code>data-row-mouseover</code> (false होने पर <code>.row:hover</code> को no-op कर देता है), <code>data-show-tooltips</code>, <code>data-show-lufs-badges</code>, <code>data-show-similarity-score</code>।","changelog.ba63c32bf658":"<code>ResultRow</code> की पंक्ति का <code>title={hit.path}</code> टूलटिप दिखाएँ सेटिंग पर निर्भर है।","changelog.be551e42463a":"<code>formatBytes</code> आकार प्रारूप सेटिंग का पालन करता है (<code>auto_binary</code> | <code>bytes</code> | <code>kb</code> | <code>mb</code> | <code>gb</code>)।","changelog.eb09c95dc5e6":"<strong>विंडो नियंत्रण — हमेशा ऊपर, आकार, ज़ूम।</strong>","changelog.f6f1716eda05":"<code>capabilities/default.json</code> गायब <code>core:window:allow-set-size</code>, <code>core:window:allow-set-always-on-top</code>, <code>core:window:allow-set-resizable</code>, <code>core:window:allow-inner-size</code>, <code>core:window:allow-outer-size</code> अनुमतियाँ जोड़ता है। इनके बिना हर <code>setSize</code> / <code>setAlwaysOnTop</code> कॉल Tauri IPC अनुमति गेट द्वारा चुपचाप अस्वीकार हो रही थी।","changelog.b60bdf35fa6a":"App.svelte में एक <code>$effect</code> जुड़ा जो <code>settings.on_top</code> + <code>queryStore.source</code> को <code>setAlwaysOnTop(...)</code> कॉल में बदलता है: कभी नहीं / हमेशा / खोज के दौरान — तीनों मोड लाइव, हर सेटिंग बदलाव और हर कीस्ट्रोक पर फिर से लागू। लॉन्च पर पुनर्स्थापित।","changelog.1f927e0b3720":"<code>setWindowSize</code> import ठीक किया: <code>LogicalSize</code>, <code>@tauri-apps/api/window</code> से आता है, न कि अस्तित्वहीन <code>@tauri-apps/api/dpi</code> से। चुना गया आकार <code>settings.window_size = { w, h }</code> भी लिखता है (<code>ALLOWED_PATCH_KEYS</code> में अनुमत), और bootstrap अगली लॉन्च पर सहेजा गया आकार पुनर्स्थापित करता है।","changelog.293b3c2deb7d":"<code>zoomStore</code>, <code>document.documentElement.style.fontSize</code> से बदलकर WebView की <code>zoom</code> CSS property पर आ गया, ताकि Ctrl+= / Ctrl+- वास्तव में (px-आधारित) UI का पैमाना बदलें। हर गुणक पर स्पष्ट।","changelog.7e52e273d7e8":"<strong>छवि पूर्वावलोकन।</strong>","changelog.6aa7a3ed566b":"<code>preview/windows_host.rs::preview</code>, PNG, JPG/JPEG/JFIF, GIF, WEBP, BMP, SVG, ICO, AVIF के लिए असली छवि data URL लौटाता है: फ़ाइल पढ़ता है (4 MiB सीमा), <code>commands::files::base64_encode</code> से encode करता है, <code>PreviewPayload { kind: Image, data_url: &quot;data:image/…;base64,…&quot; }</code> लौटाता है। गैर-छवि एक्सटेंशन अब भी <code>None</code> लौटाते हैं ताकि text-head fallback टेक्स्ट फ़ाइलों को संभाले।","changelog.d2769be53d10":"<code>files_preview</code>, <code>files_thumbnail</code> और <code>icon_for_ext</code> अब <code>async fn</code> हैं और असली काम <code>tokio::task::spawn_blocking</code> को सौंपते हैं। synchronous संस्करण shell-icon निकालने + कई MB के base64 encoding के दौरान Tauri के IPC dispatch थ्रेड को सेकंडों तक रोक देते थे, जिससे पूरा UI जम जाता था।","changelog.2e8adf41da90":"<code>PreviewPane.svelte</code> द्वारा एक गायब <code>files.whitelistUserChosen</code> को कॉल करना ठीक किया — helper <code>ipc/bookmarks.ts</code> में था, पर फलक <code>* as files from &quot;ipc/files&quot;</code> import करता है। <code>whitelistUserChosen</code> को <code>ipc/files.ts</code> से फिर से export किया ताकि कॉल resolve हो; synchronous <code>TypeError</code> के कारण <code>loading = true</code> हमेशा के लिए बना रहता था और पूर्वावलोकन का $effect रुका रहता था।","changelog.932173fca555":"पूर्वावलोकन / आइकन पथों पर Rust tracing जोड़ी, साथ में TS console events को cargo dev log में भेजने के लिए एक <code>log_event</code> Tauri कमांड, और एक <code>std::panic::set_hook</code> जो Rust panics को console में दिखाता है।","changelog.6ef1e2ccf454":"<strong>FTP endpoint + धूसर डिस्कनेक्ट।</strong>","changelog.5b6f4670d959":"नया <code>ConnectEndpointDialog.svelte</code>, voidtools के डायलॉग पर आधारित: होस्ट (आवश्यक), पोर्ट (डिफ़ॉल्ट 21), उपयोगकर्ता नाम, पासवर्ड, लिंक प्रकार ड्रॉपडाउन। ठीक है दबाने पर <code>settings.endpoint = { name: host, kind: &quot;ftp&quot; }</code> लिखता है।","changelog.93d8e6c9ea7d":"जब <code>settings.endpoint.kind === &quot;local&quot;</code> हो, तो <code>MenuBar.isItemEnabled</code>, <code>tools.disconnect_endpoint</code> के लिए <code>false</code> लौटाता है; CSS <code>pointer-events: none</code> के साथ एक धूसर <code>.item.disabled</code> शैली जोड़ता है।","changelog.dc6508212cbc":"<code>View → Filters</code> अब सेटिंग डायलॉग खोलने से पहले <code>indexes.exclude</code> पैनल पहले से चुन देता है (voidtools-Everything की बराबरी)।","changelog.8886320c4765":"<strong>बहिष्करण — टॉगल होने वाले एक्सटेंशन वर्ग + डुप्लिकेट हटाना।</strong>","changelog.66be911445f7":"<code>ExcludePanel.svelte</code> के एक्सटेंशन-वर्ग बटन (वीडियो / ऑडियो / छवि / संग्रह / एक्ज़ीक्यूटेबल) अब टॉगल होते हैं: क्लिक करने पर वर्ग के globs जुड़ते हैं और बटन हाइलाइट होता है; फिर से क्लिक करने पर वे हटते हैं और हाइलाइट हट जाता है। &quot;सक्रिय&quot; की गणना &quot;वर्ग का हर glob इस समय exclude-files सेट में है&quot; के रूप में होती है, ताकि हाइलाइट केवल आख़िरी क्लिक नहीं, बल्कि असली स्थिति दिखाए।","changelog.b4936ee1d7c7":"<code>Add Folder…</code> और <code>Apply OS-recommended excludes</code> दोनों डुप्लिकेट हटाते हैं, ताकि एक ही प्रविष्टि कभी दो बार न जुड़े।","changelog.fd67542ffabe":"<strong>बुकमार्क की विश्वसनीयता।</strong>","changelog.07a8ba50f22e":"<code>bookmarks.add</code> को अब ख़ाली न होने वाली क्वेरी की ज़रूरत नहीं — ख़ाली क्वेरी वाले बुकमार्क की अनुमति है (&quot;बुकमार्क N&quot; नाम से, ताकि उपयोगकर्ता व्यवस्थित करें में उनका नाम बदल सके)। डुप्लिकेट पहचानने की कुंजी अब (नाम, क्वेरी, filter-set) है।","changelog.eccef664591a":"<code>bookmarksStore.hydrate()</code> ~10 s तक हर 500 ms पर फिर से प्रयास करता है, ताकि पृष्ठभूमि-बूट के दौरान डेमन-तैयार-नहीं वाली IPC त्रुटि के कारण पहला hydrate बुकमार्क सूची न खो दे।","changelog.002b1009c89f":"<code>bookmarks.organize</code> व्यवस्थित करें डायलॉग खोलने से पहले फिर से hydrate करता है, ताकि डिस्क पर बुकमार्क होने पर कोई पुराना ड्रॉपडाउन &quot;अभी कोई बुकमार्क नहीं&quot; न दिखा सके।","changelog.c399ec40a64b":"<strong>विविध।</strong>","changelog.0437b05ad147":"<code>tracing_subscriber</code> का डिफ़ॉल्ट फ़िल्टर बढ़ाकर <code>warn,freally=info,freally_ui_lib=info,freally_indexd=info</code> किया गया, ताकि <code>RUST_LOG</code> को बाध्य किए बिना instrumentation दिखे।","changelog.64b28a5c4c3d":"सेटिंग डायलॉग का <code>markDirty</code> अब फ़ॉन्ट और रंग पैनल के पैच पथ के भीतर <code>applyFontsAndColors()</code> भी कॉल करता है, ताकि पूर्वावलोकन तुरंत दिखे।","changelog.1f355d627a40":"<code>ipc/types.ts::QueryHit</code> में <code>attrs?: number</code> जुड़ा; <code>Bookmark</code> में <code>filters?: string[]</code>। आगे की संगतता के लिए दोनों वैकल्पिक हैं।","changelog.3df684c915d5":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 12: सेटिंग डायलॉग + असली डेमन IPC + कस्टम-एक्सट्रैक्टर फ़्रेमवर्क + i18n। चरण-11 की mock IPC परत की जगह प्रति-उपयोगकर्ता Unix socket / named pipe पर असली <code>freally-rpc</code> length-prefixed JSON-RPC transport लाता है, और PRD §8.1-§8.27 का पूरा सेटिंग डायलॉग तथा Wasm-सैंडबॉक्स वाला कस्टम-एक्सट्रैक्टर होस्ट जोड़ता है।","changelog.cbb79fe44d28":"<strong>नया crate <code>freally-rpc</code></strong> (<code>crates/freally-rpc/</code> के अंतर्गत) — वह नींव जिससे Tauri UI और नया <code>freally</code> CLI दोनों एक ही <code>freally-indexd</code> इंस्टेंस से एक ही प्रोटोकॉल में बात करते हैं।","changelog.b4d3e8bb408c":"<code>frame.rs</code>: 16-MiB की कठोर payload सीमा के साथ u32-BE length-prefixed framing, ताकि कोई शत्रुतापूर्ण peer एक अकेले 4-GiB length prefix से सर्वर की मेमोरी ख़त्म (OOM) न कर सके।","changelog.9eee30718562":"<code>jsonrpc.rs</code>: JSON-RPC 2.0 Request / Response / Notification envelopes; <code>ResponseEnvelope</code> untagged enum किसी एक frame को या तो response या सर्वर द्वारा भेजी गई notification के रूप में अलग पहचानता है।","changelog.3cae329c5ea1":"<code>service.rs</code>: <code>Service</code> trait, जिसे <code>freally-indexd</code> लागू करता है; <code>NotificationSink</code> किसी method handler को उसी कनेक्शन पर asynchronous notifications भेजने देता है।","changelog.a60b3df0f5d6":"<code>server.rs</code>: सीमित outbound queue (<code>PER_CONN_OUT_QUEUE = 256</code>) के साथ प्रति-कनेक्शन accept loop; हर कनेक्शन के लिए एक writer task और एक notification fan-in task चलाता है जो <code>Notification</code>s को writer queue पर आगे भेजता है। <code>handle_connection_for_tests</code> सेकंड से कम चलने वाले integration टेस्ट के लिए वही loop body एक <code>tokio::io::duplex</code> पर उपलब्ध कराता है।","changelog.829538dc4efb":"<code>client.rs</code>: प्रति-कॉल oneshot reply channel के साथ typed <code>ClientHandle::call()</code>; <code>notifications()</code> एक tokio broadcast subscription लौटाता है। reader task, EOF पर साफ़ <code>transport closed</code> रूप के साथ प्रतीक्षारत callers को निपटा देता है।","changelog.91eab238f9d7":"<code>transport/unix.rs</code>: <code>UnixListener::accept_authenticated()</code>, <code>tokio::net::UnixStream::peer_cred()</code> से peer credentials पढ़ता है और हर उस peer को अस्वीकार करता है जिसका UID मौजूदा प्रोसेस से मेल नहीं खाता — <code>listen()</code> में सेट 0600 file-mode के साथ मिलकर, इसका अर्थ है कि उसी मशीन का कोई दूसरा उपयोगकर्ता पथ जानते हुए भी कनेक्ट नहीं कर सकता। अतिरिक्त सावधानी के तौर पर parent डायरेक्टरी को chmod 0700 किया जाता है।","changelog.fcfcdf081a40":"<code>transport/windows.rs</code>: <code>D:(A;;GA;;;&lt;userSid&gt;)(A;;GA;;;SY)</code> रूप की SDDL string से बने SECURITY_DESCRIPTOR के साथ <code>ServerOptions::create_with_security_attributes_raw</code> — केवल मौजूदा उपयोगकर्ता (<code>OpenProcessToken</code> + <code>GetTokenInformation(TokenUser)</code> + <code>ConvertSidToStringSidW</code> से resolve) और SYSTEM के पास Access-Allowed ACE है। कोई <code>Everyone</code> नहीं, कोई <code>Authenticated Users</code> नहीं। <code>reject_remote_clients(true)</code> network-pipe पहुँच रोकता है। <code>LocalFree</code> को <code>SdDrop</code> RAII guard में लपेटा गया है, ताकि early-return वाले त्रुटि पथों पर भी security descriptor मुक्त हो।","changelog.336f8a676048":"<code>path.rs</code>: प्रति-OS पारंपरिक डिफ़ॉल्ट socket / pipe पथ। macOS: <code>~/Library/Application Support/freally/indexd.sock</code>। Linux: <code>$XDG_RUNTIME_DIR/freally/indexd.sock</code>, <code>~/.local/share/freally/indexd.sock</code> fallback के साथ। Windows: <code>\\\\.\\pipe\\freally-indexd-&lt;userSid&gt;</code> (SID-चिह्नित, ताकि एक ही Windows होस्ट पर दो उपयोगकर्ताओं को अलग-अलग pipe मिलें)।","changelog.81b6aadfed10":"<code>dto.rs</code>: serde DTOs जो <code>apps/freally-ui/src/lib/ipc/types.ts</code> की बाइट-दर-बाइट प्रतिकृति हैं — वही <code>serde(rename_all = &quot;lowercase&quot;)</code> enum variants, <code>kind</code> JSON-key के लिए वही <code>serde(rename = &quot;type&quot;)</code>, वही फ़ील्ड संरचनाएँ। चरण 12 का parity audit, checked-in fixtures के विरुद्ध बाइट-स्थिर JSON आउटपुट assert करता है।","changelog.022aca1457de":"<strong>नया crate <code>freally-extractor-host</code></strong> (<code>crates/freally-extractor-host/</code> के अंतर्गत) — Wasm-सैंडबॉक्स वाला कस्टम-एक्सट्रैक्टर फ़्रेमवर्क। चरण 12 के trust model के अनुसार डिफ़ॉल्ट रूप से अविश्वसनीय।","changelog.9b6d93374feb":"<code>manifest.rs</code>: TOML स्कीमा जिसमें <code>id</code>, <code>display_name</code>, <code>version</code>, <code>formats: Vec&lt;String&gt;</code>, वैकल्पिक <code>magic: Vec&lt;String&gt;</code> (केवल hex-byte specs, जैसे <code>&quot;0x23 0x20&quot;</code>), <code>sidecar</code> (<code>*.wasm</code> बाइनरी का पथ, जिसके मौजूद होने की जाँच load के समय होती है), <code>time_budget_ms</code> (डिफ़ॉल्ट 1000), <code>memory_budget_mb</code> (डिफ़ॉल्ट 64) हैं। गलत magic specs load के समय अस्वीकार होते हैं।","changelog.bca0da3b05e5":"<code>registry.rs</code>: <code>&lt;index_root&gt;/extractors/</code> स्कैनर जो हर उप-डायरेक्टरी का <code>manifest.toml</code> लोड करता है। <code>registry.toml</code> उपयोगकर्ता की प्रति-एक्सट्रैक्टर trust स्थिति, छेड़छाड़ पकड़ने के लिए blake3 hashes, और एक crash counter दर्ज करता है जो लगातार 3+ बार crash होने वाले एक्सट्रैक्टर को तब तक स्वतः अक्षम रखता है जब तक उपयोगकर्ता उस पर फिर से भरोसा न करे। स्थायी सहेजना <code>toml::to_string_pretty</code> के ज़रिए tmp-rename से होता है। फिर से भरोसा करने पर <code>set_trusted</code> crash counter साफ़ कर देता है।","changelog.b8bcebf716a9":"<code>sandbox.rs</code>: सख़्त गारंटियों वाला <code>wasmtime</code> होस्ट — <code>Config::consume_fuel(true)</code> प्रति-कॉल CPU बजट लागू करता है (<code>fuel = time_budget_ms × 1_000_000</code>); कॉल के बाद <code>Memory::data_size</code> जाँच प्रति-कॉल मेमोरी बजट लागू करती है। guest को केवल दो host functions दिखते हैं: <code>host_log(ptr: i32, len: i32)</code> (debug logging, 4 KiB पर काटी गई) और <code>host_now_ms() -&gt; i64</code> (होस्ट द्वारा दिया गया, अनुरोध के <code>now_ms</code> से मेल खाता, ताकि guest स्वतंत्र रूप से wall time न देख सके)। कोई <code>wasi:sockets</code> नहीं, कोई <code>wasi:filesystem-write</code> नहीं, कोई <code>wasi:clocks</code> नहीं। guest <code>alloc(size) -&gt; i32</code> और <code>extract(ptr, len) -&gt; i64</code> export करता है (ऊपरी 32 बिट = परिणाम pointer, निचले 32 बिट = परिणाम लंबाई)। परिणाम लंबाई पर 16-MiB की सीमा, ताकि कोई शत्रुतापूर्ण sidecar 4-GiB का blob न लौटा सके।","changelog.c9d6d857a602":"<strong><code>freally-indexd</code> का library + binary refactor।</strong> चरण 1-3 की केवल-सेवा वाली बाइनरी अब एक library + पतली shim बन गई है। library <code>DaemonState</code> (साझा state container जिसमें <code>Arc&lt;Index&gt;</code>, <code>Arc&lt;AudioCache&gt;</code>, <code>Pipeline</code>, <code>Registry</code>, और साथ में <code>&lt;index_root&gt;/config/</code> में TOML फ़ाइलों के रूप में सहेजे गए <code>volumes / folders / excludes / network / history</code> configs हैं) और <code>IndexdService</code> (वह <code>Service</code> impl जो PRD §8.30 में गिनाए गए हर method को dispatch करता है) उपलब्ध कराती है। नए modules:","changelog.2d2defa4d194":"<code>service.rs</code>: <code>query.run</code> / <code>query.cancel</code> / <code>query.lens_timings</code> / <code>index.state</code> / <code>index.verify</code> / <code>index.compact</code> / <code>index.rebuild</code> / <code>extractors.list</code> / <code>extractors.set_mode</code> / <code>volumes.list</code> / <code>volumes.update</code> / <code>volumes.recreate_journal</code> / <code>volumes.reset_stream</code> / <code>volumes.upgrade_fanotify</code> / <code>volumes.remove</code> / <code>folders.list</code> / <code>folders.add</code> / <code>folders.remove</code> / <code>folders.update</code> / <code>folders.rescan</code> / <code>folders.rescan_all</code> / <code>excludes.get</code> / <code>excludes.set</code> / <code>network.status</code> / <code>network.start_https</code> / <code>network.stop_https</code> / <code>network.regen_token</code> / <code>network.start_api</code> / <code>network.stop_api</code> / <code>custom_extractors.list</code> / <code>custom_extractors.set_trusted</code> / <code>custom_extractors.refresh_hashes</code> / <code>history.get</code> / <code>history.set</code> / <code>history.clear</code> / <code>preview.text_head</code> / <code>preview.thumbnail</code> / <code>settings.apply</code> / <code>daemon.shutdown</code> के लिए typed dispatch। <code>query.run</code>, <code>query:batch</code> / <code>query:done</code> notifications को क्लाइंट तक stream करता है (Tauri की ओर इन्हें Tauri events के रूप में फिर से भेजा जाता है, जिन्हें Svelte stores उपयोग करते हैं)।","changelog.d58ec7a0cdfb":"<code>state.rs</code>: <code>DaemonState::open(opts)</code> इंडेक्स, ऑडियो कैश, कस्टम-एक्सट्रैक्टर रजिस्ट्री खोलता है, और सहेजी गई config TOMLs पढ़ता है। <code>DaemonState::persist()</code> उन सबको atomic ढंग से वापस लिखता है। <code>VolumesConfig</code>, <code>VolumeOverride</code>, <code>NetworkState</code>, <code>HistoryConfig</code> प्रकार अपने-अपने हिस्से का स्थायी सहेजना सँभालते हैं।","changelog.089d7c21d524":"<code>volumes.rs</code>: cross-OS वॉल्यूम पहचान — Windows <code>GetLogicalDrives</code> + <code>GetVolumeInformationW</code> + <code>GetDiskFreeSpaceExW</code> से गुज़रकर NTFS / ReFS / exFAT / FAT32 पंक्तियाँ देता है; macOS <code>/Volumes</code> + <code>statvfs</code> स्कैन करता है; Linux <code>/proc/mounts</code> (pseudo फ़ाइल सिस्टम छोड़कर) + <code>statvfs</code> पढ़ता है। हर पंक्ति में एक स्थिर <code>id</code> होती है (उदा. <code>win-C</code>, <code>lin-_home</code>, <code>mac-Macintosh_HD</code>), ताकि प्रति-वॉल्यूम overrides round-trip हो सकें।","changelog.60cb08f577a8":"<code>settings.rs</code>: <code>settings.apply</code> IPC के लिए <code>SettingsApply</code> typed payload; डेमन संबंधित state बदलता है और सहेजता है। <code>random_token_fingerprint()</code> वह छोटा, गैर-गोपनीय display fingerprint बनाता है जो नेटवर्क पैनल में दिखता है।","changelog.17b91de7bef9":"<code>history.rs</code>: <code>HistoryUpdate</code> typed payload + डेमन की ओर इतिहास मिटाने के लिए भविष्य के चरण 13 का <code>take_clear</code> hook।","changelog.b566f0999042":"<strong><code>apps/freally-ui/src-tauri</code> अब RPC क्लाइंट है।</strong>","changelog.b3d45fd8ffa1":"<code>commands/canned.rs</code> (चरण-11 का mock dataset) हटा दिया गया। चरण 12 का smoke टेस्ट <code>tests/smoke/phase_12_indexd_client.rs::no_canned_rs_in_tree</code> इस हटाने पर regression जाँच करता है।","changelog.a467ed4a6368":"नया <code>daemon.rs</code>: प्रति-OS डिफ़ॉल्ट socket पथ पर एक in-process <code>freally-indexd</code> बूट करता है (टेस्ट के लिए env override <code>FREALLY_RPC_SOCKET</code>), एक <code>freally-rpc</code> क्लाइंट खोलता है, और एक notification re-emitter task चलाता है जो सर्वर द्वारा भेजी गई हर notification को <code>app.emit(method, payload)</code> से Tauri event में बदलता है। <code>Daemon::call/call_void</code> क्लाइंट को clone करके future को डेमन के tokio runtime पर चलाता है, जिससे वह move/borrow टकराव टल जाता है जो <code>Arc&lt;Daemon&gt;::block_on(async move {…})</code> पैदा करता।","changelog.2b8987c2135e":"<code>commands/query.rs</code>, <code>commands/index_state.rs</code>, <code>commands/extractors.rs</code>, और साथ में नए <code>commands/volumes.rs / folders.rs / excludes.rs / network.rs / custom_extractors.rs / history.rs</code> — हर Tauri कमांड body अब डेमन से होकर जाती है। <code>query_parse</code> एकमात्र in-process अपवाद है — कीस्ट्रोक की गति वाला tokenization डेमन round-trip का ख़र्च नहीं उठा सकता।","changelog.6a7142ad49d6":"<code>commands/files.rs</code> अपना UI-side <code>verify_path</code> known-paths गेट बनाए रखता है, पर <code>files_thumbnail</code> / <code>files_preview</code> अब नए <code>preview</code> module को काम सौंपते हैं, जो OS-native पूर्वावलोकन होस्ट तक dispatch करता है।","changelog.b19dfedad0ec":"<code>commands/settings.rs</code> JSON-आधारित स्थानीय persistence बनाए रखता है और उसमें एक <code>#[serde(flatten)] extras</code> HashMap जुड़ता है, जो typed-scalars सतह को फुलाए बिना चरण-12 के 70+ शीर्ष-स्तरीय फ़ील्ड समेट लेता है; security review के allowlist अनुबंध के लिए <code>ALLOWED_PATCH_KEYS</code> हर नई कुंजी तक फैलता है; <code>phase_12_default_extras()</code> चरण-12 के डिफ़ॉल्ट भरता है ताकि नए इंस्टॉल का <code>settings.json</code> हर फ़ील्ड के साथ आए। <code>lib/ipc/types.ts</code> का TS अनुबंध अपरिवर्तित है।","changelog.1469ccfaba03":"<strong>OS-native पूर्वावलोकन होस्ट</strong> (<code>apps/freally-ui/src-tauri/src/preview/</code>)। प्लेटफ़ॉर्म module संरचना तैयार है; हर होस्ट का पूर्ण एकीकरण UX-गुणवत्ता सुधार के रूप में क्रमशः चालू होता है, जो data-URL अनुबंध नहीं बदलता।","changelog.b4df5b094937":"<code>preview/macos.rs</code> — QuickLook bridge (पूर्ण पूर्वावलोकन के लिए <code>QLPreviewPanel</code>, थंबनेल के लिए <code>QLThumbnailGenerator</code>)। चरण 12 module सतह और runtime probe शिप करता है; पूरा <code>objc2</code> कॉल क्रम परिष्कार दौर के सुधार के रूप में आएगा।","changelog.7c608576f7b1":"<code>preview/windows_host.rs</code> — Shell preview handlers (windows-rs के ज़रिए <code>IPreviewHandler</code> + <code>IThumbnailProvider</code>)। वही रुख़ — सतह तैयार है, COM bridge क्रमशः शिप होता है।","changelog.2350b7e13cc7":"<code>preview/linux.rs</code> — मौजूद होने पर DBus के ज़रिए GNOME Sushi, मौजूद होने पर subprocess shell-out के ज़रिए KDE KIO। पहचान <code>OnceLock</code> में कैश किया गया <code>gdbus introspect</code> / <code>kioclient5 --version</code> probe है, इसलिए पहली कॉल के बाद प्रति-पूर्वावलोकन लागत शून्य है।","changelog.94e452c9cf02":"<code>preview/fallback.rs</code> — कम प्रचलित Unix के लिए fallback। हमेशा None लौटाता है, ताकि caller सार्वभौमिक text-head + typed-icon पथ पर आ जाए।","changelog.3c9eec3f6c4b":"<code>preview/mod.rs</code> — होस्ट dispatch + <code>text_head_fallback</code> (4 KiB तक पढ़ता है, और टेक्स्ट तभी मानता है जब कोई NUL बाइट न हो और replacement-char अनुपात ≤ 1% हो)।","changelog.67698e29fe12":"<strong>सेटिंग डायलॉग</strong> (<code>apps/freally-ui/src/components/settings/</code>) — PRD §8.2-§8.27 का हर नियंत्रण, बिना किसी stub के, जुड़ा हुआ।","changelog.a3361a51edd5":"<code>SettingsDialog.svelte</code>: आकार बदलने योग्य modal (न्यूनतम 800×620, डिफ़ॉल्ट 960×720), बायाँ tree-nav + दायाँ विवरण फलक + नीचे बटन पट्टी वाला लेआउट। आख़िरी चुना गया नोड + प्रति-फलक स्क्रॉल स्थिति localStorage में सहेजता है, ताकि डायलॉग फिर से खोलने पर उपयोगकर्ता उसी पैनल पर लौटे जिसमें वह आख़िरी बार था।","changelog.24b28d6fc11f":"<code>SettingsTreeNav.svelte</code>: PRD §8.1.1 का पूरा ट्री (सामान्य / इतिहास / अनुक्रमणिकाएँ / लेंस / नेटवर्क / गोपनीयता और अपडेट / लॉग और डिबग / बैकअप, निर्यात, रीसेट / लोकेल / परिचय)। विकल्प खोजने वाला बॉक्स नोड्स को लेबल और प्रति-नोड कीवर्ड सेट से फ़िल्टर करता है। असहेजे बदलाव वाले पैनलों पर बैंगनी <code>•</code> लगता है, ताकि उपयोगकर्ता देख सके कि किनमें असहेजे परिवर्तन हैं।","changelog.4f8f836e7ec7":"<code>SettingsButtonBar.svelte</code>: डिफ़ॉल्ट पुनर्स्थापित करें (बाएँ, प्रति-पैनल), ठीक है / रद्द करें / लागू करें (दाएँ)। लागू करें केवल तब सक्षम होता है जब <code>settingsDialog.dirty</code> हो; ठीक है लागू करके बंद करता है; रद्द करें <code>SettingsDialogModel.cancel()</code> से वापस ले जाता है (डायलॉग खुलने पर हर store का <code>snapshot()</code> लिया जाता है, <code>rollback()</code> उसे पुनर्स्थापित करता है); डिफ़ॉल्ट पुनर्स्थापित करें <code>SettingsDialogModel.resetPanel(panelId)</code> से सक्रिय पैनल को रीसेट करता है।","changelog.57b1a742578b":"26 पैनल कंपोनेंट, PRD §8.2-§8.27 के हर अनुभाग के लिए एक। मुख्य बातें:","changelog.66c58219af20":"<strong>सामान्य → UI</strong>: थीम चुनने वाला (लाइव बदलता है), ट्रे टॉगल, सिंगल-क्लिक के रूप, पंक्ति घनत्व, एनिमेटेड क्रॉस-फ़ेड।","changelog.cfe484eb7c32":"<strong>सामान्य → होम</strong>: हर मिलान डिफ़ॉल्ट के लिए अंतिम मान उपयोग करें | चालू | बंद वाले त्रिक; फ़िल्टर / क्रम / दृश्य / अनुक्रमणिका स्रोत ड्रॉपडाउन; डिफ़ॉल्ट लेंस दृश्यता + प्रति-लेंस परिणाम सीमाएँ।","changelog.434f9ca58ddb":"<strong>सामान्य → खोज</strong>: voidtools-Everything DSL के व्यवहार का हर टॉगल, और साथ में Freally की अतिरिक्त सुविधाएँ (strict-Everything मोड, auto-regex, मॉडिफ़ायर पूर्णता, होवर पर पार्स-ट्री)।","changelog.1d3e0b8951a4":"<strong>सामान्य → परिणाम</strong>: हर व्यवहार + लोड-प्राथमिकता ड्रॉपडाउन + लेंस अनुसार समूहीकरण।","changelog.66559820d7a5":"<strong>सामान्य → दृश्य</strong>: हर (E) प्रदर्शन टॉगल + Freally के ऑडियो/समानता बैज + पूर्वावलोकन-फलक की स्थिति।","changelog.abfacc1cecb2":"<strong>सामान्य → संदर्भ मेनू</strong>: सभी 10 प्रविष्टियों के लिए प्रति-कमांड दिखाएँ / केवल Shift दबाए रखने पर दिखाएँ / छिपाएँ + macro स्ट्रिंग।","changelog.bcfbad5112f2":"<strong>सामान्य → फ़ॉन्ट और रंग</strong>: सभी 8 आइटम स्थितियों के लिए फ़ॉन्ट + आकार + प्रति-स्थिति अग्रभूमि/पृष्ठभूमि रंग (<code>&lt;input type=&quot;color&quot;&gt;</code> के साथ) + बोल्ड + इटैलिक + प्रति-लेंस एक्सेंट + थीम-विरासत टॉगल।","changelog.e1ece0afb46b":"<strong>सामान्य → कीबोर्ड</strong>: ग्लोबल हॉटकी + प्रति-विंडो हॉटकी + chord रजिस्ट्री (कमांड+binding जोड़ियों के लिए जोड़ें/हटाएँ पंक्तियाँ)।","changelog.3ae2a3be31d0":"<strong>इतिहास</strong>: खोज/रन इतिहास टॉगल + प्रतिधारण के दिन + अभी साफ़ करें बटन + गोपनीयता मोड + प्रति-लेंस इतिहास टॉगल।","changelog.04aa58c3b95c":"<strong>अनुक्रमणिकाएँ (शीर्ष-स्तर)</strong>: Everything के पूरे-इंडेक्स वाले हर फ़ील्ड का टॉगल + पुनर्निर्माण के लिए बाध्य करें / संहत करें / सत्यापित करें बटन (toast प्रतिक्रिया के साथ असली डेमन ऑपरेशन)।","changelog.9c0402a55809":"<strong>अनुक्रमणिकाएँ → वॉल्यूम</strong>: FS बैज (NTFS / ReFS / exFAT / FAT32 / APFS / HFS+ / ext4 / Btrfs / ZFS / XFS / F2FS) + स्थिति संकेतक के साथ cross-platform वॉल्यूम पहचान; प्रति-वॉल्यूम अनुक्रमणिका में शामिल करें / केवल शामिल करें / journal सदस्यता सक्षम करें (लेबल OS के अनुसार बदलता है — USN / FSEvents / inotify) / बफ़र / आवंटन डेल्टा (केवल NTFS) / हाल के परिवर्तन लोड करें / परिवर्तनों की निगरानी करें; प्रति-OS बटन (NTFS पर journal पुनः बनाएँ, APFS पर स्ट्रीम रीसेट करें, Linux पर fanotify में अपग्रेड करें); हटाएँ बटन।","changelog.a85227577e86":"<strong>अनुक्रमणिकाएँ → फ़ोल्डर</strong>: OS फ़ोल्डर पिकर से जोड़ें + प्रति-फ़ोल्डर निगरानी टॉगल + बफ़र + पुनः स्कैन अनुसूची (निर्धारित समय पर / हर N घंटे / कभी नहीं) + अभी पुनः स्कैन करें / सभी को अभी पुनः स्कैन करें बटन।","changelog.7a5ae0347c10":"<strong>अनुक्रमणिकाएँ → फ़ाइल सूचियाँ</strong>: पिकर से फ़ाइल सूची जोड़ें + प्रारूप ड्रॉपडाउन (टेक्स्ट / JSON / .srcb) + सहेजी गई खोजों के स्वतः-निर्यात का टॉगल + फ़ाइल सूची संपादक बटन।","changelog.e20f4ec8774d":"<strong>अनुक्रमणिकाएँ → बहिष्कृत करें</strong>: फ़ोल्डर सूची + globs + OS-अनुशंसित लागू करें (Win / Mac / Linux के प्रति-OS पारंपरिक बहिष्करण) + वर्ग अनुसार बहिष्करण चिप (वीडियो / ऑडियो / छवि / संग्रह / एक्ज़ीक्यूटेबल)।","changelog.8fd5ecb1f212":"<strong>लेंस → फ़ाइल नाम</strong>: ट्राइग्राम तीव्रता + प्रत्यय-सरणी मेमोरी बजट + वाइल्डकार्ड विस्तार सीमा + regex टाइमआउट।","changelog.38b4c6105b69":"<strong>लेंस → सामग्री</strong>: सक्षम करें + 11 प्रारूपों के लिए प्रति-प्रारूप मोड + बजट + स्निपेट लंबाई + स्टॉप-वर्ड भाषा (18 शिप-लोकेल) + सेटिंग बदलने पर पुनः निकालें + blob चेकसम सत्यापित करें।","changelog.299de69339e8":"<strong>लेंस → ऑडियो</strong>: सक्षम करें + 10 प्रारूपों के लिए प्रति-प्रारूप मोड + LUFS संदर्भ मानक + पीक गणना + मौन सीमा + संशोधन पर पुनः निकालें।","changelog.9b9db5aea8be":"<strong>लेंस → समानता</strong>: सक्षम करें + हस्ताक्षर आकार (64/128/256) + बैंड (8/16/32) + रिकॉल सीमा + परिणाम सीमा।","changelog.98316029b6fa":"<strong>लेंस → कस्टम</strong>: trust टॉगल के साथ समुदाय-एक्सट्रैक्टर रजिस्ट्री + blake3 hash प्रदर्शन + सैंडबॉक्स-अनुमति दृश्य + हैश ताज़ा करें।","changelog.b244fd575e99":"<strong>नेटवर्क → HTTPS सर्वर</strong>: शुरू/बंद + bind/पोर्ट/force-https/legacy-auth + टोकन पुनर्जनन (fingerprint लाइव बदलता है)।","changelog.2b5f33d631fe":"<strong>नेटवर्क → ETP/FTP API</strong>: शुरू/बंद + पोर्ट + लीगेसी सादा FTP/ETP टॉगल।","changelog.acd0f3e9e295":"<strong>गोपनीयता और अपडेट</strong>: स्वतः-अपडेट आवृत्ति + प्री-रिलीज़ टॉगल + hard-coded, केवल-पठन नेटवर्क कॉल नीति।","changelog.a7f925aabcc4":"<strong>लॉग और डिबग</strong>: लॉग स्तर (tracing फ़िल्टर लाइव बदलता है) + प्रतिधारण + लॉग फ़ोल्डर खोलें (<code>tauri-plugin-opener</code> के ज़रिए) + डायग्नोस्टिक्स बंडल निर्यात करें।","changelog.71e2554230fe":"<strong>बैकअप, निर्यात, रीसेट</strong>: सेटिंग निर्यात / आयात करें (<code>tauri-plugin-fs</code> के ज़रिए TOML round-trip) + बुकमार्क बंडल निर्यात / आयात करें (.srcb) + सब रीसेट करें (पुष्टि के साथ)।","changelog.af4a3d364535":"<strong>लोकेल</strong>: 18 शिप-लोकेल का ड्रॉपडाउन — <strong>अंग्रेज़ी सबसे ऊपर स्थिर</strong>, फिर मूल नाम के अनुसार वर्णानुक्रम (Latin → Cyrillic → RTL → अन्य लिपियाँ, इस समूहीकरण में); हर लेबल भाषा का अपना स्व-नाम है, ताकि UI किसी ऐसी लिपि में हो जिसे उपयोगकर्ता पढ़ नहीं सकता, तब भी वह अपनी भाषा चुन सके; <code>applyRtlForLocale()</code> से लाइव RTL बदलाव (लोकेल अरबी हो या RTL पूर्वावलोकन चालू हो, तो <code>document.documentElement</code> पर <code>dir=&quot;rtl&quot;</code> और <code>lang</code> सेट करता है); तिथि / संख्या प्रारूप (OS / ISO / RFC / कस्टम)।","changelog.34eea5e6fc14":"<strong>परिचय</strong>: संस्करण + commit + OS पहचान + लाइसेंस + voidtools का श्रेय + ओपन-सोर्स सूचनाएँ।","changelog.5db29baba331":"SettingsDialogModel (<code>lib/stores/settings_dialog.svelte.ts</code>) — dirty-state मशीन। प्रति-पैनल dirty चिह्न ट्रैक करता है; डायलॉग खुलने पर हर store का snapshot लेता है; <code>apply()</code> एक ही बार में हर store का <code>flush()</code> चलाता है; <code>rollback()</code> snapshots पुनर्स्थापित करता है; <code>resetPanel(id)</code> केवल उस पैनल की अपनी कुंजियाँ वापस करता है। <code>PANEL_KEYS</code> सटीक रीसेट के लिए हर PanelId को उसकी अपनी SettingsState कुंजियों से जोड़ता है।","changelog.7d9367a4db32":"<code>lib/stores/</code> के अंतर्गत डेमन से होकर जाने वाले 6 नए stores: <code>volumes / folders / excludes / network / custom_extractors / history</code>। हर एक में <code>hydrate()</code> (डायलॉग खुलने पर कॉल होता है), <code>snapshot()</code> / <code>rollback()</code>, <code>flush()</code>, <code>reset()</code> हैं।","changelog.f76dd7e6a086":"<strong>CLI बाइनरी <code>freally</code></strong> (<code>crates/freally-cli</code>) उसी <code>freally-rpc</code> transport का दूसरा क्लाइंट बन जाती है — वही socket पथ, वही प्रमाणीकरण रुख़। Subcommands: <code>search &quot;&lt;query&gt;&quot;</code> (<code>--strict-everything</code> और <code>--parse-only</code> फ़्लैग के साथ); <code>index status / verify / compact / rebuild / pause / resume / add-root &lt;path&gt; / rm-root &lt;path&gt;</code>; <code>bookmark save / list / delete</code> (UI-side state — जब तक चरण 13 बुकमार्क को डेमन transport पर नहीं ले जाता, तब तक साफ़ &quot;चल रहे ऐप द्वारा प्रबंधित&quot; संदेश दिखाता है); <code>theme system | light | dark</code>। <code>search</code> subcommand पहले notifications की सदस्यता लेता है ताकि शुरुआती <code>query:batch</code> events न छूटें, hits आते ही उन्हें लेंस-अनुसार समूह में छापता है, और <code>query:done</code> पर अंतिम लेंस समय छापता है।","changelog.af56538d34af":"<strong>i18n।</strong> सभी 18 <code>.ftl</code> फ़ाइलें चरण 12 की सेटिंग-डायलॉग कुंजियों से विस्तारित (प्रति लोकेल ~250 कुंजियाँ, प्रति फ़ाइल ~14 KiB)। भाषाएँ: en / ar / de / es / fr / hi / id / it / ja / ko / nl / pl / pt-BR / ru / tr / uk / vi / zh-CN। हर लोकेल अपनी मूल भाषा में पूरी तरह अनूदित है (कोई MT-ड्राफ़्ट शिप नहीं होता)। RTL अरबी का लेआउट <code>lib/bootstrap.ts</code> के लाइव <code>applyRtlForLocale()</code> बदलाव और <strong>लोकेल → RTL पूर्वावलोकन</strong> टॉगल से टेस्ट किया जाता है। मूल-नाम वाले स्व-लेबल combobox की बदौलत, ऐसी लिपि में फँसा उपयोगकर्ता भी जिसे वह पढ़ नहीं सकता, अपनी भाषा चुन सकता है।","changelog.3cd9ef6d9858":"<strong>Smoke टेस्ट</strong> (<code>tests/smoke/phase_12_*</code>, और साथ में <code>crates/freally-rpc/tests</code>, <code>crates/freally-indexd/tests</code>, <code>crates/freally-extractor-host/tests</code> के अंतर्गत प्रति-crate re-exports):","changelog.233c2ff71ae3":"<code>phase_12_rpc_transport.rs</code> — असली UDS (Unix) / named pipe (Windows) पर round-trip; socket फ़ाइल पर 0600 file-mode assertion; साफ़-EOF व्यवहार; बहुत बड़े frame की अस्वीकृति।","changelog.037808959a87":"<code>phase_12_indexd_client.rs</code> — <code>query.run</code> batches stream करता है और <code>query:done</code> भेजता है; <code>index.state</code> एक typed view लौटाता है; <code>extractors.list</code> + <code>extractors.set_mode</code> round-trip; <code>excludes.get</code> / <code>excludes.set</code> round-trip; <code>no_canned_rs_in_tree</code> regression गेट, जो <code>canned.rs</code> के फिर से आने पर बिल्ड विफल कर देता है।","changelog.c5cfbc1b43d4":"<code>phase_12_settings.rs</code> — चरण-12 की <code>SettingsState</code> संरचना के लिए fixture-आधारित JSON round-trip; <code>extras</code> flatten अज्ञात कुंजियों को बनाए रखता है।","changelog.3f571f0f5d1b":"<code>phase_12_custom_extractor.rs</code> — manifest डिफ़ॉल्ट; trust round-trip; crash counter तीन पर अक्षम करता है; गलत manifest को छोड़ना; host engine init।","changelog.3dbbc40cea55":"<code>phase_12_theme_switch.rs</code> — <code>settings.apply</code> से होकर थीम-चयन का JSON round-trip।","changelog.972927dbd83f":"<code>phase_12_preview_hosts.rs</code> — सार्वभौमिक text-head fallback वर्गीकरण + typed-icon SVG रंग तालिका।","changelog.a578a3241000":"<code>phase_12_volumes.{ps1,sh}</code> — प्रति-OS shell scripts जो <code>cargo test -p freally-indexd --test phase_12_indexd_client</code> चलाते हैं (वॉल्यूम-पहचान के invariants indexd crate के unit टेस्ट में हैं; shell smoke टेस्ट cross-OS गेट हैं)।","changelog.c7b0c19f8b54":"<strong>Build-Guide से विचलन</strong> (एक): prompt में माँगा गया था कि OS-native पूर्वावलोकन होस्ट (QuickLook / Shell / Sushi+KIO) चरण 12 में <em>पूरी तरह जुड़े</em> हों। cross-platform module संरचना + सार्वभौमिक fallback इस चरण में शिप होते हैं; प्रति-OS COM/objc2/DBus एकीकरण, data-URL अनुबंध या Tauri-कमांड सतह बदले बिना, सुविधा-सुधारों के रूप में आएँगे। <code>preview</code> module सतह तैयार है, इसलिए यह बदलाव स्थानीय रहेगा।","changelog.409ff5baabf9":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 11 खोज UI — जादुई क्षण (<code>apps/freally-ui</code>)। <code>src-tauri/src/commands/</code> में एक <em>mock</em> IPC backend के ऊपर Tauri 2 + Svelte 5 + TypeScript + Tailwind CSS डेस्कटॉप ऐप। असली backend से बात करने वाला एकमात्र कमांड <code>query_parse</code> है, जो सीधे <code>freally-query::parse_to_report</code> तक जाता है, ताकि search bar का लाइव tokenization production पार्सर से हूबहू मेल खाए। चरण 12 (TASK-086a/b/c), <code>lib/ipc/types.ts</code> का TS type अनुबंध बदले बिना, mock परत की जगह असली <code>freally-indexd</code> RPC transport लाता है।","changelog.8c8596283703":"<strong>UI सतह (PRD §8.28 + §8.29 + §9):</strong> SearchBar — <code>query.parse</code> IPC से लाइव tokenization + token प्रकार के अनुसार रंगे गए mirror-layer span की रेंडरिंग + पहली त्रुटि span से जुड़ा इनलाइन parse-error pill (Esc साफ़ करता है); लेंस-अनुसार समूहित परिणाम (फ़ाइल नाम / सामग्री / ऑडियो / समानता), संक्षिप्त किए जा सकने वाले अनुभागों, प्रति-लेंस समय बैज, और <code>View → Lenses</code> से लेंस-दृश्यता टॉगल के साथ; बहु-कॉलम परिणाम (नाम | पथ | आकार | संशोधित | प्रकार | एक्सटेंशन), कॉलम ग्रिप पर pointer-capture drag से आकार बदलने, क्लिक से सॉर्ट टॉगल (आरोही / अवरोही चक्र), <code>settings.column_profiles[active]</code> में सहेजी गई कॉलम प्रोफ़ाइल, और पंक्ति घनत्व सघन (32 px) / आरामदायक (44 px) टॉगल के साथ; पंक्ति क्रियाएँ (Enter खोलें / Ctrl+Enter फ़ोल्डर में दिखाएँ / Shift+Enter पथ कॉपी करें / Ctrl+C नाम कॉपी करें / Del पुष्टि+हटाएँ; Ctrl+click चयन टॉगल करता है); पहले चयनित <code>file_id</code> से बँधा पूर्वावलोकन फलक (<code>files_preview</code> IPC से text head रेंडर करता है, छवि data-URLs समर्थित, बाइनरी के लिए &quot;Unsupported&quot; दिखाता है — OS-native पूर्वावलोकन होस्ट चरण 12 में जुड़ेंगे); थंबनेल कॉलम (<code>ThumbnailCell</code> प्रति एक्सटेंशन mock रंगीन SVG वर्गों के साथ <code>files_thumbnail</code> IPC कॉल करता है); मेनू बार में BookmarksDropdown, जो <code>bookmarks_list</code> से भरता है (OS app-data dir के अंतर्गत असली JSON-आधारित persistence) + नाम बदलने और हटाने वाला OrganizeBookmarksDialog (Ctrl+D जोड़ता है, Ctrl+Shift+B व्यवस्थित करें खोलता है); 7 चिप वाला QuickFiltersPalette (ऑडियो / वीडियो / छवि / दस्तावेज़ / एक्ज़ीक्यूटेबल / संग्रह / फ़ोल्डर), जो मेल खाता token टॉगल करता है; <code>tauri-plugin-global-shortcut</code> से ग्लोबल हॉटकी (macOS पर डिफ़ॉल्ट Alt+Space, Win/Linux पर Super+Space) — दबाने पर विंडो सामने आती है + खोज इनपुट पर फ़ोकस होता है; <code>tauri-plugin-deep-link</code> से <code>freally://search?q=…</code> URL प्रोटोकॉल; प्रथम-रन विज़ार्ड (4 चरण: रूट / हॉटकी / लोकेल / थीम), जो <code>settings.first_run_complete</code> पर निर्भर है; थीम सिस्टम (PRD §9) — <code>&lt;html data-theme&gt;</code> attribute के ज़रिए <code>system</code> / <code>light</code> / <code>dark</code> त्रि-अवस्था, tokens हर रंग को CSS custom properties (<code>tokens.{dark,light,shared}.css</code>) से चलाते हैं, <code>prefers-reduced-motion</code> का सम्मान करने वाला 100 ms क्रॉस-फ़ेड, <code>system</code> मोड में <code>prefers-color-scheme</code> listener लाइव बदलता है, Tailwind config utilities को <code>var(--…)</code> से जोड़ता है।","changelog.ab4ea4f7502a":"<strong>मुख्य मेनू बार (PRD §8.28)</strong> — फ़ाइल / संपादन / दृश्य / खोज / बुकमार्क / उपकरण / सहायता में Everything के समकक्ष पूरे मेनू, सभी सबमेनू + उप-आइटम + कीबोर्ड accelerators + Freally की अतिरिक्त चीज़ों के साथ (दृश्य → थीम सबमेनू, दृश्य → लेंस सबमेनू, उपकरण → अनुक्रमणिका अनुरक्षण ▶ सत्यापित करें / संहत करें / पुनर्निर्माण के लिए बाध्य करें, उपकरण → कस्टम एक्सट्रैक्टर प्रबंधक, सहायता → ऑडियो / समानता मॉडिफ़ायर संदर्भ, सहायता → प्रायोजन / दान करें)। प्रति-OS स्थान: macOS ग्लोबल मेनू बार के लिए <code>tauri::menu::MenuBuilder</code> उपयोग करता है (macOS के लिए आवश्यक <code>Freally →</code> ऐप मेनू के साथ, जिसमें परिचय / प्राथमिकताएँ / बाहर निकलें हैं); Win/Linux विंडो के भीतर एक <code>MenuBar.svelte</code> रेंडर करते हैं, जो उसी CommandId सेट के ज़रिए वही declarative spec उपयोग करता है। macOS नेटिव मेनू के क्लिक events <code>menu-command</code> भेजते हैं; UI का <code>bootstrap.ts</code> उन्हें सुनता है और in-process command registry से dispatch करता है — दोनों रेंडरिंग पथों के लिए सच्चाई का एक ही स्रोत। Hover events <code>MenuHoverEvent</code> → स्थिति-बार संकेत खंड भेजते हैं। Hover संकेत Everything की स्ट्रिंग से हूबहू मेल खाते हैं (&quot;Freally के साथ काम करने के कमांड शामिल हैं।&quot;, &quot;परिणाम सूची क्रमबद्ध करने के कमांड शामिल हैं।&quot;, आदि), और साथ में Freally की अतिरिक्त स्ट्रिंग (&quot;सिस्टम, हल्की या गहरी थीम के बीच बदलें।&quot;, &quot;परिणाम सूची में प्रत्येक लेंस की दृश्यता टॉगल करें।&quot;, &quot;Wasm-सैंडबॉक्स कस्टम एक्सट्रैक्टर प्रबंधित करें।&quot;, &quot;अनुक्रमणिका अनुरक्षण उपकरण।&quot;)।","changelog.d29275561d2e":"<strong>स्थिति बार (PRD §8.29)</strong> — <code>View → Status Bar</code> से टॉगल किया जा सकता है। बाएँ → दाएँ सात डिफ़ॉल्ट खंड: इंडेक्सिंग संकेतक (अनुक्रमित / अनुक्रमण हो रहा है N/M / रोका गया / त्रुटि), होवर पर हॉटकी दिखाने के साथ; परिणाम संख्या + चयन संख्या; चयन आकार (<code>show_size_in_status_bar</code> पर निर्भर); सक्रिय क्वेरी का समय; प्रति-लेंस विलंब (<code>show_timing_badges</code> पर निर्भर); endpoint संकेतक (स्थानीय DB / API: \\&lt;name\\&gt;); मेनू hover store से जुड़ा hover-संकेत क्षेत्र, जिसका निष्क्रिय टेक्स्ट <code>Ready · {indexed} indexed</code> है। Freally की विशिष्ट अतिरिक्त चीज़ें: सबसे दाईं ओर थीम संकेतक (सूरज / चाँद आइकन, सिंगल-क्लिक 3 स्थितियों में घुमाता है); इंडेक्सिंग संकेतक का होवर-पर-हॉटकी PRD §8.29 के दो (+) जोड़ों में से एक है।","changelog.5bcf148b5b86":"<strong>Command registry + कीबोर्ड शॉर्टकट:</strong> <code>lib/commands/ids.ts</code> में compile-time पर सम्पूर्ण <code>CommandId</code> string-union है, जो ~95 मेनू आइटम कवर करता है; <code>isCommandId</code> वह closed-set जाँच है जिससे <code>bootstrap.ts</code> macOS नेटिव मेनू से आए <code>menu-command</code> event payloads को सत्यापित करता है (विकृत payloads अस्वीकार करता है)। <code>lib/commands/registry.ts</code> एक <code>Map&lt;CommandId, CommandHandler&gt;</code> से dispatch करता है — स्टार्टअप पर हर CommandId का एक पंजीकृत handler होता है; कोई गायब हो तो bootstrap पथ <code>console.warn</code> भेजता है। <code>lib/commands/menu_spec.ts</code> (TS) + <code>src-tauri/src/menu_spec.rs</code> (Rust) — दोनों renderers द्वारा उपयोग किए जाने वाले declarative मेनू ट्री, जिन्हें parity टेस्ट <code>tests/menubar_parity.rs::rust_spec_covers_every_command_id</code> + <code>does_not_introduce_unknown_command_ids</code> lockstep में रखता है (बिल्ड-समय का codegen कदम दायरे के लिहाज़ से घाटे का सौदा होता; parity टेस्ट ही regression गेट है)। <code>lib/commands/shortcuts.ts</code> OS को समझता है — runtime पर <code>isMac()</code> से <code>mod</code> macOS पर ⌘ और Win/Linux पर Ctrl बनता है। इस चरण में जुड़े असली handlers: zoom (root font-size), विंडो आकार (Tauri <code>WebviewWindow::setSize</code>), sort (<code>sortStore</code> फ़ील्ड + order स्थिति), on-top (<code>set_always_on_top</code>), thumbs/details (row_density), theme (theme + settings round-trip), लेंस दृश्यता, refresh (क्वेरी फिर से चलाएँ), preview/status_bar टॉगल, file.close / file.exit (विंडो बंद), tools.options (सेटिंग placeholder डायलॉग), tools.verify/compact/rebuild_index (असली IPC), help.\\* (opener plugin से URL खोलें), help.about (परिचय डायलॉग), bookmarks.add/organize (store + डायलॉग), quick-filter command IDs (token आगे जोड़ें + फिर से चलाएँ), edit.cut/copy/paste/select_all/invert_selection, edit.advanced.copy_full_name/path/filename/as_json/with_metadata/as_bundle_ref। बाकी placeholder handlers (file.new_window / file.open_file_list / file.export_results / view.go_to / search.advanced / search.add_to_filters / search.organize_filters / खोज के match-टॉगल / tools.file_list_editor / edit.copy_to_folder/move_to_folder) कोड में स्पष्ट रूप से <code>Phase 12</code> चिह्नित हैं — वे असली डेमन IPC या पूरे सेटिंग डायलॉग की प्रतीक्षा में हैं, और दोनों चरण-12 के दायरे में हैं।","changelog.a2506592845e":"<strong>Rust mock IPC backend</strong> (<code>apps/freally-ui/src-tauri/src/commands/</code>): <code>query.rs</code>, <code>query_parse</code> को असली <code>freally-query::parse_to_report</code> से होकर भेजता है (चरण 10 की सतह, असली); <code>query_run</code> / <code>query_cancel</code> / <code>query_lens_timings</code> / <code>query_fetch_batches</code> चारों लेंसों में नियतात्मक (deterministic), पहले से तय batches बनाते हैं, कृत्रिम पर सही संरचना वाले LensTimings के साथ (8 ms फ़ाइल नाम / 22 ms सामग्री / 5 ms ऑडियो / 11 ms समानता / 14 ms कुल)। <code>canned.rs</code> हर क्वेरी पर चारों लेंसों में 12 / 8 / 4 / 6 hits गढ़ता है (नियतात्मक, ताकि smoke टेस्ट आउटपुट को पक्का कर सकें; 5 234 123 फ़ाइलों का स्थिर indexed-total इंडेक्सिंग संकेतक का निष्क्रिय टेक्स्ट दिखाता है)। <code>index_state.rs</code> 4 सेकंड की warm-up अवधि में <code>Indexing N/total</code> से <code>Indexed (total)</code> पर स्थिर होता है। <code>bookmarks.rs</code>, <code>app.path().app_data_dir()</code> (Tauri द्वारा जाँचा गया रूट) के अंतर्गत असली JSON-आधारित persistence शिप करता है। <code>extractors.rs</code> में चरण 7–9 के सात एक्सट्रैक्टरों की पहले से तय रजिस्ट्री है, प्रति-एक्सट्रैक्टर <code>ExtractorMode</code> (eager / lazy / disabled) के साथ। <code>settings.rs</code> JSON-आधारित है, <code>serde_json::to_value</code> + typed re-deserialize से होकर deep-merge <code>settings_set(patch)</code> round-trip के साथ; <code>settings_reset</code> डिफ़ॉल्ट पुनर्स्थापित करता है; स्कीमा थीम / लोकेल / स्थिति-बार टॉगल / timing-badge टॉगल / पूर्वावलोकन / पंक्ति घनत्व / कॉलम प्रोफ़ाइल / लेंस दृश्यता / हॉटकी / endpoint / first-run फ़्लैग / गोपनीयता मोड कवर करता है। <code>files.rs</code> असली OS open/reveal handlers के लिए <code>tauri-plugin-opener</code>, copy_path / copy_name के लिए <code>tauri-plugin-clipboard-manager</code>, हटाने के लिए (UI पुष्टि के बाद) <code>std::fs::remove_file</code>, थंबनेल के लिए रंगीन SVG data-URL (mock), और पूर्वावलोकन के लिए text head या <code>Unsupported</code> (mock) उपयोग करता है।","changelog.7d2b902ad7ff":"<strong>नेटिव एकीकरण:</strong> <code>native_menu.rs</code>, <code>menu_spec.rs</code> से पुनरावर्ती रूप से एक <code>tauri::menu::Menu</code> बनाता है और macOS पर <code>app.set_menu(...)</code> से उसे ऐप मेनू के रूप में सेट करता है (macOS के लिए आवश्यक <code>Freally →</code> ऐप मेनू में सही HIG accelerators के साथ परिचय / प्राथमिकताएँ / बाहर निकलें हैं)। <code>hotkey.rs</code>, <code>tauri-plugin-global-shortcut</code> से डिफ़ॉल्ट chord पंजीकृत करता है (macOS पर Alt+Space, Win/Linux पर Super+Space); दबाने पर मुख्य विंडो दिखाता है + उस पर फ़ोकस करता है और <code>hotkey:fired</code> भेजता है ताकि UI खोज इनपुट पर फ़ोकस करे; टकराव होने पर <code>warn</code> लॉग बनता है (उपयोगकर्ता चरण 12 की सेटिंग में chord बदल सकता है)। <code>url_protocol.rs</code>, <code>tauri-plugin-deep-link</code> से <code>freally://</code> स्कीम पंजीकृत करता है और आने वाले URL के लिए <code>url:opened</code> भेजता है; UI का listener <code>new URL(...)</code> से पार्स करता है और केवल <code>?q=</code> रूप पर ही कार्रवाई करता है।","changelog.dfae438bb9e9":"<strong>i18n</strong> (स्थायी नियम (Standing Rule) #4): इनलाइन en bundle (चरण 12 सभी 18 लोकेल के लिए <code>locales/&lt;code&gt;/freally.ftl</code> के विरुद्ध पूरा Fluent loader जोड़ता है)। सभी 18 <code>.ftl</code> फ़ाइलें चरण 11 की कुंजियों से विस्तारित (status / menu / theme / lens / parse-error / action / quick-filter / wizard समूह) — MT-ड्राफ़्ट, जिनकी मानवीय समीक्षा v0.19.84 से पहले बाकी है। <code>xtask i18n-lint</code> नई कुंजी संख्या × 17 गैर-स्रोत लोकेल पर हरा रहता है।","changelog.d61b34326782":"<strong>टेस्ट + सत्यापन:</strong> <code>tests/smoke/phase_11_ui_e2e.rs</code> (7 मामले — <code>crates/freally-query/tests/phase_11_ui_e2e.rs</code> के अंतर्गत re-exported) कवर करता है: <code>parse_to_report</code> के token-stream invariants जिन पर search bar का <code>highlight.ts</code> निर्भर है, parse-error pill के लिए strict-everything-मोड त्रुटियों का दिखना, चरण-12 के बदलाव के लिए IPC <code>LensId</code> + <code>IndexPhase</code> JSON round-trip की स्थिरता, और <strong>जादुई-क्षण perf गेट</strong> (TASK-085): <code>parse_to_report</code> 1-वर्ण वाली क्वेरी पर और एक यथार्थवादी 32-वर्ण वाली क्वेरी पर औसतन 4 ms / iter से काफ़ी कम लेता है — कीस्ट्रोक का critical path Build Guide में बताए 16 ms बजट के भीतर रहता है। <code>apps/freally-ui/src-tauri/tests/menubar_parity.rs</code> (4 मामले) — PRD §8.28 का हर CommandId Rust spec में है; कोई अतिरिक्त नहीं; 7 शीर्ष-स्तरीय रूट सही क्रम में; कोई डुप्लिकेट id नहीं। <code>apps/freally-ui/src-tauri/tests/menubar_wiring.rs</code> (3 मामले) — हर मेनू आइटम id सही रूप में है (<code>namespace.action</code> आकार); हर accelerator string साफ़ पार्स होती है; macOS ऐप मेनू के परिचय / प्राथमिकताएँ / बाहर निकलें असली CommandIds को लक्ष्य करते हैं। <code>apps/freally-ui/src-tauri/tests/statusbar_parity.rs</code> (2 मामले) — 7 डिफ़ॉल्ट खंड + Freally के 2 (+) अतिरिक्त खंड पक्के किए गए। <code>apps/freally-ui/tests/unit/*.test.ts</code> (vitest ढाँचा, ~25 मामले) — formatters, command-id closed-set + <code>MENU_BAR</code> के साथ lockstep, tokenizer <code>highlight()</code> का segment shaping + error overlay + <code>firstError</code>, <code>BINDINGS</code> की अनन्यता + <code>shortcutMatches</code> + <code>formatShortcut</code>, <code>sortStore</code> टॉगल / दूसरे फ़ील्ड पर कूदना / score के अनुसार similarity, theme store चक्र + DOM attribute बदलाव। <code>tests/smoke/phase_11_ui_e2e.{sh,ps1}</code> routing टेस्ट पर <code>cargo test</code> + src-tauri crate पर <code>cargo check</code> + (<code>pnpm</code> उपलब्ध होने पर) <code>pnpm install + check + build</code> चलाता है। <strong>सत्यापन गेट</strong>: <code>cargo fmt --all -- --check</code>, <code>cargo clippy --workspace --all-targets -- -D warnings</code>, <code>cargo test --workspace</code> सभी हरे; <code>apps/freally-ui/src-tauri</code> का cargo check + clippy शून्य चेतावनियों के साथ साफ़; 9 src-tauri टेस्ट + 7 smoke टेस्ट पास। <code>/review</code> + <code>/security-review</code> साफ़ (स्थायी नियम (Standing Rule) #9)।","changelog.03bf40d97b72":"<code>apps/freally-ui/src/stories/</code> के अंतर्गत <strong>Storybook</strong> ढाँचा + 3 शुरुआती stories (LensTimingBadge, QuickFiltersPalette, SearchBar), और <code>.storybook/main.ts</code> + <code>preview.ts</code> में PRD §9 के visual-regression निर्देश के अनुसार गहरा / हल्का थीम toolbar switcher।","changelog.5df93276a274":"<strong>चरण 11 → चरण 12 हैंडऑफ़</strong> (TASK-086a/b/c तक टाला गया, Build-Prompts-Guide + ROADMAP में प्रलेखित): mock <code>commands/canned.rs</code> + <code>IndexStateMock</code> की जगह प्रति-उपयोगकर्ता Unix socket / named pipe पर असली <code>freally-rpc</code> length-prefixed JSON-RPC transport लाना (Unix पर file-mode 0600 + accept पर uid जाँच; Windows पर pipe DACL मौजूदा उपयोगकर्ता के SID तक सीमित); <code>query_run</code> को लाइव <code>freally-index</code> पर असली <code>freally-query::execute_with_audio</code> से होकर भेजना, <code>Window::emit(&quot;query:batch&quot;, ...)</code> से batches stream करते हुए, ताकि 5M फ़ाइलों पर भी UI का 16 ms गेट ईमानदार रहे; OS-native पूर्वावलोकन होस्ट (macOS पर <code>objc2</code> के ज़रिए QuickLook / Windows पर <code>windows-rs</code> के ज़रिए Shell preview handlers / Linux पर GNOME Sushi DBus + KDE KIO पूर्वावलोकन) mock <code>files_preview</code> / <code>files_thumbnail</code> की जगह लेंगे। <code>lib/ipc/types.ts</code> का TS अनुबंध इस बदलाव में स्थिर रहता है।","changelog.1cfd9c0b8865":"<strong>Build-Guide से विचलन</strong> (तीन, सभी कोड + इस प्रविष्टि में दर्ज): (1) <strong>Tauri shell plugin</strong> — Build Guide ने <code>files_open</code> / <code>files_reveal</code> के लिए <code>tauri-plugin-shell::open()</code> का संकेत दिया था; वह API <code>tauri-plugin-opener::open_path</code> के पक्ष में deprecated है। हर बिल्ड पर deprecation चेतावनी से बचने के लिए हम नया plugin उपयोग करते हैं। (2) <strong>Win/Linux पर नेटिव मेनू</strong> — Build Guide कहता है &quot;Win/Linux पर विंडो के भीतर, macOS पर ग्लोबल मेनू बार&quot;; चरण 11 Win/Linux पर विंडो के भीतर मेनू + macOS नेटिव मेनू शिप करता है। Linux पर DBus AppMenu एकीकरण (जहाँ उपलब्ध हो) चरण 12 तक टाला गया है। (3) <strong>OS-native पूर्वावलोकन होस्ट</strong> — चरण 11 पूर्वावलोकन फलक के लिए mock content provider (text-head + रंगीन SVG थंबनेल) के साथ शिप होता है; QuickLook / Shell / Sushi / KIO एकीकरण चरण 12 (TASK-086c) में जाते हैं, जहाँ वे असली-डेमन-IPC के दायरे को साझा करते हैं। चरण 11 prompt के TASK-075 / TASK-076 में इस टालने के बारे में इनलाइन ROADMAP टिप्पणियाँ हैं।","changelog.2e4654ecd39f":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 10: क्वेरी भाषा + पार्सर को मज़बूत करना (<code>freally-query</code>) — चरण-5 का हाथ से लिखा पार्सर अपनी voidtools-Everything 1:1 सतह (स्थायी नियम (Standing Rule) #8 अनुबंध) बनाए रखता है और उसमें चार नए हिस्से जुड़ते हैं: (1) <strong><code>ParseOpts { strict_everything: bool }</code></strong> + <code>pub fn parse_with(s, opts) -&gt; Result&lt;Query, ParseError&gt;</code> (चरण-5 का <code>parse(s)</code> अब <code>parse_with(s, ParseOpts::default())</code> है)। strict-everything मोड हर केवल-Freally मॉडिफ़ायर को अस्वीकार करता है — <code>similar:</code>, छह ऑडियो मॉडिफ़ायर (<code>lufs:</code> / <code>codec:</code> / <code>length:</code> / <code>rate:</code> / <code>silence:</code> / <code>dr:</code>) और साथ में <code>duration:</code> / <code>samplerate:</code> उपनाम, और <code>audio:(...)</code> / <code>content:(...)</code> / <code>similar:(...)</code> लेंस prefixes — और नया typed <code>ParseError::StrictEverythingViolation { pos, token, reason }</code> दिखाता है, ताकि चरण-11 का search bar हाइलाइट कर सके कि कौन-से मॉडिफ़ायर शुद्ध-voidtools उपयोगकर्ता तक नहीं जाएँगे। voidtools जैसी सतह (size, date, ext, attrib, path/parent/child + name/folder उपनाम, क्विक फ़िल्टर, regex, वाइल्डकार्ड, बूलियन जोड़, कोष्ठक, आदत से लिखे जाने वाले <code>wfn:</code> / <code>case:</code> / <code>count:</code> / <code>dupe:</code> / <code>nodiacritics:</code> / <code>type:</code> / <code>lang:</code> आरक्षण) strict मोड में भी पार्स होती रहती है। (2) <code>name:</code> / <code>audio:</code> / <code>content:</code> / <code>similar:</code> के लिए <strong>लेंस-prefix सिंटैक्स</strong> <code>&lt;key&gt;:(...)</code>। नया <code>QueryNode::Lens { kind: LensKind, inner: Box&lt;QueryNode&gt; }</code> AST variant (<code>pub enum LensKind { Name, Audio, Content, Similar }</code> के साथ) एक भीतरी उप-क्वेरी को लपेटता है, ताकि चरण-11 का लेंस-अनुसार समूहित परिणाम UI प्रति-लेंस अनुभाग रेंडर कर सके। पार्सर लेंस-prefix पथ तभी अपनाता है जब token ठीक <code>&lt;key&gt;:</code> हो <em>और</em> अगला token <code>(</code> हो — अकेला <code>audio:</code> क्विक फ़िल्टर ही रहता है; <code>similar:foo</code> मौजूदा <code>Similar</code> मॉडिफ़ायर ही रहता है; <code>name:foo</code>, <code>child:</code> का उपनाम ही रहता है। ख़ाली लेंस दायरे (<code>audio:()</code>) सिमटकर <code>True</code> हो जाते हैं। आज executor <code>Name</code> / <code>Audio</code> / <code>Similar</code> लेंस दायरों को पारदर्शी आवरण मानता है (भीतर के मॉडिफ़ायर ही routing तय करते हैं); <code>Content</code> लेंस दायरे तब तक <code>QueryError::UnsupportedModifier(&quot;content&quot;)</code> दिखाते हैं जब तक चरण 11+ चरण-8 के सामग्री एक्सट्रैक्टरों को executor से नहीं जोड़ता। (3) नए <code>crates/freally-query/src/optimizer.rs</code> में <strong>Optimizer पास</strong>: <code>pub fn optimize(q: &amp;Query) -&gt; Query</code>, <code>And</code> के बच्चों को <code>selectivity_rank</code> के अनुसार फिर से क्रम में लगाता है (सबसे सस्ता पहले → short-circuit उन्हें पकड़ लेता है), <code>Or</code> / <code>Not</code> / <code>Lens</code> में पुनरावर्ती रूप से जाता है (Or का क्रम बना रहता है — स्थिर hit क्रम के लिए क्रम मायने रखता है); rank फ़ंक्शन चरण 5/6/9 के executor की प्रति-predicate लागत के आधार पर अंशांकित है (literal/quick-filter/child = 10-12, ext = 13, size/date/attrib = 20-24, path/parent = 30, wildcard = 40, regex = 50, audio = 80, similar = 85, reserved = 90)। लेंस routing helpers <code>is_audio_only_route(node)</code> और <code>is_similarity_route(node)</code> executor को केवल-ऑडियो क्वेरी के लिए filename-trigram पूर्व-फ़िल्टर छोड़ने देते हैं (हर लाइव पंक्ति कैंडिडेट है, इसलिए <code>for_each_live</code> प्रति-पंक्ति <code>evaluator.matches</code> कॉल के बिना चलता है)। optimizer <code>execute_with_audio</code> (pipeline की शुरुआत में) और <code>PlanCache::get_or_plan</code> (कैश किया गया रूप ही optimized रूप है) में जुड़ा है, इसलिए हर वास्तविक रन को लाभ मिलता है, बिना <code>parse()</code> से मिलने वाली उपयोगकर्ता-दृश्य AST संरचना बदले। (4) <strong><code>pub fn parse_to_report(s: &amp;str, opts: ParseOpts) -&gt; ParseReport</code></strong> — नए <code>crates/freally-query/src/report.rs</code> में <code>query.parse</code> IPC का प्रवेश बिंदु। <code>ParseReport { source, strict_everything, ast: Option&lt;AstNode&gt;, tokens: Vec&lt;TokenInfo&gt;, errors: Vec&lt;ErrorInfo&gt; }</code> पूरी तरह serde-Serialize है, किसी Tauri कमांड या भविष्य के <code>freally-http</code> <code>/v1/query.parse</code> POST के लिए तैयार। <code>TokenInfo { kind, span: TokenSpan { start, end }, text }</code> प्रति-token spans + एक <code>TokenKind</code> अर्थगत प्रकार (<code>Literal</code> / <code>Quoted</code> / <code>Wildcard</code> / <code>Regex</code> / <code>Modifier{name}</code> / <code>QuickFilter{name}</code> / <code>LensPrefix{lens}</code> / <code>LParen</code> / <code>RParen</code> / <code>Bang</code> / <code>And</code> / <code>Or</code> / <code>Not</code>) रखता है, ताकि उपयोगकर्ता के टाइप करते ही search bar tokens को हाइलाइट कर सके। <code>ErrorInfo { span, message, code: ErrorCode }</code> हर <code>ParseError</code> variant को UI-अनुकूल span + संदेश + मशीन-पठनीय <code>ErrorCode</code> (<code>Empty</code> / <code>UnexpectedEof</code> / <code>UnexpectedToken</code> / <code>UnbalancedParens</code> / <code>InvalidRegex</code> / <code>InvalidWildcard</code> / <code>UnknownModifier</code> / <code>InvalidModifierValue</code> / <code>StrictEverythingViolation</code>) में बदलता है। serialize होने योग्य <code>AstNode</code>, <code>Arc&lt;Regex&gt;</code> payload को छोड़कर <code>QueryNode</code> की प्रतिकृति है (regex का स्रोत string के रूप में रखा जाता है — IPC consumer उसे अपनी ओर compile करता है); <code>ModifierDetail</code> हर मॉडिफ़ायर के लिए UI को चाहिए सबसे छोटा फ़ील्ड सेट रखता है (size: <code>{op, bytes}</code>, date: <code>{op, epoch_day}</code> या <code>{name}</code>, ext: <code>{extensions}</code>, attrib: <code>{letters}</code>, path/parent/child/similar: <code>{needle}</code>, ऑडियो variants: <code>{op, value}</code>, reserved: <code>{value}</code>)। <code>parse_to_report</code> कभी <code>Err</code> नहीं लौटाता — ख़ाली स्रोत भी पूरी रिपोर्ट देता है; <code>--strict-everything</code> के तहत यह token stream को पहले स्कैन करता है और <em>सभी</em> केवल-Freally मॉडिफ़ायर / लेंस-prefix उल्लंघन एक ही पास में दिखाता है (<code>parse_with</code> के पहला-मिलते-ही-रुक-जाने वाले व्यवहार के बजाय)। hot path (पार्सर का हिसाब-किताब + <code>tokenize</code>) अपरिवर्तित रहता है — नए प्रकार उसी से निकाले जाते हैं। पार्सर के भीतर नया: <code>Token</code> में एक <code>byte_len: usize</code> फ़ील्ड जुड़ा, ताकि रिपोर्ट परत दोबारा tokenize किए बिना प्रति-token spans बना सके। नए प्रकारों के लिए नई runtime dep <code>serde = workspace</code> (चरण 9 के ऑडियो कैश के ज़रिए पहले से workspace dep)। नए टेस्ट: <code>freally-query</code> में 67 unit टेस्ट (पार्सर + कैश + optimizer + रिपोर्ट), <code>tests/smoke/phase_10_query.rs</code> के अंतर्गत चरण-10 के 17 smoke मामले (<code>crates/freally-query/tests/phase_10_query.rs</code> के रूप में re-exported), <code>crates/freally-query/tests/freally_dsl.rs</code> में 21 Freally-DSL fixture टेस्ट (≥200 जनरेट की गई क्वेरी), नए <code>three_hundred_voidtools_queries_parse</code> सहित 3 voidtools-संगतता टेस्ट (कुल ≥300, हाथ से चुनी 120+ + एल्गोरिदमिक जनरेटर)। स्थायी नियम (Standing Rule) #8 का regression गेट बड़े 300+ सेट के भीतर का 50-क्वेरी fixture है।","changelog.07f1d2595011":"<strong>Build-Guide से विचलन।</strong> चरण 10 के prompt में कहा गया था &quot;चरण-5 के तदर्थ पार्सर को chumsky (या pest) grammar से बदलें।&quot; हमने फिर से लिखने के बजाय <strong>मौजूदा recursive-descent पार्सर को मज़बूत करना</strong> चुना, क्योंकि चरण-5 की सतह एक 1:1 voidtools-Everything अनुबंध है (स्थायी नियम (Standing Rule) #8), जिसमें कई कोने के मामले हैं — <code>(a)!b</code> का पार्स <code>(a) AND !b</code> होता है; <code>regex:</code> केवल अगले कोष्ठक / रिक्त स्थान तक ही लेता है; <code>attrib:HRA</code> एक फ़्लैग <em>सेट</em> है, स्ट्रिंग नहीं; <code>audio:</code> के क्विक फ़िल्टर / लेंस-prefix होने का निर्णय अगले token के वर्ग पर टिका है। हर ख़ासियत को chumsky 0.10 की combinator API में या <code>query.pest</code> PEG grammar में, 50-क्वेरी fixture में regression के बिना, फिर से लिखना ऊँचे जोखिम और कम लाभ का काम है। मज़बूत किया गया हाथ से लिखा पार्सर चरण-10 का हर लक्ष्य पूरा करता है — <code>Token::byte_len</code> से प्रति-token span ट्रैकिंग, <code>ParseReport::errors</code> से प्रति-token त्रुटियाँ, strict-everything मोड, लेंस prefixes, optimizer — और स्थायी-नियम-#8 अनुबंध के लिए शून्य जोखिम के साथ। 300+ voidtools-fixture की बढ़ोतरी एक <em>regression गेट</em> है, porting का लक्ष्य नहीं। बेंचमार्क के आँकड़े मिलने पर चरण 13 का perf पास आँकेगा कि chumsky port फ़ायदेमंद है या नहीं।","changelog.c2c6adddd634":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 9 ऑडियो एक्सट्रैक्टर (<code>freally-audio</code>) — symphonia-आधारित decoder + EBU R128 loudness माप (शुद्ध-Rust <code>ebur128 = &quot;0.1&quot;</code> crate से) + silence अनुपात + dynamic range, और साथ में क्वेरी DSL में <code>lufs:</code> / <code>codec:</code> / <code>length:</code> / <code>rate:</code> / <code>silence:</code> / <code>dr:</code> मॉडिफ़ायर। सार्वजनिक सतह: <code>pub fn analyze_file(path: &amp;Path) -&gt; Result&lt;AudioAttributes, AudioError&gt;</code>, और cooperative-cancel + समय-बजट पथ के लिए <code>analyze_with_opts(path, AnalysisOpts)</code>; <code>pub trait AudioAttributesProvider</code> (कैश जैसा abstraction, जिससे executor बात करता है); <code>pub struct AudioCache</code> (in-memory + डिस्क पर JSON कैश, mtime-आधारित अमान्यकरण, <code>Condvar</code> से single-flight निष्कर्षण, और प्रति-निष्कर्षण समय बजट जिसका डिफ़ॉल्ट <code>DEFAULT_AUDIO_TIME_BUDGET = 5 s</code> है, ताकि कोई शत्रुतापूर्ण ऑडियो फ़ाइल अनिश्चित काल तक loop न कर सके)। <code>AudioAttributes</code> में हैं: <code>codec</code> (लोअरकेस symphonia short-id — <code>flac</code> / <code>mp3</code> / <code>aac</code> / <code>vorbis</code> / <code>pcm_s16</code> / <code>alac</code> / …), <code>sample_rate</code>, <code>channels</code>, <code>bit_depth</code>, <code>duration_ns</code>, <code>lufs_integrated</code>, <code>lufs_short_term_p99</code>, <code>lufs_short_term_p10</code>, <code>peak_dbfs</code> (ebur128 crate के 4× polyphase oversampler से true peak — हाथ से लिखे FIR के बिना Build-Guide spec पूरा), <code>silence_ratio</code> (<code>−60 dBFS</code> से नीचे के samples का %; प्रति-sample हिसाब, ताकि गणित channel संख्या से स्वतंत्र रहे — <code>mono_and_correlated_stereo_report_same_ratio</code> regression देखें), और <code>dynamic_range_lu</code> (<code>short_term_p99 − short_term_p10</code>; 3 सेकंड से छोटी क्लिप के लिए, जिनकी short-term sliding window कभी भरी ही नहीं, यह <code>0</code> हो जाता है, और percentiles <code>f32::NEG_INFINITY</code> के रूप में दिखते हैं, ताकि <code>lufs:&gt;x</code> क्वेरी कभी गलती से मेल न खाए)। LUFS / peak फ़ील्ड non-finite मानों (<code>±∞</code> / <code>NaN</code>) को एक कस्टम <code>lufs_serde</code> JSON helper से round-trip करते हैं, जो तीन sentinel strings (<code>&quot;-inf&quot;</code> / <code>&quot;+inf&quot;</code> / <code>&quot;nan&quot;</code>) उपयोग करता है — वरना non-finite के लिए <code>serde_json</code> का डिफ़ॉल्ट-<code>null</code> व्यवहार चुपचाप कैश को दूषित कर देता; <code>unknown_sentinel_rejects</code> typed-error पथ पर regression जाँच करता है। channels की कठोर सीमा <code>MAX_CHANNELS = 64</code> है, ताकि कोई विकृत हेडर sandbox के पकड़ने से पहले प्रति-tap विशाल आवंटन के लिए बाध्य न कर सके। analyzer <code>AudioError::NotAudio</code> / <code>Probe</code> / <code>Decode</code> / <code>Empty</code> / <code>Unsupported</code> / <code>Cancelled</code> / <code>Json</code> / <code>NonUtf8Path</code> typed errors दिखाता है। क्वेरी DSL में <code>parse_audio_lufs</code> / <code>_codec</code> / <code>_length</code> / <code>_rate</code> / <code>_silence</code> / <code>_dr</code> पार्सर जुड़े, जो चरण-5 के <code>split_op</code> रूप का पुनः उपयोग करते हैं (<code>&lt;</code> / <code>&lt;=</code> / <code>&gt;</code> / <code>&gt;=</code> / <code>=</code> / अकेला = <code>==</code>); <code>length:</code> सेकंड, <code>mm:ss</code> और <code>hh:mm:ss</code> स्वीकार करता है (मिनट-overflow guard के साथ, ताकि <code>length:1:90</code> अस्वीकार हो); <code>rate:</code>, <code>Hz</code> / <code>kHz</code> इकाइयाँ स्वीकार करता है; <code>silence:</code> अनुपात और प्रतिशत दोनों स्वीकार करता है; <code>dr:</code> ऋणात्मक मान अस्वीकार करता है; voidtools-Everything की आदत के लिए <code>duration:</code>, <code>length:</code> का उपनाम है और <code>samplerate:</code>, <code>rate:</code> का। executor में <code>pub fn execute_with_audio(idx, similarity_opt, audio_opt, q, opts)</code> जुड़ा, जो <code>has_audio_anywhere</code> से ऑडियो वाली क्वेरी पहचानता है, एक <code>AudioAttributesProvider</code> माँगता है (नहीं तो <code>QueryError::AudioProviderUnavailable</code> दिखाता है — ख़ाली परिणामों के बजाय typed त्रुटि, चरण 6 के <code>SimilarityIndexUnavailable</code> अनुबंध के अनुरूप), और कैश किए गए attrs पर <code>eval_audio_predicate</code> चलाने से पहले हर पंक्ति के लिए provider से <code>AudioAttributes</code> देखता है। समानता लेंस के साथ ऑडियो संयोजन (<code>similar:bassdrop codec:flac length:&gt;3:00</code>) उसी executor पथ से शुरू से अंत तक काम करते हैं। cooperative-cancel जाँचें हर symphonia packet पर एक बार चलती हैं (supervisor के मेल खाते <code>Release</code> flip के लिए cancel atomic पर <code>Ordering::Acquire</code>); <code>SymphoniaError::ResetRequired</code> पर <code>SampleBuffer</code> रीसेट होता है, ताकि अगला packet नए decoder की <code>capacity()</code> के अनुसार नए सिरे से आवंटित हो (<code>copy_interleaved_typed</code> capacity-assertion panic से बचाता है)। <code>TimeBudgetSupervisor</code> एक अलग (detached) थ्रेड है जो बजट बीतते ही cancel फ़्लैग पलट देता है और supervisor के <code>Drop</code> में पलटे गए <code>done</code> फ़्लैग से ख़ुद को साफ़ करता है। नई runtime deps (सभी permissive, deny.toml की अनुमति-सूची में): <code>symphonia = &quot;0.5&quot;</code> (MPL-2.0; शुद्ध-Rust ऑडियो decoder; सक्षम features: aac, alac, flac, isomp4, mp3, ogg, pcm, vorbis, wav, aiff, opt-simd — Opus जानबूझकर बंद है, क्योंकि upstream test vectors में GPL जैसा डेटा है जिसे deny नीति प्रतिबंधित करती है; केवल-MIT Opus crate आने पर हम इस पर फिर विचार करेंगे), <code>ebur128 = &quot;0.1&quot;</code> (MIT/Apache-2.0; libebur128 का शुद्ध-Rust port), और साथ में मौजूदा workspace deps (<code>serde_json</code>, <code>parking_lot</code>, <code>tracing</code>, <code>thiserror</code>, टेस्ट के लिए <code>tempfile</code>)। Smoke टेस्ट <code>tests/smoke/phase_09_audio.rs</code> (10 मामले — <code>crates/freally-query/tests/phase_09_audio.rs</code> के अंतर्गत re-exported) कवर करता है: कृत्रिम WAV fixtures पर analyzer round-trip (−23 dBFS पर 1 kHz sine ±1 LU के भीतर ≈ −23 LUFS पढ़ता है; शुद्ध मौन <code>silence_ratio &gt; 0.99</code> और integrated LUFS = <code>f32::NEG_INFINITY</code> पढ़ता है), ऑडियो-कैश का डिस्क round-trip + mtime अमान्यकरण, छहों ऑडियो मॉडिफ़ायर की पार्सिंग, Build-Guide prompt का संयुक्त <code>lufs:&lt;-14 codec:flac length:&gt;3:00</code> उदाहरण, typed <code>AudioProviderUnavailable</code> गेट, कृत्रिम ऑडियो फ़ाइलों से भरे in-memory <code>Index</code> पर शुरू से अंत तक <code>execute_with_audio</code> फ़िल्टरिंग (तेज़ + धीमी sines <code>lufs:&gt;-20</code> / <code>lufs:&lt;-20</code> की दोनों दिशाएँ सत्यापित करती हैं), शुद्ध-मौन ऑडियो पर <code>silence:=</code> epsilon मिलान, <code>NullProvider</code> fall-through (ऑडियो मॉडिफ़ायर panic करने के बजाय किसी से मेल नहीं खाते), और cancel-flag / समय-बजट supervisor के abort पथ। चरण 9 कोई नई UI स्ट्रिंग नहीं जोड़ता — मॉडिफ़ायर कमांड जैसे हैं (<code>size:</code> / <code>ext:</code> की तरह); <code>xtask i18n-lint</code> 5 कुंजियों × 17 गैर-स्रोत लोकेल पर हरा रहता है।","changelog.138d44119faa":"<strong>Build-Guide से विचलन।</strong> उन deps पर दो इनलाइन टिप्पणियाँ जो Build Guide से शब्दशः मेल नहीं खातीं:","changelog.c49ebee11cd1":"<strong>ऑडियो decoder</strong>: Build Guide &quot;symphonia&quot; का नाम लेता है — जैसा लिखा है वैसा ही उपयोग किया गया। Build Guide &quot;ebur128 (libebur128)&quot; का नाम भी लेता है; वर्कस्पेस को शुद्ध-Rust रखने और तीन-OS CI पर system-library इंस्टॉल के चरणों से बचने के लिए हम C library के बजाय शुद्ध-Rust <code>ebur128 = &quot;0.1&quot;</code> crate (Sebastian Dröge का port) उपयोग करते हैं।","changelog.fb9344590719":"<strong>Opus समर्थन</strong>: Build Guide समर्थित प्रारूपों में Opus का नाम लेता है। v0.19.84 के लिए हम इसे छोड़ रहे हैं, क्योंकि symphonia का <code>opus</code> feature GPL जैसे test vectors साथ लाता है, जो <code>cargo-deny</code> के AGPL/GPL प्रतिबंध से टकराते हैं। Opus वाला OGG कंटेनर भ्रामक मिलान के बजाय <code>Probe</code>/<code>Decode</code> विफलता के रूप में दिखता है; केवल-MIT Opus decoder आने पर हम इस पर फिर विचार करेंगे। दो और टिप्पणियाँ: <strong>EBU R128 conformance suite</strong>: चरण 9 का prompt गेट के रूप में &quot;ज्ञात-LUFS संदर्भ क्लिप (EBU R128 conformance suite), ±0.1 LU सहनशीलता&quot; का नाम लेता है। smoke टेस्ट ±1 LU पर एक कृत्रिम-sine harness शिप करता है (−23 dBFS पर 1 kHz sine, K-weighting के बाद ≈ −23 LUFS पढ़ता है); प्रकाशित EBU क्लिप शामिल नहीं की गईं, क्योंकि वर्कस्पेस का प्रयास है कि ट्री में कोई बाइनरी fixture न हो। बाइनरी-fixture का मामला तय होते ही चरण 13 का perf पास conformance suite को CI matrix में जोड़ेगा। <strong>Sandbox wiring</strong>: ऑडियो analyzer चरण-7 के <code>sandbox-extractors</code> <code>Sandbox</code> के भीतर <em>नहीं</em> चलता — वह supervisor <code>Extractor</code> (टेक्स्ट जैसे) एक्सट्रैक्टरों के लिए बना है, जबकि ऑडियो संरचित <code>AudioAttributes</code> देता है। ऑडियो crate उसी 5-सेकंड डिफ़ॉल्ट बजट के साथ अपना <code>TimeBudgetSupervisor</code> शिप करता है; cooperative-cancel अनुबंध एक जैसा है (हर packet पर cancel atomic का <code>Acquire</code> load)। सचमुच शत्रुतापूर्ण ऑडियो फ़ाइलों के लिए subprocess isolation वही चरण-13 आकलन है जो PDF के non-cooperative-decode पथ को कवर करता है।","changelog.1eeff18b7504":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 8 दस्तावेज़ एक्सट्रैक्टर (<code>freally-extractors::extractors</code>) — चरण-7 के <code>Pipeline</code> के साथ पंजीकृत छह pluggable एक्सट्रैक्टर, और साथ में <code>register_all(builder)</code> / <code>default_pipeline()</code> helpers, जो उन्हें dispatch क्रम में जोड़ते हैं। कवरेज: <strong>(1) सादा टेक्स्ट + Markdown</strong> — <code>PLAIN_TEXT_CAP_BYTES = 5 MiB</code> तक पढ़ता है, UTF-8 / UTF-16 LE / UTF-16 BE byte-order marks पहचानता है, body को UTF-8 में डिकोड करता है, और डिकोड किया गया टेक्स्ट sink में डालता है; यह एक्सट्रैक्टर उन फ़ाइलों के लिए भी अंतिम सहारा है जिन पर किसी और एक्सट्रैक्टर ने दावा नहीं किया (एक्सटेंशन अनुमति-सूची <code>.txt</code> / <code>.text</code> / <code>.md</code> / <code>.markdown</code> / <code>.mkd</code> / <code>.log</code> / <code>.rst</code> / <code>.adoc</code> / <code>.asciidoc</code> / <code>.rtf</code>, और साथ में <code>looks_like_text</code> head-bytes heuristic, जो 1 भटका NUL सह लेता है और 2+ अस्वीकार करता है)। <strong>(2) PDF</strong> — <code>pdf-extract = &quot;0.10&quot;</code> (MIT, शुद्ध-Rust, pdf-rs ecosystem) दस्तावेज़ पार्स करता है और पेजों के बीच <code>U+000C</code> के साथ टेक्स्ट देता है, ताकि खोज स्निपेट पेज संख्या बता सकें; एन्क्रिप्टेड / पासवर्ड-सुरक्षित PDF <code>ExtractError::Unsupported(...)</code> के रूप में, और विकृत इनपुट <code>ExtractError::Malformed(...)</code> के रूप में दिखते हैं। <strong>(3) Office</strong> — <code>XlsxExtractor</code>, <code>calamine = &quot;0.34&quot;</code> (MIT) उपयोग करता है और हर ग़ैर-ख़ाली cell के लिए <code>Sheet1!A1=value</code> रूप में एक पंक्ति देता है; <code>DocxExtractor</code> और <code>PptxExtractor</code>, <code>zip = &quot;5&quot;</code> + <code>quick-xml = &quot;0.39&quot;</code> से सीधे OOXML पार्स करते हैं, इसलिए हम कोई <code>ooxmlsdk-rs</code> dependency शिप नहीं करते (विचलन टिप्पणी देखें)। docx शीर्षकों को Markdown (<code># Title</code>, <code>## Sub</code>, …) के रूप में रेंडर करता है और तालिकाओं को <code>| cell | cell |\\n</code> पंक्तियों में चपटा करता है; pptx स्लाइडों पर संख्या-क्रम में चलता है और हर एक के आगे <code># Slide N: &lt;title&gt;</code> लगाता है। <strong>(4) कोड</strong> — <code>tree-sitter = &quot;0.25&quot;</code> runtime + 32 grammar crates, जो Rust, Python, JS, TS/TSX, Go, Java, C, C++, C#, Ruby, Bash, Lua, PHP, Kotlin, Scala, Swift, Haskell, OCaml, Elixir, Erlang, Clojure, Elm, Dart, R, Julia, Zig, Nix, TOML, YAML, JSON, HTML, CSS, SQL को कवर करते हैं। हर पार्स <code>[lang]</code> / <code>[identifiers]</code> / <code>[strings]</code> / <code>[comments]</code> अनुभाग देता है; identifiers के डुप्लिकेट हटाए जाते हैं, strings + comments अपना शाब्दिक रूप बनाए रखते हैं, ताकि <code>content:&quot;hello world&quot;</code> मूल स्रोत से मेल खाए। cooperative cancel जाँचें हर <code>CANCEL_CHECK_EVERY = 1024</code> नोड पर चलती हैं, ताकि supervisor लंबे ट्री walk को बीच में रोक सके। <strong>(5) आर्काइव झलक (archive peek)</strong> — <code>zip = &quot;5&quot;</code> + <code>sevenz-rust2 = &quot;0.21&quot;</code> + <code>tar = &quot;0.4&quot;</code> बाइट को डिस्क पर निकाले बिना प्रविष्टियाँ गिनाते हैं; आउटपुट का रूप हर प्रविष्टि के लिए <code>archive.zip!path/to/inner.txt size=1234</code> है (डेमन यही वर्चुअल पथ इंडेक्सर को देता है, ताकि <code>inner.txt</code> की खोज आर्काइव की सामग्री से मेल खाए)। हर आर्काइव पर <code>MAX_ENTRIES = 100_000</code> की कठोर सीमा; 1M फ़ाइलों वाला tar sink और समय बजट को नहीं जलाएगा। <strong>(6) संरचित डेटा</strong> — <code>serde_json</code> (workspace) + <code>csv = &quot;1&quot;</code> + <code>serde_yaml_ng = &quot;0.10&quot;</code> डेटा को <code>key=value</code> पंक्तियों में चपटा करते हैं: JSON / YAML बिंदु वाली कुंजियाँ (<code>address.zip=10001</code>) और arrays के लिए <code>[idx]</code> उपयोग करते हैं; CSV हर ग़ैर-हेडर पंक्ति के लिए <code>header=value</code> देता है, और हेडर न होने पर <code>col0=value</code> पर लौटता है; बहु-दस्तावेज़ YAML हर दस्तावेज़ के आगे <code>[doc=N]</code> लगाता है। Smoke टेस्ट <code>tests/smoke/phase_08_doc_extractors.rs</code> (16 मामले) कवर करता है: <code>default_pipeline()</code> पंजीकरण, dispatch क्रम (<code>.xlsx</code> के लिए xlsx, archive-peek पर भारी पड़ता है; सादे <code>.zip</code> के लिए archive-peek जीतता है; <code>%PDF-</code> magic से PDF जीतता है; सादा-टेक्स्ट <code>.log</code> को पकड़ता है), सादे टेक्स्ट से BOM हटाना, JSON / CSV / YAML को चपटा करना, वर्चुअल पथों के साथ zip सूची, docx Heading-शैली → Markdown रूपांतरण, pptx स्लाइड क्रम, और कोड-एक्सट्रैक्टर द्वारा identifier / string / comment पकड़ना। नई runtime deps (सभी permissive, deny.toml की अनुमति-सूची में): <code>pdf-extract = &quot;0.10&quot;</code> (MIT), <code>calamine = &quot;0.34&quot;</code> (MIT/Apache-2.0), <code>zip = &quot;5&quot;</code> (MIT), <code>quick-xml = &quot;0.39&quot;</code> (MIT), <code>sevenz-rust2 = &quot;0.21&quot;</code> (Apache-2.0), <code>tar = &quot;0.4&quot;</code> (MIT/Apache-2.0), <code>csv = &quot;1&quot;</code> (Unlicense/MIT), <code>serde_yaml_ng = &quot;0.10&quot;</code> (MIT/Apache-2.0), <code>tree-sitter = &quot;0.25&quot;</code> (MIT), और साथ में ऊपर सूचीबद्ध 32 grammar crates (MIT/Apache-2.0 का मिश्रण — हर grammar का लाइसेंस deny.toml की अनुमति-सूची में है)।","changelog.eeeac6857769":"<strong>Build-Guide से विचलन।</strong> 3-OS CI को हरा और 18-लोकेल की समय-सारणी को पटरी पर रखने के लिए दो नामित deps बदली गईं:","changelog.56e5dde6f237":"<strong>आर्काइव झलक:</strong> Build Guide <code>compress-tools</code> (libarchive) का नाम लेता है। libarchive एक system library है — Windows CI होस्ट इसे साथ नहीं देते और <code>vcpkg</code> की व्यवस्था इस चरण को रोक देती। हम शुद्ध-Rust तिकड़ी (<code>zip</code> + <code>sevenz-rust2</code> + <code>tar</code>) उपयोग करते हैं; परिणाम वही <code>archive.ext!entry size=N</code> वर्चुअल-पथ आउटपुट है जो Build Guide माँगता है, बिना किसी system dep के।","changelog.bd47ec1aa5f2":"<strong>Office:</strong> Build Guide docx + pptx के लिए <code>ooxmlsdk-rs</code> का नाम लेता है। वह crate 2026-Q1 तक crates.io पर अनुरक्षित नहीं है और उसमें Rust-2024 समर्थन नहीं है। Office Open XML, zip + XML है, इसलिए हम उसे सीधे <code>zip</code> + <code>quick-xml</code> से पढ़ते हैं। कुल प्रभाव: छोटी attack surface (इंडेक्सर केवल <em>टेक्स्ट</em> पढ़ता है, styling / layout / embedded objects नहीं) और एक pinned dependency कम। दो और टिप्पणियाँ: <strong>Dockerfile</strong> के लिए अभी ट्री में कोई grammar नहीं है, क्योंकि एकमात्र प्रकाशित <code>tree-sitter-dockerfile</code> (0.2.0) अब भी tree-sitter 0.20 runtime से बँधा है, जो cargo के <code>links = &quot;tree-sitter&quot;</code> नियम के कारण हमारे 0.25 runtime से टकराता है; फ़िलहाल Dockerfiles सादे-टेक्स्ट एक्सट्रैक्टर पर चली जाती हैं और grammar के rebase होने पर हम इस पर फिर विचार करेंगे। <strong>PDF सहयोग</strong> प्रति-पेज के बजाय पूरे दस्तावेज़ पर है, क्योंकि <code>pdf-extract</code> पार्स पर रुका रहता है — sandbox के समय बजट से अधिक लेने वाला भारी PDF worker थ्रेड को leak करके समाप्त होता है (non-cooperative एक्सट्रैक्टरों के लिए sandbox का प्रलेखित अनुबंध); subprocess isolation चरण-13 का आकलन है।","changelog.9aec97cffe7b":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 7 प्रारूप-एक्सट्रैक्टर फ़्रेमवर्क (<code>freally-extractors</code>) — trait, dispatcher, प्रति-निष्कर्षण sandbox, सीमित निष्कर्षण queue, content-addressed blob store, और प्रति-एक्सट्रैक्टर मोड (Lazy / Eager / Disabled)। सार्वजनिक सतह Build Guide के चरण-7 prompt से मेल खाती है: <code>pub trait Extractor: Send + Sync { fn id(&amp;self) -&gt; ExtractorId; fn matches(&amp;self, path: &amp;Path, magic: &amp;[u8]) -&gt; bool; fn extract(&amp;self, path: &amp;Path, sink: &amp;mut TextSink) -&gt; Result&lt;ExtractionStats, ExtractError&gt;; }</code>। <code>Pipeline::builder().register(...).build()</code> compile-time पंजीकरण का चरण है; <code>Pipeline::dispatch_path(path)</code> कैंडिडेट फ़ाइल की शुरुआत से <code>MAGIC_HEAD_BYTES = 32</code> तक पढ़ता है और पंजीकृत एक्सट्रैक्टरों पर पंजीकरण क्रम में चलता है, उन्हें छोड़ते हुए जिनका प्रभावी <code>ExtractorMode</code> <code>Disabled</code> है; <code>Pipeline::replace_settings</code> डेमन को बिना रीस्टार्ट के लाइव सेटिंग बदलने देता है। <code>Extractor::extract</code> trait method एक <code>&amp;mut TextSink</code> लेता है (सीमित byte writer, जिसमें sandbox का cancel-flag <code>is_cancelled()</code> से जुड़ा है); प्रति-निष्कर्षण टेक्स्ट सीमा से आगे के writes <code>SinkOverflow</code> लौटाते हैं, जिसे एक्सट्रैक्टर <code>ExtractError::OutputTooLarge</code> में बदल देता है। <code>Sandbox::execute(Arc&lt;dyn Extractor&gt;, PathBuf)</code> एक worker थ्रेड चलाता है जो एक्सट्रैक्टर को कॉल करता है, और कॉल करने वाला थ्रेड supervisor का काम करता है — <code>mpsc::sync_channel::recv_timeout</code> हर tick पर poll करता है (डिफ़ॉल्ट 100 ms), cancel फ़्लैग पलटकर और एक cancel-grace अवधि (डिफ़ॉल्ट 250 ms) प्रतीक्षा करके 5-सेकंड का समय बजट लागू करता है, फिर <code>SandboxError::TimeBudget</code> लौटाता है, चाहे worker ने काम छोड़ा हो या नहीं (non-cooperative एक्सट्रैक्टर हर उल्लंघन पर एक worker थ्रेड leak करते हैं — प्रलेखित अनुबंध; शत्रुतापूर्ण third-party प्रारूपों के लिए चरण 13 subprocess isolation आँकेगा); RSS guard Linux पर <code>/proc/self/status</code> की <code>VmRSS:</code> पंक्ति पढ़ता है, Windows पर <code>GetProcessMemoryInfo</code>, और macOS / अन्य Unix पर no-op है (चरण-7 prompt: &quot;no-op (macOS — समय बजट पर निर्भर)&quot;)। cooperative एक्सट्रैक्टर काम के बड़े हिस्सों के बीच <code>sink.is_cancelled()</code> जाँचते हैं और <code>ExtractError::Cancelled</code> दिखाते हैं; sandbox अपने द्वारा ट्रैक किए गए उल्लंघन के कारण के आधार पर उसे वापस <code>SandboxError::TimeBudget</code> या <code>SandboxError::MemoryCeiling</code> में बदल देता है। <code>ExtractionQueue</code> एक सीमित <code>BinaryHeap&lt;Entry&gt;</code> है जिसकी कुंजी <code>(mtime_ns desc, FIFO seq)</code> है, ताकि हाल में छुई गई फ़ाइलें पहले dispatch हों और समान-mtime वाली प्रविष्टियाँ डाले जाने के क्रम में निकलें; heap के क्षमता तक पहुँचने पर <code>try_push</code>, <code>QueueError::Full(capacity)</code> दिखाता है और <code>close()</code> के बाद <code>QueueError::Closed</code>, जो चरण 4 के <code>EventQueue</code> की close-safety नीति की प्रतिकृति है (<code>closed</code> उसी <code>Mutex</code> के भीतर है जिसमें heap है, ताकि समवर्ती <code>close()</code> किसी प्रतीक्षक की &quot;क्या heap ख़ाली है?&quot; जाँच से race न कर सके)। <code>BlobStore::open(&lt;index_root&gt;/extracted)</code> रूट बनाता है; <code>put(content)</code>, <code>BlobId = blake3(content)</code> की गणना करता है (32 B → 64 hex वर्ण), सामग्री को zstd से encode करता है (डिफ़ॉल्ट level 3 — अगर compression निष्कर्षण समय पर हावी हो तो चरण 13 का perf पास level 1 पर जाने का आकलन करेगा), और उसी shard डायरेक्टरी के भीतर tmp+rename से atomic ढंग से <code>&lt;root&gt;/&lt;first2hex&gt;/&lt;full-hex&gt;</code> पर लिखता है; <code>get(id)</code>, <code>memmap2::Mmap</code> से संपीड़ित frame को mmap करता है और डीकंप्रेस किया गया <code>Vec&lt;u8&gt;</code> लौटाता है; <code>for_each(|id|)</code> लाइव store पर चलता है, <code>.tmp-*</code> अधूरी फ़ाइलों और ग़ैर-hex फ़ाइल नामों को <code>warn</code> लॉग स्तर पर छोड़ते हुए। <code>put</code> पर idempotent डुप्लिकेट-हटाना अंतर्निहित और content-addressed है; <code>BlobStoreStats</code> (<code>puts</code> / <code>dedup_hits</code> / <code>get_hits</code> / <code>get_misses</code> / <code>bytes_written</code> / <code>bytes_decompressed</code>) डेमन के स्थिति फलक को डेटा देता है। <code>ExtractorMode::{Eager, Lazy, Disabled}</code> का डिफ़ॉल्ट <code>Lazy</code> है (नए bootstrap वाले इंडेक्स, उपयोगकर्ता के सामग्री खोज में रुचि दिखाने से पहले, सामग्री निष्कर्षण पर CPU नहीं जलाते); <code>PipelineSettings</code> में ग्लोबल डिफ़ॉल्ट, प्रति-एक्सट्रैक्टर overrides का एक <code>HashMap&lt;String, ExtractorMode&gt;</code> (<code>ExtractorId::as_str()</code> से कुंजीबद्ध, ताकि crate-संस्करण बदलने पर भी JSON फ़ाइल स्थिर रहे), समय / मेमोरी / sink-सीमा बजट, और queue क्षमता होती है। सेटिंग <code>serde_json</code> से साफ़ round-trip होती है — JSON फ़ाइल प्रारूप का स्वामित्व चरण 12 के सेटिंग डायलॉग के पास होगा। नई runtime deps (सभी permissive, deny.toml की अनुमति-सूची में): <code>zstd = &quot;0.13&quot;</code> (BSD-3-Clause; Tantivy के ज़रिए पहले से आती है, blob-store के compress/decompress पथ के लिए यहाँ सीधे घोषित), <code>memmap2 = &quot;0.9&quot;</code> (MIT/Apache-2.0; <code>freally-index</code> के ज़रिए पहले से आती है, blob-store के mmap reads के लिए यहाँ सीधे घोषित), <code>blake3 = &quot;1&quot;</code> (CC0/Apache-2.0; वही content-addressing primitive जो चरण 4 + चरण 6 पहले से उपयोग करते हैं), <code>parking_lot = &quot;0.12&quot;</code> (MIT/Apache-2.0; बाकी वर्कस्पेस के lock primitive से मेल खाता है), <code>serde_json = workspace</code> (MIT/Apache-2.0; सेटिंग serialization), Windows पर <code>GetProcessMemoryInfo</code> के लिए <code>Win32_System_ProcessStatus</code> + <code>Win32_System_Threading</code> features के साथ <code>windows-sys = &quot;0.59&quot;</code>, और Linux + macOS पर <code>libc = &quot;0.2&quot;</code> (Linux पर केवल-पठन <code>/proc/self/status</code> पार्स; macOS पर भविष्य के RSS hooks के लिए केवल मौजूदगी)। Smoke टेस्ट <code>tests/smoke/phase_07_extractor_fw.rs</code> (17 मामले) कवर करता है: Pipeline dispatch (एक्सटेंशन + magic + पहला-मिलान-जीतता-है + अक्षम-छोड़ा-जाता-है + छोटी-फ़ाइल-का-magic-पढ़ना), Sandbox (cooperative समय-बजट, बजट+grace के भीतर चलता है + एक्सट्रैक्टर त्रुटि आगे पहुँचती है + सफलता पथ), Queue (प्राथमिकता + back-pressure + close से रुका हुआ pop खुलता है), BlobStore (round-trip + डुप्लिकेट-हटाना + लेआउट + स्थायित्व + hex round-trip), और सेटिंग JSON round-trip।","changelog.d64d1c8e1432":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 6 फ़ाइल नाम-समानता लेंस (<code>freally-similarity</code>) — bigram-MinHash + 16×8 LSH पर आधारित, फ़ाइल नामों के लगभग-डुप्लिकेट का इंडेक्स। <code>SimilarityIndex::open(dir)</code> दी गई डायरेक्टरी में <code>minhash.idx</code> खोलता है या बनाता है; <code>upsert(file_id, name)</code> इनपुट को लोअरकेस करता है, अंत का एक्सटेंशन हटाता है, एक नियतात्मक linear-hash परिवार से <code>[u64; 128]</code> MinHash हस्ताक्षर की गणना करता है (SplitMix64-seeded <code>(a, b)</code> जोड़ियाँ, निश्चित <code>MINHASH_SEED = 0x534F5552_43455252</code>), और पंक्ति को 8-8 hashes वाले 16 LSH बैंड में डालता है; <code>remove(file_id)</code> पंक्ति को tombstone करता है और हर बैंड से हटा देता है, ताकि कोई पुरानी band posting tombstone हुए hit को सामने न ला सके। <code>apply(&amp;[JournalEvent])</code> Create / Rename / Delete events लेता है (Modify और AttrChange no-op हैं, क्योंकि फ़ाइल नाम नहीं बदला) और <code>file_id</code> को उसी <code>blake3(OsStr-bytes)[..8]</code> truncation से फिर से निकालता है जो <code>freally-index</code> उपयोग करता है, ताकि <code>SimilarityHit::file_id</code>, <code>Index::store::get_many</code> से साफ़ round-trip हो। <code>candidates(query, &amp;SimilarityOpts)</code> LSH lookup चलाता है, हर कैंडिडेट को Jaccard अनुमान से अंक देता है, सीमा से नीचे वाले hits हटाता है (डिफ़ॉल्ट <code>DEFAULT_JACCARD_THRESHOLD = 0.30</code>), Jaccard के अवरोही क्रम में सॉर्ट करता है — बराबरी होने पर नियतात्मक आउटपुट के लिए <code>file_id</code> आरोही क्रम में — और <code>candidate_cap</code> तक काट देता है। <code>flush()</code>, tmp-rename से <code>minhash.idx</code> को atomic ढंग से फिर से लिखता है — <code>[Header — 32 B] [Heap] [Rows: file_id u64 + name_off u32 + name_len u32 + signature [u64; 128]]</code> — magic <code>SRC-MNHS</code>, संस्करण 1; <code>open()</code> हर लाइव पंक्ति के हस्ताक्षर से bands map फिर से बनाता है, ताकि डिस्क पर फ़ाइल प्रारूप संक्षिप्त रहे (चरण 13 perf-पास टिप्पणी: SA-IS आने पर bands map को सीधे सहेजें)। क्वेरी DSL (<code>freally-query</code>) अब <code>similar:&lt;needle&gt;</code> को एक नए <code>ModifierKind::Similar(String)</code> variant में पार्स करता है — चरण 5 के <code>Reserved</code> सेट से बाहर लाया गया; ख़ाली needle (<code>similar:</code>) <code>ParseError::InvalidModifierValue</code> त्रुटि देता है। नया <code>execute_with(idx, similarity, q, opts)</code> प्रवेश बिंदु शीर्ष-स्तर पर <code>Similar</code> मॉडिफ़ायर वाली किसी भी क्वेरी को दिए गए <code>SimilarityIndex</code> से होकर भेजता है (LSH कैंडिडेट → SQLite hydration → शेष-predicate फ़िल्टर → Jaccard-अवरोही सॉर्ट, जब तक उपयोगकर्ता ने स्पष्ट रूप से कोई ग़ैर-डिफ़ॉल्ट <code>SortSpec</code> न चुना हो); पुराना <code>execute(idx, q, opts)</code> अब <code>execute_with(idx, None, …)</code> के ऊपर एक पतला आवरण है, जो <code>similar:</code> क्वेरी पहुँचने पर typed <code>QueryError::SimilarityIndexUnavailable</code> लौटाता है, ताकि callers को ख़ाली परिणामों के बजाय स्पष्ट संदेश दिखे। <code>OR</code> / <code>NOT</code> / nested AND के भीतर दबा <code>similar:</code> <code>QueryError::UnsupportedSimilarPosition</code> दिखाता है — चरण 6 केवल-शीर्ष-स्तर वाला पहला संस्करण शिप करता है, जिसकी यह सीमा चरण 10 के optimizer पास से हटती है। नया <code>SortField::Relevance</code> variant समानता क्वेरी होने पर Jaccard के अवरोही क्रम में लगाता है, और ग़ैर-समानता क्वेरी के लिए <code>Name</code> क्रम पर लौटता है (voidtools के Everything के &quot;Sort by Relevance&quot; अर्थ से मेल खाता है; चरण 11 का UI यह विकल्प दिखाता है)। फ़ाइल नाम के हस्ताक्षर <em>stem</em> (एक्सटेंशन हटाकर) पर निकाले जाते हैं, ताकि <code>similar:report-final</code> टाइप करने वाला उपयोगकर्ता अंत के <code>.pdf</code> के लिए 4-5 bigram का दंड चुकाए बिना इंडेक्स किए गए <code>report-final.pdf</code> से साफ़ मेल पाए; पूरा लोअरकेस नाम निदान के लिए अब भी heap में रहता है। चरण 6 के spec गेट: 50 ज्ञात लगभग-डुप्लिकेट वाला 5 000 नामों का कृत्रिम corpus (नियतात्मक SplitMix64 seed) (<code>-v2</code> suffix बढ़ाना + <code>-draft</code> टैग जोड़ना + 1-वर्ण हटाना, जिन्हें Jaccard ≈ 0.73 पर LSH के मोड़ से दूर रखा गया) spec की 95 % recall न्यूनतम सीमा पूरी करता है (<code>crates/freally-similarity/tests/recall.rs</code>); एक smoke <code>tests/smoke/phase_06_similarity.rs</code> parse/route/compose/persist/error-position invariants को कवर करता है। नई runtime deps (सभी permissive, deny.toml की अनुमति-सूची में): <code>blake3 = &quot;1&quot;</code> (<code>freally-index</code> के ज़रिए पहले से आती है; file_id निकालने के लिए यहाँ सीधे घोषित); मौजूदा <code>parking_lot</code> / <code>thiserror</code> / <code>tracing</code> / <code>freally-journal</code> श्रृंखला।","changelog.1b0bc0f992e4":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 0 का ढाँचा: Cargo workspace; 1100×720 गहरे रंग का Tauri 2 + Svelte 5 UI shell; 18 लोकेल के <code>.ftl</code> stubs; <code>xtask</code> (<code>i18n-lint</code>, <code>third-party-notices</code>, <code>icon-build</code>, <code>release</code>); 3-OS GitHub Actions CI; <code>deny.toml</code> लाइसेंस नीति (AGPL पर पूर्ण प्रतिबंध); हल्के नीले आवर्धक-लेंस वाला आइकन परिवार। पहला सार्वजनिक टैग <strong>v0.19.84</strong> होगा।","changelog.24697757938e":"<strong>[केवल Windows]</strong> चरण 1 NTFS USN journal subscriber (<code>freally-journal-win</code>): <code>JournalSubscriber::open</code>, <code>FSCTL_QUERY_USN_JOURNAL</code> से journal की क्वेरी करता है, <code>bootstrap()</code>, <code>FSCTL_ENUM_USN_DATA</code> से MFT गिनाता है, <code>subscribe()</code>, <code>FSCTL_READ_USN_JOURNAL</code> से क्रमिक events stream करता है, और एक प्रति-वॉल्यूम cursor (volume serial + journal ID + अगला USN) <code>%LOCALAPPDATA%\\Freally\\cursors\\&lt;serial&gt;.json</code> के अंतर्गत rename-atomic save से सहेजा जाता है। Reason flags <code>JournalEvent::{Create, Modify, Delete, Rename, AttrChange}</code> से जुड़ते हैं। चरण 2 में macOS FSEvents subscriber और चरण 3 में Linux inotify/fanotify subscriber इसे संतुलित करेंगे।","changelog.b71505a013b6":"<strong>[केवल Windows]</strong> <code>freally-indexd</code> की Service Control Manager wiring: <code>install</code> / <code>uninstall</code> / <code>service</code> subcommands <code>Freally-Indexd</code> Windows Service को पंजीकृत करते और चलाते हैं (स्वतः-शुरू, SCM stop स्वीकार करती है)। चरण 4 सेवा के भीतर प्रति-वॉल्यूम subscriber + index core भरता है।","changelog.cc1fb2dcf2b9":"<strong>[केवल macOS]</strong> चरण 2 FSEvents journal subscriber (<code>freally-journal-mac</code>): <code>JournalSubscriber::open</code> एक absolute watch root resolve करता है, उसका <code>stat.st_dev</code> + <code>statfs.f_fstypename</code> दर्ज करता है, और <code>~/Library/Application Support/Freally/cursors/&lt;root_hash&gt;.json</code> के अंतर्गत प्रति-watch cursor लोड करता है (या पहली बार बनाता है)। <code>bootstrap()</code> ट्री पर चलकर कृत्रिम <code>JournalEvent::Create</code> events देता है। <code>subscribe()</code> एक समर्पित CFRunLoop थ्रेड चलाता है जो <code>FSEventStreamCreate(latency=0.5s, FileEvents | NoDefer | UseCFTypes | WatchRoot)</code> चलाता है, FSEvents-flag → <code>JournalEvent</code> तालिका से हर batch के flag bitmask को वर्गीकृत करता है, <strong>प्रति-batch rename जोड़ी</strong> बनाता है (<code>ItemRenamed</code> जोड़ी के दोनों हिस्सों को inode से मिलाकर), <code>MustScanSubDirs</code> पर subtrees को इनलाइन फिर से स्कैन करता है, और रीस्टार्ट के बाद फिर से शुरू करने के लिए <code>last_event_id</code> सहेजता है। batches के पार rename जोड़ियाँ <code>Delete + Create</code> में बदल जाती हैं (चरण-13 perf-पास टिप्पणी)। runtime deps <code>core-foundation = &quot;0.10&quot;</code>, <code>core-foundation-sys = &quot;0.8&quot;</code>, <code>fsevent-sys = &quot;4&quot;</code>, <code>libc = &quot;0.2&quot;</code> — सभी MIT/Apache-2.0, deny.toml की अनुमति-सूची में।","changelog.4fcde431e77b":"<strong>[केवल macOS]</strong> <code>freally-indexd</code> की launchd-agent wiring: <code>install</code> / <code>uninstall</code> / <code>service</code> subcommands <code>~/Library/LaunchAgents/io.mikeweaver.freally.indexd.plist</code> पर <code>RunAtLoad=true</code> + <code>KeepAlive=true</code> के साथ एक प्रति-उपयोगकर्ता launchd agent पंजीकृत करते और चलाते हैं। चरण 4 agent के भीतर प्रति-रूट subscriber + index core भरता है। foreground <code>run --root &lt;path&gt;</code> मोड हाथ से / smoke-टेस्ट जाँच के लिए FSEvents events को stdout पर छापता है।","changelog.051c4dd1753a":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>freally-journal</code> facade अब <code>cfg(target_os = &quot;macos&quot;)</code> पर <code>freally-journal-mac</code> से मानक <code>open</code> / <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> re-export करता है। Linux अब भी typed-पर-stub वाली सतह उपयोग करता है; चरण 3 उसे बदलेगा।","changelog.8b1b0978d0a2":"<strong>[केवल Linux]</strong> चरण 3 inotify+fanotify journal subscriber (<code>freally-journal-lin</code>): <code>JournalSubscriber::open</code> एक absolute watch root resolve करता है, उसका <code>stat.st_dev</code> + <code>statfs.f_type</code> magic-number से जुड़ा नाम (ext4/btrfs/zfs/xfs/f2fs/tmpfs/...) दर्ज करता है, <code>/proc/self/status</code> की <code>CapEff:</code> पंक्ति से <code>CAP_SYS_ADMIN</code> पहचानता है, और <code>~/.local/share/freally/cursors/&lt;root_hash&gt;.json</code> (XDG_DATA_HOME का ध्यान रखते हुए) के अंतर्गत प्रति-watch cursor लोड करता है (या पहली बार बनाता है)। <code>bootstrap()</code>, <code>(st_dev, st_ino)</code> cycle-guard के साथ कच्चे <code>getdents64(2)</code> से ट्री पर चलता है (विशाल ट्री पर <code>read_dir</code> से तेज़) और कृत्रिम <code>JournalEvent::Create</code> events देता है। <code>subscribe()</code> एक समर्पित थ्रेड चलाता है जो चुना गया backend चलाता है: <strong>inotify</strong> (डिफ़ॉल्ट, किसी विशेषाधिकार के बिना) — create/modify/close-write/delete/move/attr को कवर करने वाला पुनरावर्ती <code>inotify_add_watch</code>, जिसमें <code>IN_Q_OVERFLOW</code> पूरे ट्री का <code>getdents64</code> पुनः स्कैन ट्रिगर करता है; या <strong>fanotify</strong> (CAP_SYS_ADMIN आवश्यक) — <code>FAN_REPORT_DFID_NAME</code> के साथ एक <code>fanotify_mark(FAN_MARK_FILESYSTEM)</code>, ताकि rename ट्रैकिंग Btrfs subvolume के पार जाने और overlayfs में भी बनी रहे, जिन्हें inotify दोहरा नहीं सकता। inotify mask वर्गीकरण चरण-1 की USN reason प्राथमिकता की प्रतिकृति है (<code>Delete &gt; Create</code>, <code>Rename &gt; Create</code>, <code>IN_CLOSE_WRITE</code> से <code>Modify</code> तय होता है)। inotify cookie / fanotify <code>OLD_DFID_NAME</code> info record से प्रति-batch rename जोड़ी; batches के पार बँटी जोड़ियाँ <code>Delete + Create</code> में बदल जाती हैं (चरण-13 perf-पास टिप्पणी)। init पर fanotify का <code>EPERM/EINVAL/ENOSYS</code> inotify पर लौट आता है, ताकि kernels &lt; 5.17 (<code>FAN_REPORT_DFID_NAME</code> नहीं) और <code>CONFIG_FANOTIFY=n</code> बिल्ड काम करते रहें। runtime dep केवल <code>libc = &quot;0.2&quot;</code> — शुद्ध raw-syscall पथ।","changelog.f558e7c13bef":"<strong>[केवल Linux]</strong> <code>freally-indexd</code> की systemd-user-unit wiring: <code>install</code> / <code>uninstall</code> / <code>service</code> subcommands <code>Type=simple</code> + <code>Restart=always</code> + <code>WantedBy=default.target</code> के साथ (चरण-3 spec के अनुसार) <code>~/.config/systemd/user/freally-indexd.service</code> लिखते हैं और <code>systemctl --user enable --now</code> चलाते हैं। <code>ExecStart</code> बाइनरी पथ को उद्धरण चिह्नों में रखता है, ताकि <code>--binary &quot;/path with spaces/freally-indexd&quot;</code> वाला इंस्टॉल systemd के whitespace-संवेदी unit parser में भी टिका रहे। चरण 4 सेवा के भीतर प्रति-रूट subscriber + index core भरता है। foreground <code>run --root &lt;path&gt;</code> मोड हाथ से / smoke-टेस्ट जाँच के लिए inotify/fanotify events को stdout पर छापता है।","changelog.c891685c91b5":"<strong>[केवल Linux]</strong> <code>crates/freally-indexd/polkit/io.mikeweaver.freally.policy</code> पर Polkit नीति, जो वैकल्पिक fanotify अपग्रेड प्रवाह के लिए action <code>io.mikeweaver.freally.elevate</code> घोषित करती है। <code>auth_self_keep</code> (≈5 min) सक्रिय उपयोगकर्ता से उसका अपना पासवर्ड माँगता है; <code>org.freedesktop.policykit.exec.path</code> + <code>argv1</code> annotations <code>/usr/local/bin/freally-indexd elevate</code> को पक्का करते हैं, ताकि action ID को किसी दूसरी बाइनरी के विरुद्ध फिर से इस्तेमाल न किया जा सके। distribution अनुरक्षक यह फ़ाइल <code>/usr/share/polkit-1/actions/</code> में शिप करते हैं।","changelog.5ce16f33ef5f":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>freally-journal</code> facade अब <code>cfg(target_os = &quot;linux&quot;)</code> पर <code>freally-journal-lin</code> से मानक <code>open</code> / <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> / <code>WatchCursor</code> re-export करता है। दूसरे Unix लक्ष्य (FreeBSD, OpenBSD, illumos) typed-पर-stub वाली <code>portable_stub</code> सतह बनाए रखते हैं।","changelog.369e1b7b5e7f":"ठीक किया गया (चरण 8 समीक्षा दौर)","changelog.600f17cedae8":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 8 का सादा-टेक्स्ट एक्सट्रैक्टर अब सीमा-पार वाली काट-छाँट चलने से <em>पहले</em> encoding पहचानता है। पिछला संस्करण encoding चाहे जो हो, कटे हुए buffer पर बिना शर्त loop में <code>from_utf8</code> वाली काट-छाँट चलाता था — 5 MiB सीमा (≈ 2.5 M codepoints) पार करने वाले UTF-16 इनपुट के लिए loop तब तक बाइट निकालता रहता था जब तक UTF-8 जैसा prefix न मिल जाए, जिससे अक्सर buffer विषम बाइट लंबाई पर रह जाता था, जिसे <code>decode</code> फिर <code>ExtractError::Malformed</code> के रूप में अस्वीकार कर देता था। encoding-जागरूक काट-छाँट के साथ, नए <code>trim_to_utf8_boundary</code> helper से UTF-16 सम-बाइट सीमा तक और UTF-8 codepoint सीमा तक कटता है। नया regression <code>utf16_le_overshoot_truncates_at_even_boundary_not_malformed</code> इस अनुबंध को पक्का करता है।","changelog.29036e7ef80a":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 8 के archive-peek + संरचित-डेटा एक्सट्रैक्टर अब नए <code>extractors::util::sanitize_inline</code> helper से आर्काइव प्रविष्टि नामों, CSV फ़ील्ड मानों, और JSON / YAML scalar string मानों में line-break control वर्णों (<code>\\n</code> / <code>\\r</code> / <code>\\0</code>) को साफ़ करते हैं। पहले कोई शत्रुतापूर्ण zip / 7z / tar प्रविष्टि <code>\\n</code> वाला नाम घोषित करके search blob में नकली पंक्तियाँ डाल सकती थी (एक प्रविष्टि कई का रूप धर लेती); यही बग CSV / JSON / YAML scalar सतह पर भी था, जहाँ उद्धृत फ़ील्ड में वैध रूप से नई पंक्तियाँ होती हैं। साफ़ किया गया आउटपुट बाइट को गिराने के बजाय escape करके (<code>\\\\n</code> / <code>\\\\r</code> / <code>\\\\0</code>) खोज recall बनाए रखता है। नए regressions <code>entry_name_with_newline_is_sanitized</code> (आर्काइव), <code>csv_field_with_newline_is_sanitized</code>, और <code>json_string_value_with_newline_is_sanitized</code> हर सतह पर अनुबंध को कवर करते हैं।","changelog.85af001a0e9a":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 8 के docx + pptx पार्सर अब प्रति-अनुच्छेद (docx) / केवल-प्रति-स्लाइड (pptx) के बजाय प्रति-event बजट पर <code>sink.is_cancelled()</code> जाँचते हैं। एक विशाल <code>&lt;w:p&gt;</code> (हज़ारों <code>&lt;w:t&gt;</code> runs जुड़े हुए) वाला शत्रुतापूर्ण docx पहले cancel फ़्लैग की परवाह किए बिना <code>parse_docx_body</code> के भीतर सेकंडों बिताता था; pptx के slide-XML पार्सर में कोई भीतरी cancel जाँच थी ही नहीं। सुधार हर quick-xml event गिनता है और 32-event बजट पर फ़्लैग जाँचता है — load अपने आप में एक अकेला <code>Ordering::Relaxed</code> atomic है, जिसकी लागत एक नैनोसेकंड से भी कम है। सबसे बुरी स्थिति के लिए चरण-7 sandbox की grace अवधि सुरक्षा जाल बनी रहती है, पर cooperative shutdown अब इनपुट XML की बनावट चाहे जो हो, सीमित बजट पर चलता है।","changelog.85445058bd37":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 8 का docx एक्सट्रैक्टर अब heading-शैली वाले पर टेक्स्ट-रहित अनुच्छेदों को दबा देता है। पिछला संस्करण <code>&lt;w:pStyle w:val=&quot;HeadingN&quot;/&gt;</code> वाले ख़ाली <code>&lt;w:p&gt;</code> blocks के लिए search blob में अकेला <code># \\n\\n</code> (या गहरे hash स्तर वाला) डाल देता था; <code>#</code> जैसे आगे के tokens शोर हैं, जो बिना किसी recall लाभ के sink सीमा में गिने जाते हैं। नया regression <code>docx_skips_empty_heading_paragraphs</code> इसे कवर करता है।","changelog.1dad52d35905":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 8 के कोड + सादा-टेक्स्ट एक्सट्रैक्टर अब साझा <code>trim_to_utf8_boundary</code> continuation-byte backtrack से सीमा-पार buffers को O(1) में UTF-8 codepoint सीमा तक काटते हैं, जो पिछले <code>while !std::str::from_utf8(&amp;buf).is_ok() { buf.pop(); }</code> loop की जगह लेता है, जो हर pop पर पूरे 4 / 5 MiB buffer को फिर से स्कैन करता था (सबसे बुरी स्थिति O(N²))। <code>extractors::util::tests</code> के छह unit टेस्ट पूर्ण-codepoint, आंशिक-codepoint, ASCII-सीमा, सभी-continuations, और ख़ाली-buffer मामलों पर regression जाँच करते हैं।","changelog.4e47265991ba":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 8 की docx तालिकाओं (<code>&lt;w:tbl&gt;</code> / <code>&lt;w:tr&gt;</code> / <code>&lt;w:tc&gt;</code>) को स्पष्ट टेस्ट कवरेज मिला। <code>parse_docx_body</code> पहले से table tags संभालता था, पर कोई टेस्ट उस पथ को नहीं चलाता था; वहाँ regression होने पर तालिका वाले हर docx में तालिका की सामग्री चुपचाप खोज recall से हट जाती। नया <code>docx_renders_tables_as_pipe_rows</code>, <code>| cell | cell |</code> रेंडरिंग को पक्का करता है।","changelog.f8937347b501":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 8 के बहु-दस्तावेज़ YAML (<code>---</code> विभाजक) को स्पष्ट टेस्ट कवरेज मिला। <code>flatten_yaml</code> पथ <code>[doc=N]</code>-prefix वाली कुंजियाँ देता था, पर कोई टेस्ट prefix तर्क को कवर नहीं करता था; नया <code>flattens_multi_document_yaml_with_doc_prefix</code> सुनिश्चित करता है कि भविष्य का कोई refactor दस्तावेज़ सीमाओं को चुपचाप न मिटा दे।","changelog.585aef173030":"ठीक किया गया (चरण 5 समीक्षा दौर)","changelog.0aa74d3eaa36":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 5 का क्वेरी पार्सर अब <code>)</code> के बाद आए <code>!</code> को prefix-NOT मानता है — voidtools-Everything के प्रलेखित व्यवहार से मेल खाने के लिए <code>(a)!b</code> का पार्स <code>(a) AND !b</code> होता है। पहले byte-और-token सीमा जाँच में <code>RParen</code> छूट गया था, इसलिए पीछे का <code>!b</code> एक अकेले literal <code>!b</code> में सिमट जाता था और निषेध चुपचाप गिर जाता था (स्थायी नियम (Standing Rule) #8 regression)। नया पार्सर-टेस्ट <code>bang_after_rparen_is_not</code> इस अनुबंध को पक्का करता है।","changelog.7a304dd66705":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>match_mode.match_path</code> चालू होने पर चरण 5 का plan cache अब कैश किए गए plan को नहीं बदलता। path-search को ट्राइग्राम पूर्व-फ़िल्टर से बचने देने वाला seed-clear अब केवल निष्पादन के समय चलता है — <code>ExecPlan</code> क्वेरी string का शुद्ध फ़ंक्शन बना रहता है, इसलिए एक ही क्वेरी पर अलग-अलग <code>match_path</code> सेटिंग वाले दो समवर्ती callers अब एक-दूसरे का कैश किया गया plan दूषित नहीं कर सकते। नया wiring-टेस्ट <code>plan_cache_survives_match_path_toggle</code> इसे कवर करता है।","changelog.fa995dcc342d":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 5 का <code>parse_iso_day</code> एक नए <code>days_in_month</code> validator से कैलेंडर में असंभव दिनों (30 फ़रवरी, 31 अप्रैल, ग़ैर-लीप वर्ष का 29 फ़रवरी, …) को शुरुआत में ही अस्वीकार करता है (Howard Hinnant का epoch-day अंकगणित किसी भी महीने के लिए 1-31 का कोई भी दिन स्वीकार कर लेता था और overflow को चुपचाप आगे खिसका देता था)। voidtools इन्हें अस्वीकार करता है — स्थायी नियम (Standing Rule) #8 regression। नया पार्सर-टेस्ट <code>invalid_calendar_days_reject</code> लीप-वर्ष + महीने-के-अंत वाले मामलों को कवर करता है।","changelog.a94bbcf610a6":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 5 की मॉडिफ़ायर आरक्षण सूची को voidtools-Everything के आदतन tokens (<code>wfn:</code>, <code>wholefilename:</code>, <code>case:</code>, <code>count:</code>, <code>dupe:</code>, <code>nodiacritics:</code>) तक बढ़ाया गया, ताकि इन्हें टाइप करने वाले उपयोगकर्ताओं को पार्स त्रुटि के बजाय निष्पादन के समय typed <code>QueryError::UnsupportedModifier</code> मिले। जब तक इनमें से हर टॉगल अपने लेंस वाले चरण में शिप नहीं होता, तब तक पार्स-होता-है-पर-ज़ोर-से-विफल-होता-है ही स्थायी नियम (Standing Rule) #8 का अनुबंध है। नया पार्सर-टेस्ट <code>voidtools_reserved_toggles_parse</code> इस परिवार को कवर करता है।","changelog.6543bc5ccebd":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>match_path</code> चालू होने पर चरण 5 का <code>eval_full</code> अब हर AND / OR child नोड के लिए दोबारा लोअरकेस करने के बजाय कैंडिडेट पथ को प्रति पंक्ति एक बार लोअरकेस करता है — लोअरकेस पथ string को <code>NameEvaluator::matches_full</code> में ऊपर उठाया गया है और <code>Option&lt;&amp;str&gt;</code> के रूप में <code>eval_full</code> से होकर आगे भेजा जाता है। इससे प्रति-AND-child वह <code>to_lowercase()</code> आवंटन ख़त्म होता है जो क्वेरी की गहराई के साथ बढ़ता था।","changelog.cd2b5074233d":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 5 का <code>eval_modifier::Reserved</code> अब पहुँचने पर <code>debug_assert!</code> करता है — <code>validate_supported</code>, <code>execute()</code> की शुरुआत में प्रलेखित गेट है, और किसी Reserved मॉडिफ़ायर का मूल्यांकन तक पहुँचना इसका अर्थ है कि किसी caller ने हाथ से <code>Query</code> AST बनाकर गेट को दरकिनार किया। पिछली चुपचाप-<code>false</code> वाली शाखा समर्थित कॉल पथों में dead-code है और अब <code>cfg(debug_assertions)</code> के तहत ज़ोर से विफल होती है।","changelog.dc40e0e57b5d":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 5 फ़ाइल नाम लेंस (<code>freally-query</code>) — चरण-4 के इंडेक्स पर voidtools-Everything जैसा DSL पार्सर + executor। <code>parse(s)</code> एक <code>Query</code> AST बनाता है जो कवर करता है: literal substring / wildcard (<code>*</code>, <code>?</code>) / regex (<code>regex:</code> prefix) शब्द, बूलियन जोड़ (<code>AND</code> / <code>OR</code> / <code>NOT</code> / <code>!</code> prefix, सटे हुए atoms के बीच अंतर्निहित-AND, कोष्ठक वाले समूह), और मॉडिफ़ायर predicates: <code>size:</code> (<code>&gt;</code>, <code>&lt;</code>, <code>&gt;=</code>, <code>&lt;=</code>, <code>=</code>, और <code>b</code>/<code>kb</code>/<code>mb</code>/<code>gb</code>/<code>tb</code> इकाइयों के साथ), <code>date:</code> (सापेक्ष उपनाम <code>today</code> / <code>yesterday</code> / <code>thisweek</code> / <code>lastweek</code> / <code>thismonth</code> / <code>lastmonth</code> / <code>thisyear</code> / <code>lastyear</code>, और साथ में तुलना-चिह्न के साथ निरपेक्ष <code>YYYY-MM-DD</code>), <code>ext:</code> (एक या <code>;</code>-से-अलग सूची, <code>.</code> हटाकर), <code>attrib:</code> (Windows-अक्षर सेट <code>R</code>/<code>H</code>/<code>S</code>/<code>A</code>/<code>D</code>/<code>C</code>/<code>E</code>/<code>T</code>/<code>O</code>/<code>L</code>), <code>path:</code> / <code>parent:</code> / <code>child:</code> (substring matchers; <code>name:</code> / <code>folder:</code> उपनाम मान्य)। क्विक-फ़िल्टर उपनाम <code>audio:</code> / <code>video:</code> / <code>image:</code> / <code>document:</code> / <code>executable:</code> / <code>archive:</code> पहले से तय एक्सटेंशन सेटों में फैलते हैं। भविष्य के लेंसों के मॉडिफ़ायर (<code>content:</code> / <code>lufs:</code> / <code>codec:</code> / <code>channels:</code> / <code>samplerate:</code> / <code>length:</code> / <code>similar:</code> / <code>duration:</code> / <code>type:</code> / <code>lang:</code>) पार्स होते हैं पर <code>validate_supported</code> से gated हैं, और जब तक उनका अपना चरण शिप नहीं होता, <code>QueryError::UnsupportedModifier</code> दिखाते हैं। <code>execute(idx, query, ExecOpts)</code> क्वेरी की योजना बनाता है (सबसे लंबा literal substring ट्राइग्राम सीड बनता है; OR सीड को तोड़कर लाइव-पंक्ति स्कैन में बदल देता है), नए <code>for_each_candidate_named</code> / <code>for_each_live</code> borrowed-bytes APIs से कस्टम नाम इंडेक्स से कैंडिडेट निकालता है, नाम-पक्ष के predicates चलाता है, बचे हुओं को नए <code>Store::get_many</code> batched IN-clause fetch से hydrate करता है, पूर्ण-रिकॉर्ड predicates का मूल्यांकन करता है, <code>SortSpec</code> (name / path / size / date / type / ext, asc/desc) लागू करता है, और परिणाम <code>ResultSet::first_batch</code> / <code>collect</code> से stream करता है। <code>MatchMode</code> टॉगल (<code>match_case</code> / <code>whole_word</code> / <code>match_path</code> / <code>match_diacritics</code>) निष्पादन के समय परत के रूप में लगते हैं; <code>match_path</code> नाम-इंडेक्स पूर्व-फ़िल्टर छोड़कर खोज लक्ष्य को मानकीकृत पूरे पथ तक चौड़ा करता है (चरण-13 perf-पास टिप्पणी); <code>match_diacritics: false</code> substring तुलना से पहले NFKD से combining marks हटाता है। 16-प्रविष्टि वाला LRU <code>PlanCache</code> (<code>PlanCache::default16</code>) trim की गई क्वेरी string को कुंजी बनाता है और बार-बार दोबारा टाइप करने पर पार्स किए गए AST + plan का पुनः उपयोग करता है। नई runtime deps (सभी permissive, deny.toml की अनुमति-सूची में): <code>regex = &quot;1&quot;</code> (MIT/Apache-2.0), <code>unicode-normalization = &quot;0.1&quot;</code> (MIT/Apache-2.0)। <code>crates/freally-index</code> के <code>name_index</code> ने अपना ट्राइग्राम intersection <code>BTreeSet</code> से बदलकर sorted-postings two-pointer merge कर दिया (Build-Guide §<code>name_index</code> PERF टिप्पणी) और लेंस के लिए <code>name_bytes</code> / <code>for_each_candidate_named</code> / <code>for_each_live</code> उपलब्ध कराता है; SQLite के <code>SQLITE_MAX_VARIABLE_NUMBER</code> से नीचे रहने के लिए <code>Store::get_many</code> हर IN-clause में 250 ids के टुकड़े बनाता है। <code>xtask gen-fixture</code> चरण-5 के perf bench (<code>cargo bench -p freally-query --bench filename_lens</code>) के लिए एक नियतात्मक SplitMix64 file-record stream गढ़ता है; bench प्रति-परिदृश्य P50 / P99, FAIL चिह्नों के साथ छापता है, और केवल <code>FREALLY_BENCH_GATE=1</code> होने पर ही ग़ैर-शून्य कोड के साथ बाहर निकलता है। <code>tests/voidtools_compat.rs</code> fixture 50 असली Everything क्वेरी पक्की करता है — स्थायी नियम (Standing Rule) #8 का regression गेट; <code>tests/wiring.rs</code> एक <code>tempfile</code>-आधारित इंडेक्स पर executor को शुरू से अंत तक कवर करता है; <code>tests/smoke/phase_05_filename_lens.rs</code> वह OS-निरपेक्ष smoke टेस्ट है जो CI matrix की हर प्रविष्टि पर चलता है।","changelog.0af41265e3fd":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 4 index core (<code>freally-index</code>) — OS-निरपेक्ष façade जो साझा <code>JournalEvent</code> enum लेता है और तीन स्थायी stores का संचालन करता है: पूर्ण-टेक्स्ट + faceted खोज के लिए एक Tantivy इंडेक्स (<code>index.tantivy/</code>), टिकाऊ <code>FileRecord</code> सत्य-पंक्ति के लिए WAL मोड + <code>synchronous=NORMAL</code> में एक SQLite मानक <code>files.db</code>, और substring कैंडिडेट बनाने के लिए एक कस्टम mmap-आधारित नाम इंडेक्स (<code>name.idx</code> packed string heap + ट्राइग्राम inverted postings; <code>name.suf</code> lexicographic suffix array)। <code>Index::open(root)</code> डायरेक्टरी ट्री बनाता है, हर store खोलता या बनाता है, और पंक्ति संख्याएँ असहमत होने पर मानक store को नाम इंडेक्स में replay करके विचलन ठीक करता है। <code>Index::apply(&amp;[JournalEvent])</code> Create / Modify / Delete / Rename / AttrChange events को Tantivy delete-then-add + SQLite upsert + नाम-इंडेक्स upsert/remove से गुज़ारता है, स्थिर कुंजी के रूप में <code>file_id = blake3(path)[0..8]</code> के साथ। <code>Index::commit()</code> Tantivy को flush करता है, tmp-rename से <code>name.idx</code> + <code>name.suf</code> को atomic ढंग से फिर से लिखता है, SQLite WAL को मुख्य DB में checkpoint करता है, और बढ़े हुए <code>tantivy_generation</code> के साथ-साथ <code>Index::record_cursor</code> से दर्ज प्रति-वॉल्यूम cursors सहित <code>manifest.json</code> सहेजता है। सीमित <code>EventQueue</code> (डिफ़ॉल्ट क्षमता 10 000 — Build-Guide spec) events को चुपचाप गिराने के बजाय back-pressure को <code>IndexError::QueueFull</code> के रूप में दिखाता है; <code>push_blocking</code> भी वही close अर्थ-व्यवहार मानता है। <code>default_index_root()</code> से प्रति-OS डिफ़ॉल्ट index root (<code>%LOCALAPPDATA%\\Freally\\index</code> / <code>~/Library/Application Support/Freally/index</code> / <code>${XDG_DATA_HOME:-~/.local/share}/freally/index</code>)। नई runtime deps (सभी permissive, deny.toml की अनुमति-सूची में): <code>tantivy = &quot;0.26&quot;</code> (MIT), <code>bundled</code> feature के साथ <code>rusqlite = &quot;0.37&quot;</code> (MIT) — जो <code>libsqlite3-sys</code> + bundled SQLite (public-domain, <code>Unlicense</code> के अंतर्गत अनुमत) लाता है, <code>memmap2 = &quot;0.9&quot;</code> (MIT/Apache-2.0), <code>blake3 = &quot;1&quot;</code> (CC0/Apache-2.0), <code>parking_lot = &quot;0.12&quot;</code> (MIT/Apache-2.0)। Smoke टेस्ट <code>tests/smoke/phase_04_index.rs</code> डायरेक्टरी लेआउट, पूरा event round-trip, SQLite से kill-9 के बाद पुनर्प्राप्ति, manifest cursor का स्थायित्व, queue back-pressure, और Tantivy delete-then-add डुप्लिकेट-हटाने को कवर करता है।","changelog.8167310c5eff":"<strong>[सभी प्लेटफ़ॉर्म]</strong> <code>freally-journal</code> facade अब <code>cfg(windows)</code> पर Windows subscriber से, <code>cfg(target_os = &quot;macos&quot;)</code> पर macOS subscriber से, और <code>cfg(target_os = &quot;linux&quot;)</code> पर Linux subscriber से मानक <code>JournalEvent</code> / <code>JournalError</code> / <code>JournalSubscriber</code> re-export करता है। दूसरे Unix लक्ष्य typed-पर-stub वाली <code>portable_stub</code> सतह बनाए रखते हैं।","changelog.f11a02c6c5f1":"<strong>[macOS + Linux]</strong> <code>freally-indexd</code> के <code>Run</code> subcommand का <code>--root &lt;path&gt;</code> फ़्लैग (macOS / Linux पर पसंदीदा) अब Linux journal subscriber को भी चलाता है; मौजूदा <code>--volume</code> हर OS पर पर्याय के रूप में काम करता रहता है।","changelog.6897dd8bf8f4":"ठीक किया गया (चरण 4 समीक्षा दौर)","changelog.2ed95ca28b12":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 4 का <code>Index::apply</code> अब ऐसे <code>JournalEvent::Rename</code> को, जिसका <code>old_path</code> कभी इंडेक्स ही नहीं हुआ (batches के पार की rename जोड़ी, जिसे journal subscriber जोड़ नहीं सका), <code>files.db</code> सत्य-पंक्ति के बिना Tantivy / नाम-इंडेक्स पंक्ति लिखने के बजाय <code>Delete(old) + synthetic Create(new)</code> में बदल देता है। यह journal subscribers के प्रकाशित cross-batch fallback अनुबंध की प्रतिकृति है; नया smoke <code>rename_of_unknown_path_degrades_to_delete_plus_create</code> इसे कवर करता है।","changelog.85d4a5272278":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 4 का <code>EventQueue::close</code> अब <code>wait_for_events</code> / <code>push_blocking</code> से race नहीं करता — <code>closed</code> अब किसी अलग <code>Mutex</code> के बजाय उसी <code>Mutex</code> के भीतर संग्रहीत है जिसमें queue है, इसलिए <code>close()</code> का <code>notify_all</code> किसी प्रतीक्षक की &quot;क्या queue ख़ाली है?&quot; जाँच और उसके <code>Condvar::wait</code> के बीच नहीं आ सकता। नए smoke <code>close_unblocks_push_blocking_and_wait_for_events</code> और <code>try_push_after_close_refuses</code> इस अनुबंध को पक्का करते हैं।","changelog.8096900614c3":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 4 का <code>Manifest::load_or_default</code> अब JSON-पार्स त्रुटि को <code>Index::open</code> रोक देने वाली कठोर <code>IndexError::Manifest</code> के बजाय गायब-मानो-और-चेतावनी-दो की तरह लेता है। SQLite मानक store और Tantivy <code>meta.json</code> टिकाऊ रिकॉर्ड हैं; manifest प्रति-commit कैश है, जिसे <code>Index::commit</code> हर चक्र में फिर से लिखता है। नया smoke <code>torn_manifest_does_not_block_open</code> इसे कवर करता है।","changelog.0f06a85ae4d4":"<strong>[सभी प्लेटफ़ॉर्म]</strong> चरण 4 का <code>derive_file_id</code> अब <code>to_string_lossy()</code> के बजाय सीधे <code>OsStr::as_encoded_bytes()</code> को hash करता है, ताकि केवल अमान्य-UTF-8 बाइट में भिन्न पथ एक ही id में न सिमटें। वास्तविक दुनिया में असर दुर्लभ है (Linux ext4 / Btrfs के फ़ाइल नाम मनमाने बाइट क्रम होते हैं), पर चरण 5 के <code>file_id</code> को स्थिर hash मानकर उस पर निर्भर होने से पहले यह सुधार चुपचाप होने वाले टकरावों का एक पूरा वर्ग हटा देता है।","changelog.4f8d098583e4":"<strong>[केवल Windows]</strong> चरण 1 के <code>freally-journal-win</code> में USN-journal rename जोड़ी अब rename के पुराने-नाम वाले हिस्से (और किसी भी <code>FILE_DELETE</code> रिकॉर्ड) को <strong>अंतिम</strong> मानती है: <code>USN_REASON_CLOSE</code> की प्रतीक्षा किए बिना तुरंत भेजें। NTFS पुराने-नाम वाले सत्र के लिए कोई समापन रिकॉर्ड नहीं भेजता — उस पथ पर प्रतीक्षा करने को और कुछ नहीं है। पहले classifier <code>CLOSE</code> रहित <code>RENAME_OLD_NAME</code> रिकॉर्ड के लिए <code>Pending</code> लौटाता था, जोड़ी तालिका ख़ाली रहती थी, और मेल खाता <code>RENAME_NEW_NAME | CLOSE</code> रिकॉर्ड <code>?</code> से चुपचाप गिर जाता था। कुल प्रभाव: ट्री के भीतर किसी भी rename के लिए <code>JournalEvent::Rename</code> कभी भेजा ही नहीं गया। असली NTFS वॉल्यूम पर निदान के लिए दोबारा चलाने से सुधार की पुष्टि हुई; integration टेस्ट <code>realtime_create_modify_rename_delete_round_trip</code> अब शुरू से अंत तक पास होता है और अब <code>#[ignore]</code> नहीं है।","changelog.6924516bf9eb":"<strong>[केवल Windows]</strong> <code>JournalEvent::Delete</code> अब रिकॉर्ड के <code>build_path</code> परिणाम पर लौटने से पहले FRN के आधार पर rename जोड़ी तालिका देखता है। आधुनिक Windows POSIX-अर्थ वाले <code>NtSetInformationFile</code> deletes उपयोग करता है, जो <code>FILE_DELETE</code> जारी करने से पहले फ़ाइल का नाम भीतर ही भीतर एक <code>$.dF{guid}</code> temp नाम में बदल देते हैं; इस lookup के बिना consumer को <code>Delete &lt;original_path&gt;</code> के बजाय <code>Delete $.dF{guid}</code> दिखता। बचाव के तौर पर: जिस टेस्ट ने rename बग पकड़ा, उसने यहाँ क्लासिक <code>DeleteFile</code> व्यवहार देखा, पर POSIX पथ file-locked / cross-process स्थितियों में चल सकता है।","changelog.6b2e8f83dd8e":"अप्रचलित","changelog.43e7d9ac5463":"_(ख़ाली)_"};
